export default { async fetch() { return new Response(HTML, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache" } }); } };
const HTML = "<!doctype html><html lang=\"ko\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>마주봄 AI 가이드</title><style>\n:root{--bg:#f7f7f5;--bg2:#fff;--fg:#1d2026;--muted:#5d6470;--line:#dfe2e6;--accent:#0f766e;--accent-bg:#e6f4f2;--warn:#9a3412;--warn-bg:#fff4ec;--code-bg:#f2f3f5;--easy-bg:#eef6ff;--easy:#1e4f8a}\n@media (prefers-color-scheme:dark){:root:not([data-theme=\"light\"]){--bg:#15171b;--bg2:#1d2025;--fg:#e7e9ec;--muted:#a3a9b3;--line:#30343b;--accent:#5eead4;--accent-bg:#123a36;--warn:#fdba74;--warn-bg:#3a2414;--code-bg:#111317;--easy-bg:#16263a;--easy:#9cc7ff}}\n:root[data-theme=\"dark\"]{--bg:#15171b;--bg2:#1d2025;--fg:#e7e9ec;--muted:#a3a9b3;--line:#30343b;--accent:#5eead4;--accent-bg:#123a36;--warn:#fdba74;--warn-bg:#3a2414;--code-bg:#111317;--easy-bg:#16263a;--easy:#9cc7ff}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:15px/1.65 \"Noto Sans KR\",system-ui,sans-serif}\n.wrap{max-width:1100px;margin:0 auto;padding:24px 16px 80px}h1{font-size:24px;margin:0 0 4px}h2{font-size:21px;margin:6px 0}\n.sub,.muted{color:var(--muted)}a{color:var(--accent)}code{background:var(--code-bg);padding:1px 5px;border-radius:4px;font-size:13px}\n.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:12px;margin:18px 0}\n.card{display:block;background:var(--bg2);border:1px solid var(--line);border-radius:10px;padding:14px;text-decoration:none;color:var(--fg)}\n.card:hover{border-color:var(--accent)}.card b{display:block;font-size:16px;margin-bottom:4px}.card span{color:var(--muted);font-size:13px}\n.part-head{border-bottom:1px solid var(--line);margin-bottom:14px;padding-bottom:8px}.back{font-size:13px;text-decoration:none}\n.easy{background:var(--easy-bg);color:var(--fg);border-left:4px solid var(--easy);padding:12px 14px;border-radius:6px;margin:12px 0}.easy b{color:var(--easy);margin-right:6px}\n.warn{background:var(--warn-bg);border-left:4px solid var(--warn);padding:10px 14px;border-radius:6px;margin:12px 0}.warn b{color:var(--warn);margin-right:6px}\n.cite{font-size:12.5px;color:var(--muted);border-top:1px dashed var(--line);margin-top:14px;padding-top:8px}\ndetails.step{background:var(--bg2);border:1px solid var(--line);border-radius:10px;margin:10px 0;padding:0 14px}\ndetails.step>summary{cursor:pointer;padding:12px 0;font-weight:700;font-size:16px;list-style:none}details.step>summary::-webkit-details-marker{display:none}\ndetails.step>summary:before{content:\"▸\";color:var(--accent);margin-right:8px}details.step[open]>summary:before{content:\"▾\"}\n.num{display:inline-block;background:var(--accent-bg);color:var(--accent);border-radius:6px;padding:0 7px;margin-right:8px;font-size:13px}\n.plain{padding-bottom:6px}.detail{background:var(--code-bg);border-radius:8px;padding:8px 14px;margin:8px 0;font-size:14px}.detail-h{font-weight:700;font-size:13px;color:var(--muted)}\n.formula{font-family:\"JetBrains Mono\",ui-monospace,monospace;font-size:13.5px;background:var(--accent-bg);border-radius:8px;padding:10px 14px;margin:10px 0;overflow-x:auto}\ndetails.code{margin:8px 0 12px;border:1px solid var(--line);border-radius:8px;background:var(--code-bg)}\ndetails.code>summary{cursor:pointer;padding:8px 12px;font-size:13.5px}.code-tag{background:var(--accent);color:var(--bg2);border-radius:4px;padding:0 6px;font-size:12px;margin-right:4px}\n.code-loc{color:var(--muted);font-size:12px;margin-left:6px}.code-note{padding:0 12px;font-size:13px;color:var(--muted)}\npre{margin:0;padding:10px 12px;overflow-x:auto;font:12.5px/1.5 \"JetBrains Mono\",ui-monospace,monospace;white-space:pre}.ln{color:var(--muted);user-select:none;margin-right:12px;opacity:.6}\npre.sample{background:var(--code-bg);border-radius:8px;margin:8px 0}\ntable{border-collapse:collapse;width:100%;margin:10px 0;font-size:13.5px;display:block;overflow-x:auto}th,td{border:1px solid var(--line);padding:6px 8px;text-align:left;vertical-align:top}th{background:var(--code-bg)}\n.flowline{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:8px 0;font-size:13px}.flowline span{background:var(--bg2);border:1px solid var(--line);border-radius:999px;padding:3px 10px}\n.ref{font-family:ui-monospace,monospace;font-size:12.5px}.top{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;align-items:flex-start}\n#theme,#openall{background:var(--bg2);color:var(--fg);border:1px solid var(--line);border-radius:8px;padding:4px 10px;cursor:pointer}\n</style></head><body><div class=\"wrap\">\n<div class=\"top\"><div><h1>마주봄 AI 가이드 — 학습 모델·예측·LLM 리포트</h1><div class=\"muted\">신입 개발자용 코드 읽기 안내 · 생성 2026-10-21 · tools/build_ai_guide.py · 코드 조각은 생성 시점 소스에서 직접 잘라 옴</div></div>\n<div><button id=\"openall\" type=\"button\">이 파트 전부 펼치기</button> <button id=\"theme\" type=\"button\">밝게/어둡게</button></div></div>\n<div id=\"home\"><p>마주봄에서 'AI'라고 부르는 부분을 <b>무엇을 배우나(학습 모델) · 무엇을 예측하나(통계) · 무엇을 쓰나(LLM)</b>로 나눠 정리했다.\n파트를 누르면 그 파트만 펼쳐지고, 단계마다 <b>쉬운 설명 → 엔지니어 메모·수식 → 실제 코드(줄 번호)</b> 순서다. 처음이면 <b>0. AI 지도</b>부터 읽는다.</p>\n<div class=\"cards\"><a class=\"card\" href=\"#map\"><b>0. AI 지도</b><span>학습 모델·통계·LLM·규칙 구분, 제1원칙</span></a><a class=\"card\" href=\"#posture\"><b>1. 자세 분류</b><span>Random Forest · 정직한 정확도(LOSO)</span></a><a class=\"card\" href=\"#anomaly\"><b>2. 움직임 이상 탐지</b><span>LSTM 오토인코더(참고값)</span></a><a class=\"card\" href=\"#prior\"><b>3. 보행 기대 범위</b><span>문헌 + LLM 인용 검증</span></a><a class=\"card\" href=\"#trend\"><b>4. 보행 저하 예측</b><span>칼만 필터 · Phillips 2017 기준</span></a><a class=\"card\" href=\"#search\"><b>5. 근거 찾기</b><span>검색어 생성 · 벡터+BM25+RRF · EMR</span></a><a class=\"card\" href=\"#report\"><b>6. AI 종합 리포트</b><span>서버 계산 · 프롬프트 규칙 · 검증</span></a><a class=\"card\" href=\"#fall\"><b>7. 낙상 사건 리포트·검토</b><span>규칙 원인 후보 · 자동 검토</span></a><a class=\"card\" href=\"#lab\"><b>8. 실험 코드</b><span>아직 운영에 안 쓰는 것</span></a><a class=\"card\" href=\"#ops\"><b>9. 실행·시험</b><span>다시 학습·테스트·체크리스트</span></a></div></div>\n<section class=\"part\" id=\"map\" hidden><div class=\"part-head\"><a href=\"#home\" class=\"back\">← 전체 지도</a><h2>0. AI 지도 — 무엇이 진짜 '학습'이고 무엇이 계산·규칙인가</h2><p class=\"sub\">처음 읽는 사람이 헷갈리지 않게 종류별로 나눔</p></div>\n<div class=\"easy\"><b>쉽게 말하면</b> 마주봄의 'AI'는 한 덩어리가 아니다. ① 데이터를 보고 <b>스스로 배우는 모델</b>(자세 분류·이상 탐지), ② 공식으로 <b>미래를 추정하는 통계</b>(보행 저하 예측·보행 기대 범위), ③ 글을 읽고 <b>문장을 쓰는 LLM</b>(리포트·검색어·기록 판단), ④ 사람이 정한 <b>규칙</b>(낙상 감지·뒤척임·위험 점수)으로 나뉜다. 숫자(점수·확률·예측)는 ①②④가 만들고, LLM은 그 숫자를 <b>설명만</b> 한다 — 이것이 이 프로젝트의 제1원칙이다.</div>\n<table><thead><tr><th>이름</th><th>종류</th><th>입력 → 출력</th><th>코드</th><th>운영에 쓰이나</th></tr></thead><tbody><tr><td>자세 분류</td><td>학습 모델(Random Forest 200그루)</td><td>ToF 128칸 거리 → 6가지 자세</td><td><a class=\"ref\" href=\"../TOF/ml/train_posture_v2.py\" title=\"TOF/ml/train_posture_v2.py\">TOF/ml/train_posture_v2.py</a></td><td>✅ 매 프레임</td></tr><tr><td>움직임 이상 탐지</td><td>학습 모델(LSTM 오토인코더)</td><td>4초 움직임 특징 → 재구성 오차</td><td><a class=\"ref\" href=\"../TOF/ml/tof_anomaly.py\" title=\"TOF/ml/tof_anomaly.py\">TOF/ml/tof_anomaly.py</a></td><td>참고값만(판정에 안 씀)</td></tr><tr><td>보행 기대 범위</td><td>통계 + LLM 보조 판단</td><td>입원 기록·나이·키 → 기대 보행속도 범위</td><td><a class=\"ref\" href=\"../server/gait_prior.py\" title=\"server/gait_prior.py\">server/gait_prior.py</a></td><td>✅ 기록 5일 전 잠정 판정</td></tr><tr><td>보행 저하 예측</td><td>통계(칼만 필터)</td><td>하루 보행값 → 7·14일 뒤 예측·감소 확률</td><td><a class=\"ref\" href=\"../server/gait_trend.py\" title=\"server/gait_trend.py\">server/gait_trend.py</a></td><td>✅ 14일 기록부터</td></tr><tr><td>논문 검색</td><td>임베딩 + BM25 + RRF</td><td>검색어 → 근거 논문 조각(논문 73편·조각 631개)</td><td><a class=\"ref\" href=\"../server/paper_kb.py\" title=\"server/paper_kb.py\">server/paper_kb.py</a></td><td>✅ 리포트 작성 때</td></tr><tr><td>환자 기록 검색</td><td>어휘 해시 벡터(신경망 아님)</td><td>검색어 → 그 환자 EMR 조각</td><td><a class=\"ref\" href=\"../server/emr_kb.py\" title=\"server/emr_kb.py\">server/emr_kb.py</a></td><td>✅ 리포트 작성 때</td></tr><tr><td>AI 종합 리포트</td><td>LLM(gpt-4o-mini)</td><td>계산된 사실·근거 → 15개 항목 문장</td><td><a class=\"ref\" href=\"../server/integrated_analysis.py\" title=\"server/integrated_analysis.py\">server/integrated_analysis.py</a></td><td>✅ 매주 + 버튼</td></tr><tr><td>낙상 사건 리포트</td><td>규칙 + LLM</td><td>낙상 순간 사실 → 원인 후보·조치 문장</td><td><a class=\"ref\" href=\"../server/fall_report.py\" title=\"server/fall_report.py\">server/fall_report.py</a></td><td>✅ 낙상 감지 직후</td></tr><tr><td>리포트 자동 검토</td><td>규칙(LLM 없음)</td><td>저장된 리포트 → 점검 결과</td><td><a class=\"ref\" href=\"../server/report_review.py\" title=\"server/report_review.py\">server/report_review.py</a></td><td>✅ 리포트마다</td></tr><tr><td>낙상 감지·뒤척임·위험 점수</td><td>규칙(학습 없음)</td><td>레이더 높이·ToF 모양 → 사건</td><td>mmWave/fall_detect.py · <a class=\"ref\" href=\"../server/tof_toss.py\" title=\"server/tof_toss.py\">server/tof_toss.py</a></td><td>✅ (AI 아님 — 코드 가이드 참고)</td></tr><tr><td>변화 감시(ADWIN)·과거 리포트 검색</td><td>실험</td><td>—</td><td><a class=\"ref\" href=\"../server/maintenance_ai.py\" title=\"server/maintenance_ai.py\">server/maintenance_ai.py</a> · <a class=\"ref\" href=\"../server/analysis_kb.py\" title=\"server/analysis_kb.py\">server/analysis_kb.py</a></td><td>❌ 운영 경로에 연결 안 됨</td></tr></tbody></table>\n<details class=\"step\"><summary><span class=\"num\">0-1</span>제1원칙: 숫자는 서버, 문장은 LLM</summary><div class=\"plain\"><p>LLM은 그럴듯한 숫자를 지어낼 수 있다. 그래서 위험 점수·예측값·확률은 모두 서버 코드가 계산하고, LLM 프롬프트에는 '주어진 수치를 바꾸거나 새로 만들지 말라'를 넣는다. LLM 응답은 형식 검사를 통과해야 저장되고, 저장 뒤에도 규칙 검토(10장)를 받는다.</p></div><div class=\"detail\"><div class=\"detail-h\">엔지니어 메모</div><p>키가 없거나 호출이 실패하면 가짜 결과를 만들지 않고 <code>{success: False, error_type, message}</code>를 돌려준다('정직한 실패'). 모든 LLM 호출은 <a class=\"ref\" href=\"../server/ai_report.py\" title=\"server/ai_report.py\">server/ai_report.py:93</a> 하나를 거친다.</p></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> call_openai() — 모든 LLM 호출의 관문 <span class=\"code-loc\">server/ai_report.py:92–160</span></summary><pre><span class=\"ln\"> 92</span>@report_trace.traced_stage(&#x27;llm_call&#x27;, &#x27;실제 LLM 요청·응답&#x27;)\n<span class=\"ln\"> 93</span>def call_openai(payload: dict = None, model: str = DEFAULT_MODEL, timeout: float = 30.0,\n<span class=\"ln\"> 94</span>                 system_prompt: str | None = None, user_content: str | None = None,\n<span class=\"ln\"> 95</span>                 json_mode: bool = False) -&gt; dict:\n<span class=\"ln\"> 96</span>    &quot;&quot;&quot;OpenAI Chat Completions 호출. 하위호환: payload만 주면 기존 주간리포트 방식대로\n<span class=\"ln\"> 97</span>    SYSTEM_PROMPT + payload를 JSON 문자열로 넣어 호출한다. system_prompt/user_content를\n<span class=\"ln\"> 98</span>    주면(paper_kb 질의생성, ai_agent, integrated_analysis 등) 그걸 그대로 쓴다.\n<span class=\"ln\"> 99</span>    json_mode=True면 OpenAI의 JSON 강제 응답 모드를 켠다.\n<span class=\"ln\">100</span>\n<span class=\"ln\">101</span>    반환: {&quot;success&quot;: True, &quot;text&quot;: str, &quot;model&quot;: str, &quot;usage&quot;: dict|None}\n<span class=\"ln\">102</span>    또는 {&quot;success&quot;: False, &quot;error_type&quot;: str, &quot;message&quot;: str}&quot;&quot;&quot;\n<span class=\"ln\">103</span>    key = get_api_key()\n<span class=\"ln\">104</span>    if not key:\n<span class=\"ln\">105</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;missing_key&quot;,\n<span class=\"ln\">106</span>                &quot;message&quot;: &quot;.env 또는 환경변수에 OPENAI_API_KEY가 설정되어 있지 않습니다. &quot;\n<span class=\"ln\">107</span>                           &quot;코드 문제가 아니라 키 미설정입니다.&quot;}\n<span class=\"ln\">108</span>\n<span class=\"ln\">109</span>    if system_prompt is None:\n<span class=\"ln\">110</span>        system_prompt = SYSTEM_PROMPT\n<span class=\"ln\">111</span>    if user_content is None:\n<span class=\"ln\">112</span>        user_content = (&quot;다음은 이미 계산된 사실입니다. 이 사실만으로 리포트를 작성하세요.\\n\\n&quot;\n<span class=\"ln\">113</span>                         + json.dumps(payload, ensure_ascii=False, indent=2, default=str))\n<span class=\"ln\">114</span>\n<span class=\"ln\">115</span>    body = {\n<span class=\"ln\">116</span>        &quot;model&quot;: model,\n<span class=\"ln\">117</span>        &quot;messages&quot;: [\n<span class=\"ln\">118</span>            {&quot;role&quot;: &quot;system&quot;, &quot;content&quot;: system_prompt},\n<span class=\"ln\">119</span>            {&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: user_content},\n<span class=\"ln\">120</span>        ],\n<span class=\"ln\">121</span>        &quot;temperature&quot;: 0.3,\n<span class=\"ln\">122</span>    }\n<span class=\"ln\">123</span>    if json_mode:\n<span class=\"ln\">124</span>        body[&quot;response_format&quot;] = {&quot;type&quot;: &quot;json_object&quot;}\n<span class=\"ln\">125</span>\n<span class=\"ln\">126</span>    try:\n<span class=\"ln\">127</span>        resp = requests.post(\n<span class=\"ln\">128</span>            OPENAI_URL,\n<span class=\"ln\">129</span>            headers={&quot;Authorization&quot;: f&quot;Bearer {key}&quot;, &quot;Content-Type&quot;: &quot;application/json&quot;},\n<span class=\"ln\">130</span>            json=body, timeout=timeout,\n<span class=\"ln\">131</span>        )\n<span class=\"ln\">132</span>    except requests.exceptions.Timeout:\n<span class=\"ln\">133</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;timeout&quot;,\n<span class=\"ln\">134</span>                &quot;message&quot;: f&quot;OpenAI API 응답 시간 초과({timeout}s).&quot;}\n<span class=\"ln\">135</span>    except requests.exceptions.ConnectionError:\n<span class=\"ln\">136</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;network&quot;,\n<span class=\"ln\">137</span>                &quot;message&quot;: &quot;OpenAI API 연결 실패 — 네트워크/방화벽 문제일 가능성이 높습니다.&quot;}\n<span class=\"ln\">138</span>    except requests.exceptions.RequestException as e:\n<span class=\"ln\">139</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;request_error&quot;,\n<span class=\"ln\">140</span>                &quot;message&quot;: f&quot;요청 중 예외 발생: {type(e).__name__}&quot;}\n<span class=\"ln\">141</span>\n<span class=\"ln\">142</span>    if resp.status_code == 401:\n<span class=\"ln\">143</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;auth&quot;,\n<span class=\"ln\">144</span>                &quot;message&quot;: &quot;인증 실패(401) — API 키가 비어있거나 유효하지 않습니다.&quot;}\n<span class=\"ln\">145</span>    if resp.status_code == 429:\n<span class=\"ln\">146</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;rate_limit&quot;,\n<span class=\"ln\">147</span>                &quot;message&quot;: &quot;요청 한도 초과(429) — 크레딧/쿼터 문제일 수 있습니다.&quot;}\n<span class=\"ln\">148</span>    if resp.status_code != 200:\n<span class=\"ln\">149</span>        snippet = resp.text[:300] if resp.text else &quot;&quot;\n<span class=\"ln\">150</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: f&quot;http_{resp.status_code}&quot;,\n<span class=\"ln\">151</span>                &quot;message&quot;: f&quot;OpenAI API 오류 응답: {snippet}&quot;}\n<span class=\"ln\">152</span>\n<span class=\"ln\">153</span>    try:\n<span class=\"ln\">154</span>        data = resp.json()\n<span class=\"ln\">155</span>        text = data[&quot;choices&quot;][0][&quot;message&quot;][&quot;content&quot;]\n<span class=\"ln\">156</span>    except (KeyError, IndexError, ValueError, json.JSONDecodeError) as e:\n<span class=\"ln\">157</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;parse_error&quot;,\n<span class=\"ln\">158</span>                &quot;message&quot;: f&quot;응답 파싱 실패: {type(e).__name__}&quot;}\n<span class=\"ln\">159</span>\n<span class=\"ln\">160</span>    return {&quot;success&quot;: True, &quot;text&quot;: text, &quot;model&quot;: model, &quot;usage&quot;: data.get(&quot;usage&quot;)}</pre></details></details>\n<details class=\"step\"><summary><span class=\"num\">0-2</span>외부로 나가는 것과 안 나가는 것</summary><div class=\"plain\"><table><thead><tr><th>처리</th><th>어디서</th></tr></thead><tbody><tr><td>자세 분류·이상 탐지·보행 예측·낙상 감지</td><td>Pi 안에서만(인터넷 불필요)</td></tr><tr><td>리포트 문장·검색어·기록 판단</td><td>OpenAI API(키: 루트 .env, 저장소 제외)</td></tr><tr><td>논문·검색어 임베딩</td><td>OpenAI 임베딩 API(text-embedding-3-small)</td></tr><tr><td>환자 기록(EMR) 벡터</td><td>Pi 안에서만(해시 벡터 — 외부 전송 없음)</td></tr></tbody></table></div><div class=\"detail\"><div class=\"detail-h\">엔지니어 메모</div><p>2026-10-13부터 실측 낙상이 나면 사건 리포트를 자동 요청한다 → 그 순간의 사건 수치·투약·위험 요인이 OpenAI로 간다. 실제 환자 운영 전에 이 자동 전송을 계속할지 정해야 한다.</p></div></details>\n</section><section class=\"part\" id=\"posture\" hidden><div class=\"part-head\"><a href=\"#home\" class=\"back\">← 전체 지도</a><h2>1. 자세 분류 — Random Forest</h2><p class=\"sub\">ToF 128칸 거리로 누움·옆으로·앉음·걸터앉음·빈 침대 구분</p></div>\n<div class=\"easy\"><b>쉽게 말하면</b> 침대 머리·발쪽 ToF 두 개가 각각 8×8=64칸 거리를 잰다. 합친 128개 숫자를 보고 '예/아니오 질문 나무' 200그루가 각자 자세를 고르고, 다수결(확률 평균)로 정한다. 나무 하나는 '발쪽 37번 칸이 900mm보다 가까운가?' 같은 질문을 10여 번 잇는다.</div>\n<details class=\"step\"><summary><span class=\"num\">1-1</span>학습 데이터</summary><div class=\"plain\"><table><thead><tr><th>항목</th><th>값</th></tr></thead><tbody><tr><td>녹화 도구</td><td><a class=\"ref\" href=\"../TOF/record_posture.py\" title=\"TOF/record_posture.py\">TOF/record_posture.py</a> — 30초 녹화 × 회차, 자세 이름이 파일에 같이 저장</td></tr><tr><td>사람</td><td>S01(10-08, 79회차) · S02(10-13, 102회차, 담요 15회차 포함) · 빈 침대 17회차</td></tr><tr><td>클래스(프레임 쌍 수)</td><td>edge_sit 5869, side_left 5773, side_right 6087, sitting 5922, supine 7979, empty 3559</td></tr><tr><td>전처리</td><td>두 센서 프레임을 시각 250ms 안으로 짝짓기 · 회차 앞뒤 1초 제외 · 침대 밖 칸은 -1(ROI)</td></tr></tbody></table></div><div class=\"detail\"><div class=\"detail-h\">엔지니어 메모</div><p>한 프레임 = 한 샘플이라 같은 회차 안 프레임끼리는 거의 같다. 그래서 '회차/사람 단위로 빼고 시험'해야 정직하다(아래 1-3).</p></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> load() — 녹화 파일 → (128칸, 라벨) <span class=\"code-loc\">TOF/ml/train_posture_v2.py:47–71</span></summary><pre><span class=\"ln\">47</span>def load(use_roi):\n<span class=\"ln\">48</span>    X, meta = [], []\n<span class=\"ln\">49</span>    for f in sorted(glob.glob(os.path.join(DDIR, &quot;tof_*.jsonl&quot;))):\n<span class=\"ln\">50</span>        rows = [json.loads(l) for l in open(f, encoding=&quot;utf-8&quot;)]\n<span class=\"ln\">51</span>        if not rows:\n<span class=\"ln\">52</span>            continue\n<span class=\"ln\">53</span>        t0, t1 = min(_ts(r[&quot;t&quot;]) for r in rows), max(_ts(r[&quot;t&quot;]) for r in rows)\n<span class=\"ln\">54</span>        a = sorted((_ts(r[&quot;t&quot;]), _clean(r[&quot;distances_mm&quot;])) for r in rows if r[&quot;sensor&quot;] == &quot;tof1&quot;)\n<span class=\"ln\">55</span>        b = sorted((_ts(r[&quot;t&quot;]), _clean(r[&quot;distances_mm&quot;])) for r in rows if r[&quot;sensor&quot;] == &quot;tof2&quot;)\n<span class=\"ln\">56</span>        j, used = 0, set()\n<span class=\"ln\">57</span>        for t, d1 in a:\n<span class=\"ln\">58</span>            if t &lt; t0 + TRIM_SEC or t &gt; t1 - TRIM_SEC or not b:\n<span class=\"ln\">59</span>                continue\n<span class=\"ln\">60</span>            while j + 1 &lt; len(b) and abs(b[j + 1][0] - t) &lt;= abs(b[j][0] - t):\n<span class=\"ln\">61</span>                j += 1\n<span class=\"ln\">62</span>            if j in used or abs(b[j][0] - t) &gt; PAIR_SEC:\n<span class=\"ln\">63</span>                continue\n<span class=\"ln\">64</span>            used.add(j)\n<span class=\"ln\">65</span>            d2 = b[j][1]\n<span class=\"ln\">66</span>            if use_roi:\n<span class=\"ln\">67</span>                d1, d2 = roi.mask_offbed(&quot;tof1&quot;, d1), roi.mask_offbed(&quot;tof2&quot;, d2)\n<span class=\"ln\">68</span>            X.append(d1 + d2)\n<span class=\"ln\">69</span>            r0 = rows[0]\n<span class=\"ln\">70</span>            meta.append({k: r0.get(k) for k in (&quot;label&quot;, &quot;subject&quot;, &quot;cond&quot;, &quot;rep&quot;, &quot;session&quot;)})\n<span class=\"ln\">71</span>    return np.array(X, float), meta</pre></details><details class=\"code\"><summary><span class=\"code-tag\">코드</span> roi.mask_offbed() — 침대 밖 칸 지우기 <span class=\"code-loc\">TOF/ml/roi.py:79–81</span></summary><pre><span class=\"ln\">79</span>def mask_offbed(sensor_id, distances):\n<span class=\"ln\">80</span>    &quot;&quot;&quot;침대 폭 밖 존은 -1(무효)로. distances: list[int].&quot;&quot;&quot;\n<span class=\"ln\">81</span>    return [d if on_bed(sensor_id, z, d) else -1 for z, d in enumerate(distances)]</pre></details></details>\n<details class=\"step\"><summary><span class=\"num\">1-2</span>모델과 학습</summary><div class=\"plain\"><div class=\"formula\">RandomForestClassifier(n_estimators=200, class_weight='balanced')<br>나무마다: 데이터를 복원추출로 다시 뽑고(bootstrap), 갈림마다 √128≈11개 칸만 후보로 → 서로 다른 나무 200그루<br>예측 확률 = 200그루가 각 자세에 준 표의 비율 = '확신도'</div></div><div class=\"detail\"><div class=\"detail-h\">엔지니어 메모</div><p>현재 운영 모델: 사람 ['S01', 'S02', '없음'], 학습 2026-10-20T13:10:49, 나무 200그루, ROI True. 이전 모델(S01만)은 TOF/ml/archive/에 보관.</p><p>class_weight='balanced': 바로 누움이 많고 빈 침대가 적어도 클래스마다 같은 무게로 배우게 한다.</p></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> make_model() <span class=\"code-loc\">TOF/ml/train_posture_v2.py:83–84</span></summary><pre><span class=\"ln\">83</span>def make_model():\n<span class=\"ln\">84</span>    return RandomForestClassifier(n_estimators=200, class_weight=&quot;balanced&quot;, n_jobs=-1, random_state=0)</pre></details><details class=\"code\"><summary><span class=\"code-tag\">코드</span> main() — 평가 후 전체로 다시 학습·저장 <span class=\"code-loc\">TOF/ml/train_posture_v2.py:87–135</span></summary><pre><span class=\"ln\"> 87</span>def main():\n<span class=\"ln\"> 88</span>    ap = argparse.ArgumentParser()\n<span class=\"ln\"> 89</span>    ap.add_argument(&quot;--group&quot;, choices=[&quot;rep&quot;, &quot;subject&quot;], default=&quot;rep&quot;)\n<span class=\"ln\"> 90</span>    ap.add_argument(&quot;--no-roi&quot;, action=&quot;store_true&quot;)\n<span class=\"ln\"> 91</span>    ap.add_argument(&quot;--no-save&quot;, action=&quot;store_true&quot;)\n<span class=\"ln\"> 92</span>    args = ap.parse_args()\n<span class=\"ln\"> 93</span>\n<span class=\"ln\"> 94</span>    X, meta = load(not args.no_roi)\n<span class=\"ln\"> 95</span>    y = np.array([m[&quot;label&quot;] for m in meta])\n<span class=\"ln\"> 96</span>    g = groups_for(meta, args.group)\n<span class=\"ln\"> 97</span>    print(f&quot;샘플 {len(y)}쌍, 클래스 {dict(collections.Counter(y))}, 묶음({args.group}) {sorted(set(g.tolist()))}&quot;)\n<span class=\"ln\"> 98</span>\n<span class=\"ln\"> 99</span>    pred = np.empty(len(y), dtype=object)\n<span class=\"ln\">100</span>    folds = []\n<span class=\"ln\">101</span>    for k in sorted(set(g.tolist())):\n<span class=\"ln\">102</span>        tr, te = g != k, g == k\n<span class=\"ln\">103</span>        if len(set(y[tr])) &lt; 2 or te.sum() == 0:\n<span class=\"ln\">104</span>            continue\n<span class=\"ln\">105</span>        p = make_model().fit(X[tr], y[tr]).predict(X[te])\n<span class=\"ln\">106</span>        pred[te] = p\n<span class=\"ln\">107</span>        folds.append({&quot;held_out&quot;: int(k), &quot;n&quot;: int(te.sum()), &quot;accuracy&quot;: accuracy_score(y[te], p),\n<span class=\"ln\">108</span>                      &quot;macro_f1&quot;: f1_score(y[te], p, average=&quot;macro&quot;)})\n<span class=\"ln\">109</span>        print(f&quot;  묶음 {k} 시험: 정확도 {folds[-1][&#x27;accuracy&#x27;]:.3f}, macro-F1 {folds[-1][&#x27;macro_f1&#x27;]:.3f}&quot;)\n<span class=\"ln\">110</span>    done = np.array([p is not None for p in pred])\n<span class=\"ln\">111</span>    labels = [l for l in LABELS if l in set(y)]\n<span class=\"ln\">112</span>    cm = confusion_matrix(y[done], pred[done], labels=labels)\n<span class=\"ln\">113</span>    print(&quot;혼동행렬(행=정답, 열=예측):&quot;, labels)\n<span class=\"ln\">114</span>    print(cm)\n<span class=\"ln\">115</span>\n<span class=\"ln\">116</span>    report = {&quot;trained_at&quot;: datetime.now().isoformat(timespec=&quot;seconds&quot;), &quot;group&quot;: args.group, &quot;roi&quot;: not args.no_roi,\n<span class=\"ln\">117</span>              &quot;n_pairs&quot;: int(len(y)), &quot;class_counts&quot;: dict(collections.Counter(y.tolist())),\n<span class=\"ln\">118</span>              &quot;subjects&quot;: sorted({m[&quot;subject&quot;] for m in meta}), &quot;folds&quot;: folds,\n<span class=\"ln\">119</span>              &quot;overall_accuracy&quot;: accuracy_score(y[done], pred[done]) if done.any() else None,\n<span class=\"ln\">120</span>              &quot;confusion_labels&quot;: labels, &quot;confusion&quot;: cm.tolist(),\n<span class=\"ln\">121</span>              &quot;mount&quot;: {&quot;height_m&quot;: 1.2, &quot;down_tilt_deg&quot;: {&quot;tof1_foot&quot;: 50, &quot;tof2_head&quot;: 30}},\n<span class=\"ln\">122</span>              &quot;note&quot;: &quot;회차 단위 평가는 같은 사람·같은 날이라 일반화 성능이 아니다. 사람 단위(LOSO)가 기준.&quot;}\n<span class=\"ln\">123</span>    with open(os.path.join(HERE, &quot;posture_model_v2_report.json&quot;), &quot;w&quot;, encoding=&quot;utf-8&quot;) as f:\n<span class=\"ln\">124</span>        json.dump(report, f, ensure_ascii=False, indent=2)\n<span class=\"ln\">125</span>\n<span class=\"ln\">126</span>    if args.no_save:\n<span class=\"ln\">127</span>        return\n<span class=\"ln\">128</span>    clf = make_model().fit(X, y)\n<span class=\"ln\">129</span>    out = os.path.join(HERE, &quot;posture_model.joblib&quot;)\n<span class=\"ln\">130</span>    joblib.dump({&quot;model&quot;: clf, &quot;labels&quot;: sorted(set(y)), &quot;zones&quot;: ZONES,\n<span class=\"ln\">131</span>                 &quot;features&quot;: &quot;tof1_d0..63 + tof2_d0..63 (mm, -1=무효)&quot;, &quot;filtered&quot;: False,\n<span class=\"ln\">132</span>                 &quot;roi&quot;: not args.no_roi, &quot;version&quot;: &quot;v2&quot;, &quot;dataset&quot;: &quot;TOF/dataset_v2&quot;,\n<span class=\"ln\">133</span>                 &quot;subjects&quot;: report[&quot;subjects&quot;], &quot;trained_at&quot;: report[&quot;trained_at&quot;],\n<span class=\"ln\">134</span>                 &quot;mount&quot;: report[&quot;mount&quot;]}, out)\n<span class=\"ln\">135</span>    print(f&quot;모델 저장: {out}&quot;)</pre></details></details>\n<details class=\"step\"><summary><span class=\"num\">1-3</span>정확도 — 정직하게 읽기</summary><div class=\"plain\"><table><thead><tr><th>시험 방식</th><th>정확도</th><th>macro-F1</th><th>샘플</th></tr></thead><tbody><tr><td>S01 시험(S02로 학습)</td><td>58.2%</td><td>0.522</td><td>16735</td></tr><tr><td>S02 시험(S01로 학습)</td><td>73.0%</td><td>0.724</td><td>18454</td></tr></tbody></table><p>혼동행렬(행=정답, 열=예측, 두 시험 합계):</p><table><thead><tr><th>정답 \\ 예측</th><th>empty</th><th>supine</th><th>side_left</th><th>side_right</th><th>sitting</th><th>edge_sit</th></tr></thead><tbody><tr><td>empty</td><td>3559</td><td>0</td><td>0</td><td>0</td><td>0</td><td>0</td></tr><tr><td>supine</td><td>193</td><td>6871</td><td>914</td><td>1</td><td>0</td><td>0</td></tr><tr><td>side_left</td><td>0</td><td>1291</td><td>4343</td><td>139</td><td>0</td><td>0</td></tr><tr><td>side_right</td><td>367</td><td>1854</td><td>2819</td><td>1047</td><td>0</td><td>0</td></tr><tr><td>sitting</td><td>17</td><td>0</td><td>1</td><td>0</td><td>5079</td><td>825</td></tr><tr><td>edge_sit</td><td>2427</td><td>136</td><td>19</td><td>137</td><td>837</td><td>2313</td></tr></tbody></table></div><div class=\"detail\"><div class=\"detail-h\">엔지니어 메모</div><p><b>같은 사람의 다른 회차로 시험하면 100%</b>가 나온다(같은 날·같은 몸). 이건 성능이 아니다. 기준은 '한 사람으로 배우고 다른 사람으로 시험(LOSO)'이고, 한 사람만 배운 모델은 처음 보는 사람에게 58~73%였다. 주된 혼동: 오른쪽↔왼쪽 누움(화면은 '옆으로 누움' 하나로 표시), 걸터앉음→빈 침대(두 사람이 앉은 위치가 달랐음 — ROI를 꺼도 같아 ROI 탓 아님). 지금 모델은 두 사람을 다 배웠으므로 <b>세 번째 사람 기준 정확도는 아직 모른다</b> — 새 사람 데이터는 먼저 시험용으로 쓴다.</p></div></details>\n<details class=\"step\"><summary><span class=\"num\">1-4</span>실시간 추론과 화면용 다듬기</summary><div class=\"plain\"><p>서버가 새 프레임마다 128칸을 만들어 모델에 넣는다. 사람 칸(빈 침대 기준보다 15cm 이상 가까운 칸)이 하나도 없으면 모델 결과를 무시하고 '빈 침대'로 확정한다(빈 침대를 걸터앉음으로 잘못 보는 것 방지).</p></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> frame_vec() — 실시간 128칸 만들기 <span class=\"code-loc\">TOF/ml/predict_posture.py:41–50</span></summary><pre><span class=\"ln\">41</span>def frame_vec(latest):\n<span class=\"ln\">42</span>    &quot;&quot;&quot;latest = {&quot;tof1&quot;:{&quot;distances_mm&quot;:[..]}, &quot;tof2&quot;:{...}} → 128차원 벡터(없으면 None).\n<span class=\"ln\">43</span>    학습과 동일하게 침대 밖 존은 ROI로 -1 처리.&quot;&quot;&quot;\n<span class=\"ln\">44</span>    t1 = (latest.get(&quot;tof1&quot;) or {}).get(&quot;distances_mm&quot;)\n<span class=\"ln\">45</span>    t2 = (latest.get(&quot;tof2&quot;) or {}).get(&quot;distances_mm&quot;)\n<span class=\"ln\">46</span>    if not t1 or not t2:\n<span class=\"ln\">47</span>        return None\n<span class=\"ln\">48</span>    d1 = roi.mask_offbed(&quot;tof1&quot;, _pad(t1))\n<span class=\"ln\">49</span>    d2 = roi.mask_offbed(&quot;tof2&quot;, _pad(t2))\n<span class=\"ln\">50</span>    return np.array(d1 + d2).reshape(1, -1)</pre></details><details class=\"code\"><summary><span class=\"code-tag\">코드</span> predict() <span class=\"code-loc\">TOF/ml/predict_posture.py:53–60</span></summary><pre><span class=\"ln\">53</span>def predict(model, latest):\n<span class=\"ln\">54</span>    &quot;&quot;&quot;(label, confidence) 반환. 데이터 없으면 (None, None).&quot;&quot;&quot;\n<span class=\"ln\">55</span>    v = frame_vec(latest)\n<span class=\"ln\">56</span>    if v is None:\n<span class=\"ln\">57</span>        return None, None\n<span class=\"ln\">58</span>    proba = model.predict_proba(v)[0]\n<span class=\"ln\">59</span>    i = int(np.argmax(proba))\n<span class=\"ln\">60</span>    return str(model.classes_[i]), float(proba[i])</pre></details></details>\n<div class=\"warn\"><b>한계·주의</b> 이불·체형·설치 각도가 학습 때와 다르면 정확도가 떨어진다. 설치 장소를 옮기면 빈 침대 기준을 다시 잡고(/dev 버튼), 센서 각도(발 50°·머리 30°)를 그대로 맞춘다.</div>\n<div class=\"cite\">Breiman L. Random Forests. Machine Learning 2001;45:5–32.</div>\n</section><section class=\"part\" id=\"anomaly\" hidden><div class=\"part-head\"><a href=\"#home\" class=\"back\">← 전체 지도</a><h2>2. 움직임 이상 탐지 — LSTM 오토인코더(참고값)</h2><p class=\"sub\">평소 움직임을 다시 그려 보고, 못 그리면 '평소와 다름'</p></div>\n<div class=\"easy\"><b>쉽게 말하면</b> 평소(정상) 4초 움직임만 보여 주며 '그대로 다시 그리기'를 연습시킨 모델이다. 처음 보는 이상한 움직임은 잘 못 그려서 오차가 커진다. 그 오차가 기준보다 크면 '평소와 다른 움직임'. 무엇이 이상한지는 알려 주지 않고, 지금은 판정에 쓰지 않는 참고값이다.</div>\n<details class=\"step\"><summary><span class=\"num\">2-1</span>입력 특징 12개(프레임마다)</summary><div class=\"plain\"><p>사람 칸 수, 몸 중심 x·y·z, 좌우·앞뒤 퍼짐, x·y·z 범위, 침대 안 여부, 두 센서 사람 칸 수. 36프레임(≈4초)을 한 묶음으로 본다.</p></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> FEATURES <span class=\"code-loc\">TOF/ml/lstm_anomaly.py:22–24</span></summary><pre><span class=\"ln\">22</span>FEATURES = [&quot;n_pts&quot;, &quot;cx&quot;, &quot;cy&quot;, &quot;cz&quot;, &quot;sx&quot;, &quot;sy&quot;,\n<span class=\"ln\">23</span>            &quot;x_range&quot;, &quot;y_range&quot;, &quot;z_range&quot;, &quot;in_bed&quot;, &quot;occ1&quot;, &quot;occ2&quot;]\n<span class=\"ln\">24</span>DEV = &quot;cuda&quot; if torch.cuda.is_available() else &quot;cpu&quot;</pre></details><details class=\"code\"><summary><span class=\"code-tag\">코드</span> frame_feature() — 서버 안 특징 추출(학습과 같은 식) <span class=\"code-loc\">TOF/ml/tof_anomaly.py:34–70</span></summary><pre><span class=\"ln\">34</span>def frame_feature(latest, base, presence, thr=FG_THR_MM):\n<span class=\"ln\">35</span>    &quot;&quot;&quot;한 프레임의 12차원 특징 (FEATURES 순서와 정확히 일치).\n<span class=\"ln\">36</span>\n<span class=\"ln\">37</span>    latest   : {&quot;tof1&quot;:{&quot;distances_mm&quot;:[...]}, &quot;tof2&quot;:{...}}  (서버 in-memory)\n<span class=\"ln\">38</span>    base     : {&quot;tof1&quot;:[존별 빈침대 mm], &quot;tof2&quot;:[...]}          (서버 baseline)\n<span class=\"ln\">39</span>    presence : 서버 presence dict (in_bed, tof1.occupied, tof2.occupied)\n<span class=\"ln\">40</span>    &quot;&quot;&quot;\n<span class=\"ln\">41</span>    pts = []\n<span class=\"ln\">42</span>    for sid in (&quot;tof1&quot;, &quot;tof2&quot;):\n<span class=\"ln\">43</span>        d = (latest.get(sid) or {}).get(&quot;distances_mm&quot;) or []\n<span class=\"ln\">44</span>        b = base.get(sid)\n<span class=\"ln\">45</span>        if not b:\n<span class=\"ln\">46</span>            continue\n<span class=\"ln\">47</span>        for z, v in enumerate(d):\n<span class=\"ln\">48</span>            bz = b[z] if z &lt; len(b) else None\n<span class=\"ln\">49</span>            if v and v &gt; 0 and bz and bz &gt; 0 and abs(v - bz) &gt; thr:\n<span class=\"ln\">50</span>                if roi.on_bed(sid, z, v):\n<span class=\"ln\">51</span>                    p = roi.hit_point(sid, z, v)\n<span class=\"ln\">52</span>                    if p:\n<span class=\"ln\">53</span>                        pts.append(p)\n<span class=\"ln\">54</span>\n<span class=\"ln\">55</span>    n = len(pts)\n<span class=\"ln\">56</span>    if n &lt; STATE_MIN_PTS:\n<span class=\"ln\">57</span>        cx = cy = cz = sx = sy = xr = yr = zr = 0.0\n<span class=\"ln\">58</span>    else:\n<span class=\"ln\">59</span>        xs = [p[0] for p in pts]; ys = [p[1] for p in pts]; zs = [p[2] for p in pts]\n<span class=\"ln\">60</span>        cx, cy, cz = st.mean(xs), st.mean(ys), st.mean(zs)\n<span class=\"ln\">61</span>        sx = st.pstdev(xs) if n &gt; 1 else 0.0\n<span class=\"ln\">62</span>        sy = st.pstdev(ys) if n &gt; 1 else 0.0\n<span class=\"ln\">63</span>        xr = max(xs) - min(xs); yr = max(ys) - min(ys); zr = max(zs) - min(zs)\n<span class=\"ln\">64</span>\n<span class=\"ln\">65</span>    in_bed = 1 if presence.get(&quot;in_bed&quot;) else 0\n<span class=\"ln\">66</span>    occ1 = (presence.get(&quot;tof1&quot;) or {}).get(&quot;occupied&quot;, 0) or 0\n<span class=\"ln\">67</span>    occ2 = (presence.get(&quot;tof2&quot;) or {}).get(&quot;occupied&quot;, 0) or 0\n<span class=\"ln\">68</span>    # FEATURES = n_pts,cx,cy,cz,sx,sy,x_range,y_range,z_range,in_bed,occ1,occ2\n<span class=\"ln\">69</span>    return [float(n), cx, cy, cz, sx, sy, xr, yr, zr,\n<span class=\"ln\">70</span>            float(in_bed), float(occ1), float(occ2)]</pre></details></details>\n<details class=\"step\"><summary><span class=\"num\">2-2</span>모델 구조와 판정 기준</summary><div class=\"plain\"><div class=\"formula\">인코더 LSTM(12→48) → 마지막 숨은 상태 z(48차원) → 4초 길이로 복제 → 디코더 LSTM(48→48) → 선형(48→12)<br>오차 = 평균((입력 − 재구성)²) · 기준 = 검증 정상 데이터 오차의 99백분위 = 0.9218</div></div><div class=\"detail\"><div class=\"detail-h\">엔지니어 메모</div><p>학습 2026-10-12T13:48:14 · 학습 창 5073 · 검증 창 2484 · 검증에서 기준 넘은 비율 0.01. 정상 데이터: S01 1명·하루·정지 자세. 검증 99백분위 임계라 정상에서도 약 1%는 이상으로 나온다.</p></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> class LSTMAE <span class=\"code-loc\">TOF/ml/lstm_anomaly.py:59–71</span></summary><pre><span class=\"ln\">59</span>class LSTMAE(nn.Module):\n<span class=\"ln\">60</span>    def __init__(self, feat, hid=48, layers=1):\n<span class=\"ln\">61</span>        super().__init__()\n<span class=\"ln\">62</span>        self.enc = nn.LSTM(feat, hid, layers, batch_first=True)\n<span class=\"ln\">63</span>        self.dec = nn.LSTM(hid, hid, layers, batch_first=True)\n<span class=\"ln\">64</span>        self.out = nn.Linear(hid, feat)\n<span class=\"ln\">65</span>\n<span class=\"ln\">66</span>    def forward(self, x):\n<span class=\"ln\">67</span>        T = x.shape[1]\n<span class=\"ln\">68</span>        _, (h, _) = self.enc(x)\n<span class=\"ln\">69</span>        z = h[-1]                                   # (B, hid) 잠재\n<span class=\"ln\">70</span>        d, _ = self.dec(z.unsqueeze(1).repeat(1, T, 1))\n<span class=\"ln\">71</span>        return self.out(d)</pre></details><details class=\"code\"><summary><span class=\"code-tag\">코드</span> Detector.score() — 최근 4초 오차 <span class=\"code-loc\">TOF/ml/tof_anomaly.py:91–93</span></summary><pre><span class=\"ln\">91</span>    def score(self):\n<span class=\"ln\">92</span>        &quot;&quot;&quot;버퍼가 SEQ 만큼 차면 {err,threshold,ratio,status} 반환, 아니면 None.&quot;&quot;&quot;\n<span class=\"ln\">93</span>        return self.score_window(list(self.buf))</pre></details></details>\n<div class=\"warn\"><b>한계·주의</b> 정상 데이터가 S01 한 사람·하루·정지 자세뿐이라, 다른 사람의 평범한 뒤척임도 '이상'으로 나올 수 있다. 그래서 위험 판정·알림에는 쓰지 않고 응답의 lstm 항목에만 싣는다.</div>\n<div class=\"cite\">Malhotra P et al. LSTM-based Encoder-Decoder for Multi-sensor Anomaly Detection. ICML Anomaly Detection Workshop 2016 (arXiv:1607.00148).</div>\n</section><section class=\"part\" id=\"prior\" hidden><div class=\"part-head\"><a href=\"#home\" class=\"back\">← 전체 지도</a><h2>3. 보행 기대 범위 — 입원 기록 + 문헌 + LLM 보조 판단</h2><p class=\"sub\">센서 기록이 쌓이기 전 '이 환자에게 기대되는 걸음 속도'</p></div>\n<div class=\"easy\"><b>쉽게 말하면</b> 새로 입원한 환자는 평소 걸음 기록이 없다. 그래서 나이·키로 '같은 나이 건강한 한국 노인'의 기준값을 찾고, 치매 중증도·파킨슨증만큼 줄이고, 요양시설 평균과 섞어 기대 범위를 만든다. LLM은 기록을 읽고 '치매가 어느 정도인지·혼자 걷는지'만 판단하며, 그 판단은 기록 원문을 그대로 인용해야 채택된다.</div>\n<details class=\"step\"><summary><span class=\"num\">3-1</span>숫자는 문헌에서만</summary><div class=\"plain\"><p>기준값·감소량·시설 평균은 <a class=\"ref\" href=\"../server/gait_evidence.json\" title=\"server/gait_evidence.json\">server/gait_evidence.json</a>의 출처 수치만 쓴다(AI가 숫자를 만들지 않음). 측정 보행속도·날짜·센서 예측 밖 낙상 요인은 서버 규칙으로만 뽑는다.</p></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> condition_reduction() <span class=\"code-loc\">server/gait_prior.py:124–148</span></summary><pre><span class=\"ln\">124</span>def condition_reduction(severity: str | None, parkinsonism: bool) -&gt; dict:\n<span class=\"ln\">125</span>    &quot;&quot;&quot;진단별 평소 보행속도 감소량(PEEL2019 치매, ZANARDI2021 파킨슨증). 반환 {&quot;mean&quot;,&quot;sd&quot;,&quot;flags&quot;} (m/s).\n<span class=\"ln\">126</span>    중증도를 모르면 인지저하·경도·중등도 세 범주를 같은 비중으로 두고, 범주마다 파킨슨증을 먼저 결합한 뒤\n<span class=\"ln\">127</span>    섞는다(전체 기댓값·전체 분산 공식).&quot;&quot;&quot;\n<span class=\"ln\">128</span>    red = EVIDENCE[&quot;cognition_speed_reduction_mps&quot;]\n<span class=\"ln\">129</span>    pd_red = EVIDENCE[&quot;parkinsonism_speed_reduction_mps&quot;][&quot;overground&quot;] if parkinsonism else 0.0\n<span class=\"ln\">130</span>    flags: list[str] = []\n<span class=\"ln\">131</span>    if severity in (None, &quot;none&quot;):\n<span class=\"ln\">132</span>        branches = [0.0]\n<span class=\"ln\">133</span>    elif severity == &quot;unknown&quot;:\n<span class=\"ln\">134</span>        branches = [red[&quot;cognitive_impairment&quot;], red[&quot;mild&quot;], red[&quot;moderate&quot;]]\n<span class=\"ln\">135</span>        flags.append(&quot;치매 기록은 있으나 중증도가 없어 인지저하·경도·중등도를 같은 비중으로 섞음&quot;)\n<span class=\"ln\">136</span>    elif severity == &quot;severe&quot;:\n<span class=\"ln\">137</span>        branches = [red[&quot;moderate&quot;]]\n<span class=\"ln\">138</span>        flags.append(&quot;중증 치매는 메타분석 범주에 없어 중등도 감소량을 외삽함&quot;)\n<span class=\"ln\">139</span>    else:\n<span class=\"ln\">140</span>        branches = [red[severity]]\n<span class=\"ln\">141</span>    parts = [_combine_with_parkinsonism(b, pd_red) for b in branches]\n<span class=\"ln\">142</span>    k = len(parts)\n<span class=\"ln\">143</span>    mean = sum(m for m, _ in parts) / k\n<span class=\"ln\">144</span>    var = sum(v for _, v in parts) / k + sum(m * m for m, _ in parts) / k - mean * mean\n<span class=\"ln\">145</span>    if pd_red &gt; 0 and any(b &gt; 0 for b in branches):\n<span class=\"ln\">146</span>        flags.append(&quot;치매와 파킨슨증이 함께 있어 두 감소량의 합산 여부를 불확실성으로 반영&quot;)\n<span class=\"ln\">147</span>    return {&quot;mean&quot;: mean, &quot;sd&quot;: math.sqrt(max(var, 0.0)), &quot;flags&quot;: flags,\n<span class=\"ln\">148</span>            &quot;components&quot;: {&quot;cognition_branches&quot;: branches, &quot;parkinsonism&quot;: pd_red}}</pre></details><details class=\"code\"><summary><span class=\"code-tag\">코드</span> mixture() — 두 경로(건강 노인−감소 / 시설 평균) 섞기 <span class=\"code-loc\">server/gait_prior.py:160–164</span></summary><pre><span class=\"ln\">160</span>def mixture(m1: float, v1: float, m2: float, v2: float, w: float) -&gt; tuple[float, float]:\n<span class=\"ln\">161</span>    &quot;&quot;&quot;두 경로를 비중 w : (1−w)로 섞은 분포의 평균·분산(혼합분포 공식).&quot;&quot;&quot;\n<span class=\"ln\">162</span>    mean = w * m1 + (1 - w) * m2\n<span class=\"ln\">163</span>    var = w * v1 + (1 - w) * v2 + w * (1 - w) * (m1 - m2) ** 2\n<span class=\"ln\">164</span>    return mean, var</pre></details></details>\n<details class=\"step\"><summary><span class=\"num\">3-2</span>LLM 판단과 검증</summary><div class=\"plain\"><div class=\"formula\">LLM 출력: {dementia_severity, parkinsonism, ambulation, community_path_weight} + 각 판단의 quote(기록 원문)<br>채택 조건: ① quote가 기록 줄에 실제로 있음 ② quote 안에 판단 단서(예: '중등도', 'CDR')가 있음 ③ 부정·가족력이 아님</div></div><div class=\"detail\"><div class=\"detail-h\">엔지니어 메모</div><p>검증에서 떨어진 판단은 이유와 함께 버리고 규칙 결과만 쓴다. 환자 이름은 보내기 전에 지운다(redact_names).</p></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> validate_ai_profile() — 인용 검증 <span class=\"code-loc\">server/gait_prior.py:632–701</span></summary><pre><span class=\"ln\">632</span>def validate_ai_profile(ai, records_text: str) -&gt; tuple[dict, list[str]]:\n<span class=\"ln\">633</span>    &quot;&quot;&quot;AI 판단 중 인용이 기록 줄에 있고, 인용한 부분 안의 단서가 판단을 긍정(또는 부정)으로 뒷받침하는 것만 남긴다.\n<span class=\"ln\">634</span>    긍정·부정은 그 단서가 있는 원래 문장 범위로 판단한다. 반환 (검증된 항목, 버린 이유 목록).&quot;&quot;&quot;\n<span class=\"ln\">635</span>    kept: dict = {}\n<span class=\"ln\">636</span>    dropped: list[str] = []\n<span class=\"ln\">637</span>    if not isinstance(ai, dict):\n<span class=\"ln\">638</span>        return kept, [&quot;AI 응답이 JSON 객체가 아님&quot;]\n<span class=\"ln\">639</span>    lines = [ln for ln in records_text.splitlines() if ln.strip()]\n<span class=\"ln\">640</span>    non_amb_in_records = any(_non_ambulatory(ln) for ln in lines)\n<span class=\"ln\">641</span>\n<span class=\"ln\">642</span>    item = ai.get(&quot;dementia_severity&quot;)\n<span class=\"ln\">643</span>    if isinstance(item, dict) and item.get(&quot;value&quot;) not in (None, &quot;unknown&quot;):\n<span class=\"ln\">644</span>        value, spans = item.get(&quot;value&quot;), _quote_spans(item.get(&quot;quote&quot;), lines)\n<span class=\"ln\">645</span>        if value not in SEVERITIES:\n<span class=\"ln\">646</span>            dropped.append(f&quot;dementia_severity: 허용되지 않은 값 {value!r}&quot;)\n<span class=\"ln\">647</span>        elif not spans:\n<span class=\"ln\">648</span>            dropped.append(&quot;dementia_severity: 인용이 기록에 없음&quot;)\n<span class=\"ln\">649</span>        elif not _severity_supported(value, spans):\n<span class=\"ln\">650</span>            dropped.append(f&quot;dementia_severity: 인용한 부분에 &#x27;{value}&#x27;를 뒷받침하는 단서가 없음&quot;)\n<span class=\"ln\">651</span>        else:\n<span class=\"ln\">652</span>            kept[&quot;dementia_severity&quot;] = {&quot;value&quot;: value, &quot;quote&quot;: item.get(&quot;quote&quot;), &quot;source&quot;: &quot;ai&quot;}\n<span class=\"ln\">653</span>\n<span class=\"ln\">654</span>    item = ai.get(&quot;parkinsonism&quot;)\n<span class=\"ln\">655</span>    if isinstance(item, dict) and isinstance(item.get(&quot;value&quot;), bool):\n<span class=\"ln\">656</span>        spans = _quote_spans(item.get(&quot;quote&quot;), lines)\n<span class=\"ln\">657</span>        if item[&quot;value&quot;] is False and item.get(&quot;quote&quot;) in (None, &quot;&quot;):\n<span class=\"ln\">658</span>            kept[&quot;parkinsonism&quot;] = {&quot;value&quot;: False, &quot;quote&quot;: None, &quot;source&quot;: &quot;ai&quot;}\n<span class=\"ln\">659</span>        elif not spans:\n<span class=\"ln\">660</span>            dropped.append(&quot;parkinsonism: 인용이 기록에 없음&quot;)\n<span class=\"ln\">661</span>        elif any(_matches(ln, _PARKINSON, lo, hi, affirmed=item[&quot;value&quot;], self_only=True) for ln, lo, hi in spans):\n<span class=\"ln\">662</span>            kept[&quot;parkinsonism&quot;] = {&quot;value&quot;: item[&quot;value&quot;], &quot;quote&quot;: item[&quot;quote&quot;], &quot;source&quot;: &quot;ai&quot;}\n<span class=\"ln\">663</span>        else:\n<span class=\"ln\">664</span>            dropped.append(&quot;parkinsonism: 인용한 부분의 긍정·부정이 판단과 맞지 않음&quot;)\n<span class=\"ln\">665</span>\n<span class=\"ln\">666</span>    item = ai.get(&quot;ambulation&quot;)\n<span class=\"ln\">667</span>    if isinstance(item, dict) and item.get(&quot;value&quot;) not in (None, &quot;unknown&quot;):\n<span class=\"ln\">668</span>        value, spans = item.get(&quot;value&quot;), _quote_spans(item.get(&quot;quote&quot;), lines)\n<span class=\"ln\">669</span>        if value not in AMBULATION:\n<span class=\"ln\">670</span>            dropped.append(f&quot;ambulation: 허용되지 않은 값 {value!r}&quot;)\n<span class=\"ln\">671</span>        elif not spans:\n<span class=\"ln\">672</span>            dropped.append(&quot;ambulation: 인용이 기록에 없음&quot;)\n<span class=\"ln\">673</span>        elif value == &quot;non_ambulatory&quot;:\n<span class=\"ln\">674</span>            if not any(_non_ambulatory(ln, lo, hi) for ln, lo, hi in spans):\n<span class=\"ln\">675</span>                dropped.append(&quot;ambulation: 인용한 부분에 보행 불가 단서가 없음&quot;)\n<span class=\"ln\">676</span>            elif any(_walking_evidence(ln, pat, strong_only=True) for ln in lines for pat in _WALKING_CUES.values()):\n<span class=\"ln\">677</span>                dropped.append(&quot;ambulation: 기록에 걷는다는 단서가 있어 보행 불가와 충돌&quot;)\n<span class=\"ln\">678</span>            else:\n<span class=\"ln\">679</span>                kept[&quot;ambulation&quot;] = {&quot;value&quot;: value, &quot;quote&quot;: item[&quot;quote&quot;], &quot;source&quot;: &quot;ai&quot;}\n<span class=\"ln\">680</span>        elif value == &quot;wheelchair_user&quot;:\n<span class=\"ln\">681</span>            if any(_matches(ln, _WHEELCHAIR, lo, hi) for ln, lo, hi in spans):\n<span class=\"ln\">682</span>                kept[&quot;ambulation&quot;] = {&quot;value&quot;: value, &quot;quote&quot;: item[&quot;quote&quot;], &quot;source&quot;: &quot;ai&quot;}\n<span class=\"ln\">683</span>            else:\n<span class=\"ln\">684</span>                dropped.append(&quot;ambulation: 인용한 부분에 휠체어 단서가 없음&quot;)\n<span class=\"ln\">685</span>        elif any(_walking_evidence(ln, _WALKING_CUES[value], strong_only=non_amb_in_records, lo=lo, hi=hi)\n<span class=\"ln\">686</span>                 for ln, lo, hi in spans):\n<span class=\"ln\">687</span>            kept[&quot;ambulation&quot;] = {&quot;value&quot;: value, &quot;quote&quot;: item[&quot;quote&quot;], &quot;source&quot;: &quot;ai&quot;}\n<span class=\"ln\">688</span>        else:\n<span class=\"ln\">689</span>            dropped.append(f&quot;ambulation: 인용한 부분이 &#x27;{value}&#x27;를 뒷받침하지 않음&quot;)\n<span class=\"ln\">690</span>\n<span class=\"ln\">691</span>    w = _to_float(ai.get(&quot;community_path_weight&quot;))\n<span class=\"ln\">692</span>    quotes = ai.get(&quot;weight_quotes&quot;)\n<span class=\"ln\">693</span>    quotes = [q for q in quotes if isinstance(q, str)] if isinstance(quotes, list) else []\n<span class=\"ln\">694</span>    evidence = [q for q in quotes\n<span class=\"ln\">695</span>                if any(_matches(ln, _MOBILITY_TERMS, lo, hi, affirmed=None) for ln, lo, hi in _quote_spans(q, lines))]\n<span class=\"ln\">696</span>    if w is not None and 0.0 &lt;= w &lt;= 1.0 and evidence:\n<span class=\"ln\">697</span>        kept[&quot;community_path_weight&quot;] = {&quot;value&quot;: w, &quot;quotes&quot;: evidence,\n<span class=\"ln\">698</span>                                         &quot;rationale&quot;: str(ai.get(&quot;weight_rationale&quot;) or &quot;&quot;)[:600]}\n<span class=\"ln\">699</span>    elif w is not None:\n<span class=\"ln\">700</span>        dropped.append(&quot;community_path_weight: 0~1 범위가 아니거나 인용에 보행·이동 관련 단어가 없어 기본 비중을 씀&quot;)\n<span class=\"ln\">701</span>    return kept, dropped</pre></details><details class=\"code\"><summary><span class=\"code-tag\">코드</span> run_ai() <span class=\"code-loc\">server/gait_prior.py:740–765</span></summary><pre><span class=\"ln\">740</span>def run_ai(records_text: str, rule_profile: dict, paths_preview: dict, caller=None) -&gt; dict:\n<span class=\"ln\">741</span>    &quot;&quot;&quot;AI 호출. 실패하면 가짜 결과 없이 {&quot;success&quot;: False, ...}를 그대로 돌려준다.&quot;&quot;&quot;\n<span class=\"ln\">742</span>    if caller is None:\n<span class=\"ln\">743</span>        import ai_report\n<span class=\"ln\">744</span>        caller = ai_report.call_openai\n<span class=\"ln\">745</span>    brief = {k: rule_profile[k] for k in (&quot;dementia_severity&quot;, &quot;parkinsonism&quot;, &quot;ambulation&quot;) if k in rule_profile}\n<span class=\"ln\">746</span>    user_content = (\n<span class=\"ln\">747</span>        &quot;아래는 한 환자의 기록입니다. 등록된 환자 이름은 &#x27;환자&#x27;로 가렸습니다.\\n\\n[기록]\\n&quot; + records_text +\n<span class=\"ln\">748</span>        &quot;\\n\\n[규칙으로 먼저 뽑은 값 — 틀렸으면 바로잡으세요]\\n&quot; + json.dumps(brief, ensure_ascii=False) +\n<span class=\"ln\">749</span>        &quot;\\n\\n[서버가 문헌값으로 계산한 두 경로 — 숫자는 바꾸지 말고 비중만 고르세요]\\n&quot; +\n<span class=\"ln\">750</span>        json.dumps(paths_preview, ensure_ascii=False)\n<span class=\"ln\">751</span>    )\n<span class=\"ln\">752</span>    try:\n<span class=\"ln\">753</span>        result = caller(system_prompt=AI_SYSTEM_PROMPT, user_content=user_content, json_mode=True)\n<span class=\"ln\">754</span>    except Exception as e:   # 호출 계층이 예외를 던져도 규칙 결과로 계속한다\n<span class=\"ln\">755</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;call_error&quot;, &quot;message&quot;: type(e).__name__}\n<span class=\"ln\">756</span>    if not isinstance(result, dict) or not result.get(&quot;success&quot;):\n<span class=\"ln\">757</span>        result = result if isinstance(result, dict) else {}\n<span class=\"ln\">758</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: result.get(&quot;error_type&quot;), &quot;message&quot;: result.get(&quot;message&quot;)}\n<span class=\"ln\">759</span>    try:\n<span class=\"ln\">760</span>        parsed = json.loads(result[&quot;text&quot;])\n<span class=\"ln\">761</span>    except (KeyError, TypeError, json.JSONDecodeError):\n<span class=\"ln\">762</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;parse_error&quot;, &quot;message&quot;: &quot;AI 응답을 JSON으로 읽지 못했습니다.&quot;}\n<span class=\"ln\">763</span>    if not isinstance(parsed, dict):\n<span class=\"ln\">764</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;invalid_response&quot;, &quot;message&quot;: &quot;AI 응답이 JSON 객체가 아닙니다.&quot;}\n<span class=\"ln\">765</span>    return {&quot;success&quot;: True, &quot;parsed&quot;: parsed, &quot;model&quot;: result.get(&quot;model&quot;)}</pre></details></details>\n<details class=\"step\"><summary><span class=\"num\">3-3</span>어디에 쓰이나</summary><div class=\"plain\"><p>개인 기록이 5건 모이기 전까지 '잠정' 판정(주의·경고까지, 정식 알람 없음)에 쓰고, 보행 저하 예측(4장) 칼만 필터의 출발점(사전값)으로도 쓴다. 통합 위험 점수에는 넣지 않는다.</p></div></details>\n<div class=\"warn\"><b>한계·주의</b> 문헌 숫자는 다른 집단(지역사회 노인·실험실 측정)에서 나온 값이라 개인에게 그대로 맞지 않는다. 그래서 '범위'로만 쓰고, 개인 기록이 쌓이면 개인 기준이 우선한다.</div>\n</section><section class=\"part\" id=\"trend\" hidden><div class=\"part-head\"><a href=\"#home\" class=\"back\">← 전체 지도</a><h2>4. 보행 저하 예측 — 칼만 필터(국소 선형 추세)</h2><p class=\"sub\">매일 걸음값으로 7·14일 뒤를 예측하고 '줄고 있나'를 확률로</p></div>\n<div class=\"easy\"><b>쉽게 말하면</b> 하루하루 걸음 속도는 들쭉날쭉하다. 칼만 필터는 '진짜 수준'과 '하루에 얼마씩 변하는지(기울기)'를 불확실성(±)과 함께 추정한다. 그 기울기를 앞으로 늘려 7·14일 뒤를 예측하고, '7일 동안 의미 있게 줄었을 확률'이 80%를 넘을 때만 신호를 낸다.</div>\n<details class=\"step\"><summary><span class=\"num\">4-1</span>하루 대표값 만들기</summary><div class=\"plain\"><p>레이더 6초 구간 중 <b>환자 확정 + 곧게 걸은 구간</b>만 모아 하루 중앙값을 낸다. 하루 5구간 미만인 날은 버린다. 2026-10-20부터 환자 확정은 낙상 판정기가 고른 환자를 그대로 쓴다.</p></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> daily_series() <span class=\"code-loc\">server/gait_trend.py:71–100</span></summary><pre><span class=\"ln\"> 71</span>def daily_series(conn, target_id: str, days: int = LOOKBACK_DAYS, now: datetime | None = None) -&gt; list[dict]:\n<span class=\"ln\"> 72</span>    &quot;&quot;&quot;mmw_readings → 날짜별 대표값. [{&#x27;date&#x27;,&#x27;n&#x27;,&#x27;speed&#x27;,&#x27;speed_sd&#x27;,&#x27;stride&#x27;,&#x27;stride_sd&#x27;}] (기록 있는 날만).&quot;&quot;&quot;\n<span class=\"ln\"> 73</span>    now = now or datetime.now()\n<span class=\"ln\"> 74</span>    start = (now - timedelta(days=days)).isoformat(timespec=&quot;seconds&quot;)\n<span class=\"ln\"> 75</span>    rows = conn.execute(&quot;&quot;&quot;SELECT timestamp, speed, stride_length, reliable, walking, patient_locked\n<span class=\"ln\"> 76</span>                           FROM mmw_readings WHERE target_id = ? AND timestamp &gt;= ? ORDER BY timestamp&quot;&quot;&quot;,\n<span class=\"ln\"> 77</span>                        (target_id, start)).fetchall()\n<span class=\"ln\"> 78</span>    by_day: dict[str, dict[str, list[float]]] = {}\n<span class=\"ln\"> 79</span>    for r in rows:\n<span class=\"ln\"> 80</span>        r = dict(r)\n<span class=\"ln\"> 81</span>        if not _usable(r):\n<span class=\"ln\"> 82</span>            continue\n<span class=\"ln\"> 83</span>        day = by_day.setdefault(str(r[&quot;timestamp&quot;])[:10], {&quot;speed&quot;: [], &quot;stride&quot;: []})\n<span class=\"ln\"> 84</span>        for key, cfg in METRICS.items():\n<span class=\"ln\"> 85</span>            v = r.get(cfg[&quot;col&quot;])\n<span class=\"ln\"> 86</span>            lo, hi = cfg[&quot;valid&quot;]\n<span class=\"ln\"> 87</span>            if isinstance(v, (int, float)) and lo &lt;= v &lt;= hi:\n<span class=\"ln\"> 88</span>                day[key].append(float(v))\n<span class=\"ln\"> 89</span>    out = []\n<span class=\"ln\"> 90</span>    for d in sorted(by_day):\n<span class=\"ln\"> 91</span>        item = {&quot;date&quot;: d, &quot;n&quot;: len(by_day[d][&quot;speed&quot;])}\n<span class=\"ln\"> 92</span>        for key in METRICS:\n<span class=\"ln\"> 93</span>            vals = by_day[d][key]\n<span class=\"ln\"> 94</span>            ok = len(vals) &gt;= MIN_WINDOWS_PER_DAY\n<span class=\"ln\"> 95</span>            item[key] = round(st.median(vals), 4) if ok else None\n<span class=\"ln\"> 96</span>            item[key + &quot;_sd&quot;] = round(_robust_sd(vals), 4) if ok else None\n<span class=\"ln\"> 97</span>            item[key + &quot;_n&quot;] = len(vals)\n<span class=\"ln\"> 98</span>        if item[&quot;speed&quot;] is not None or item[&quot;stride&quot;] is not None:\n<span class=\"ln\"> 99</span>            out.append(item)\n<span class=\"ln\">100</span>    return out</pre></details></details>\n<details class=\"step\"><summary><span class=\"num\">4-2</span>칼만 필터 식</summary><div class=\"plain\"><div class=\"formula\">상태 x = [수준 L, 하루 기울기 b] · 하루 지나면 L ← L + b, b ← b (+작은 변화 Q)<br>관측 y = L + 오차(R = max(그날 표준오차², 최소 오차²))<br>예측: x = F x, P = F P Fᵀ + Q,   F = [[1,1],[0,1]]   갱신: K = P Hᵀ/(H P Hᵀ + R), H = [1,0]</div></div><div class=\"detail\"><div class=\"detail-h\">엔지니어 메모</div><p>기록 없는 날은 예측 단계만 거친다. 보행 기대 범위(3장)가 있으면 출발 수준으로 쓴다.</p></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> kalman_trend() <span class=\"code-loc\">server/gait_trend.py:103–149</span></summary><pre><span class=\"ln\">103</span>def kalman_trend(points: list[tuple[int, float, float]], cfg: dict, prior: tuple[float, float] | None = None) -&gt; dict | None:\n<span class=\"ln\">104</span>    &quot;&quot;&quot;국소 선형 추세 칼만 필터.\n<span class=\"ln\">105</span>\n<span class=\"ln\">106</span>    상태 x = [수준 L, 하루 기울기 b].  하루가 지나면  L ← L + b,  b ← b  (+ 작은 무작위 변화 Q).\n<span class=\"ln\">107</span>    관측 y_t = L_t + 측정 오차(분산 R_t = max(그날 표준오차², 최소 오차²)).\n<span class=\"ln\">108</span>    points: [(기준일로부터 날짜 번호, 그날 대표값, 그날 표준오차)] — 기록 없는 날은 예측 단계만 거친다.\n<span class=\"ln\">109</span>    prior: (기대 수준, 표준편차) — 입원 기록 기반 기대 범위가 있으면 출발점으로 쓴다.\n<span class=\"ln\">110</span>    &quot;&quot;&quot;\n<span class=\"ln\">111</span>    if not points:\n<span class=\"ln\">112</span>        return None\n<span class=\"ln\">113</span>    q_l, q_s, r_floor = cfg[&quot;q_level&quot;] ** 2, cfg[&quot;q_slope&quot;] ** 2, cfg[&quot;r_floor&quot;] ** 2\n<span class=\"ln\">114</span>    first_day, first_val, _ = points[0]\n<span class=\"ln\">115</span>    level0, level_sd0 = prior if prior else (first_val, 0.2)\n<span class=\"ln\">116</span>    x = [level0, 0.0]\n<span class=\"ln\">117</span>    P = [[level_sd0 ** 2, 0.0], [0.0, cfg[&quot;slope_prior_sd&quot;] ** 2]]\n<span class=\"ln\">118</span>    day = first_day\n<span class=\"ln\">119</span>    history = []\n<span class=\"ln\">120</span>    for t, y, se in points:\n<span class=\"ln\">121</span>        while day &lt; t:   # 하루씩 앞으로(예측 단계): x = F x, P = F P Fᵀ + Q,  F = [[1,1],[0,1]]\n<span class=\"ln\">122</span>            x = [x[0] + x[1], x[1]]\n<span class=\"ln\">123</span>            P = [[P[0][0] + 2 * P[0][1] + P[1][1] + q_l, P[0][1] + P[1][1]],\n<span class=\"ln\">124</span>                 [P[1][0] + P[1][1], P[1][1] + q_s]]\n<span class=\"ln\">125</span>            day += 1\n<span class=\"ln\">126</span>        # 갱신 단계: 칼만 이득 K = P Hᵀ / (H P Hᵀ + R),  H = [1, 0]\n<span class=\"ln\">127</span>        R = max(se ** 2, r_floor)\n<span class=\"ln\">128</span>        S = P[0][0] + R\n<span class=\"ln\">129</span>        K = [P[0][0] / S, P[1][0] / S]\n<span class=\"ln\">130</span>        innov = y - x[0]\n<span class=\"ln\">131</span>        x = [x[0] + K[0] * innov, x[1] + K[1] * innov]\n<span class=\"ln\">132</span>        P = [[(1 - K[0]) * P[0][0], (1 - K[0]) * P[0][1]],\n<span class=\"ln\">133</span>             [P[1][0] - K[1] * P[0][0], P[1][1] - K[1] * P[0][1]]]\n<span class=\"ln\">134</span>        history.append({&quot;day&quot;: t, &quot;obs&quot;: y, &quot;level&quot;: x[0], &quot;level_sd&quot;: math.sqrt(max(P[0][0], 0)),\n<span class=\"ln\">135</span>                        &quot;slope&quot;: x[1], &quot;slope_sd&quot;: math.sqrt(max(P[1][1], 0))})\n<span class=\"ln\">136</span>\n<span class=\"ln\">137</span>    def forecast(h: int) -&gt; dict:\n<span class=\"ln\">138</span>        &quot;&quot;&quot;h일 뒤 수준: 예측 단계를 h번 반복(x = F x, P = F P Fᵀ + Q). 평균 = L + h·b, 분산 = 반복 후 P00.&quot;&quot;&quot;\n<span class=\"ln\">139</span>        fx, fP = list(x), [row[:] for row in P]\n<span class=\"ln\">140</span>        for _ in range(h):\n<span class=\"ln\">141</span>            fx = [fx[0] + fx[1], fx[1]]\n<span class=\"ln\">142</span>            fP = [[fP[0][0] + 2 * fP[0][1] + fP[1][1] + q_l, fP[0][1] + fP[1][1]],\n<span class=\"ln\">143</span>                  [fP[1][0] + fP[1][1], fP[1][1] + q_s]]\n<span class=\"ln\">144</span>        sd = math.sqrt(max(fP[0][0], 0))\n<span class=\"ln\">145</span>        return {&quot;mean&quot;: fx[0], &quot;sd&quot;: sd, &quot;lo80&quot;: fx[0] - Z80 * sd, &quot;hi80&quot;: fx[0] + Z80 * sd}\n<span class=\"ln\">146</span>\n<span class=\"ln\">147</span>    return {&quot;level&quot;: x[0], &quot;level_sd&quot;: math.sqrt(max(P[0][0], 0)), &quot;slope&quot;: x[1],\n<span class=\"ln\">148</span>            &quot;slope_sd&quot;: math.sqrt(max(P[1][1], 0)), &quot;last_day&quot;: day, &quot;history&quot;: history,\n<span class=\"ln\">149</span>            &quot;forecast7&quot;: forecast(7), &quot;forecast14&quot;: forecast(14)}</pre></details></details>\n<details class=\"step\"><summary><span class=\"num\">4-3</span>신호 기준(논문)</summary><div class=\"plain\"><table><thead><tr><th>지표</th><th>주의(7일 누적 감소)</th><th>경고</th></tr></thead><tbody><tr><td>보행 속도</td><td>2.54 cm/s</td><td>5.1 cm/s</td></tr><tr><td>보폭</td><td>2.54 cm</td><td>7.6 cm</td></tr></tbody></table><p>감소 확률 = Φ((감소량 − 기준) / 표준편차) ≥ 80%일 때만. 기록일 14일 미만이면 예측하지 않는다.</p></div><div class=\"detail\"><div class=\"detail-h\">엔지니어 메모</div><p>Phillips 2017: 집 안 상시 측정에서 7일 누적 5.1 cm/s 감소 시 3주 내 낙상 86.3%(변화 없음 19.5%). <b>이 86.3%는 그 연구 집단의 값이지 우리 환자의 낙상 확률이 아니다</b> — 리포트에도 그렇게 쓰게 한다.</p></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> _metric_assessment() <span class=\"code-loc\">server/gait_trend.py:152–192</span></summary><pre><span class=\"ln\">152</span>def _metric_assessment(series: list[dict], key: str, prior: tuple[float, float] | None, today: date) -&gt; dict:\n<span class=\"ln\">153</span>    cfg = METRICS[key]\n<span class=\"ln\">154</span>    pts = []\n<span class=\"ln\">155</span>    base = None\n<span class=\"ln\">156</span>    for d in series:\n<span class=\"ln\">157</span>        if d.get(key) is None:\n<span class=\"ln\">158</span>            continue\n<span class=\"ln\">159</span>        dd = date.fromisoformat(d[&quot;date&quot;])\n<span class=\"ln\">160</span>        base = base or dd\n<span class=\"ln\">161</span>        se = max(d.get(key + &quot;_sd&quot;) or 0.0, WINDOW_SD_FLOOR) / math.sqrt(max(d.get(key + &quot;_n&quot;) or 1, 1))\n<span class=\"ln\">162</span>        pts.append(((dd - base).days, d[key], se))\n<span class=\"ln\">163</span>    out = {&quot;metric&quot;: key, &quot;ko&quot;: cfg[&quot;ko&quot;], &quot;days_used&quot;: len(pts)}\n<span class=\"ln\">164</span>    if len(pts) &lt; MIN_DAYS:\n<span class=\"ln\">165</span>        out.update(status=&quot;insufficient&quot;, message=f&quot;{cfg[&#x27;ko&#x27;]}: 하루 대표값이 {len(pts)}일치(필요 {MIN_DAYS}일)&quot;)\n<span class=\"ln\">166</span>        return out\n<span class=\"ln\">167</span>    k = kalman_trend(pts, cfg, prior)\n<span class=\"ln\">168</span>    # 7일 누적 변화(Phillips 2017의 정의) = 오늘 추정 수준 − 7일 전 추정 수준(그날 기록이 없으면 그 이전 가장 가까운 날).\n<span class=\"ln\">169</span>    # 표준편차 = √(오늘 수준 분산 + 7일 전 수준 분산). 처음엔 &#x27;7×기울기&#x27;를 썼으나 기울기는 늦게 반응해\n<span class=\"ln\">170</span>    # 합성 시험(하루 1 cm/s 감소)에서 경고를 거의 못 냈다(2026-10-13 조정 기록은 문서 참조).\n<span class=\"ln\">171</span>    past = [h for h in k[&quot;history&quot;] if h[&quot;day&quot;] &lt;= k[&quot;history&quot;][-1][&quot;day&quot;] - 7]\n<span class=\"ln\">172</span>    ref = past[-1] if past else k[&quot;history&quot;][0]\n<span class=\"ln\">173</span>    change7 = k[&quot;level&quot;] - ref[&quot;level&quot;]\n<span class=\"ln\">174</span>    change7_sd = math.sqrt(k[&quot;level_sd&quot;] ** 2 + ref[&quot;level_sd&quot;] ** 2)\n<span class=\"ln\">175</span>    p_caution = _norm_cdf((-cfg[&quot;caution_cm&quot;] / 100 - change7) / change7_sd) if change7_sd &gt; 0 else float(change7 &lt;= -cfg[&quot;caution_cm&quot;] / 100)\n<span class=\"ln\">176</span>    p_warn = _norm_cdf((-cfg[&quot;warn_cm&quot;] / 100 - change7) / change7_sd) if change7_sd &gt; 0 else float(change7 &lt;= -cfg[&quot;warn_cm&quot;] / 100)\n<span class=\"ln\">177</span>    level = &quot;warning&quot; if p_warn &gt;= CONFIDENT else &quot;caution&quot; if p_caution &gt;= CONFIDENT else &quot;normal&quot;\n<span class=\"ln\">178</span>    days_since_last = (today - (base + timedelta(days=k[&quot;last_day&quot;]))).days\n<span class=\"ln\">179</span>    out.update(\n<span class=\"ln\">180</span>        status=&quot;ok&quot;, level=level,\n<span class=\"ln\">181</span>        current=round(k[&quot;level&quot;], 3), current_sd=round(k[&quot;level_sd&quot;], 3),\n<span class=\"ln\">182</span>        slope_per_day_cm=round(k[&quot;slope&quot;] * 100, 2), slope_sd_cm=round(k[&quot;slope_sd&quot;] * 100, 2),\n<span class=\"ln\">183</span>        change7_cm=round(change7 * 100, 2), change7_sd_cm=round(change7_sd * 100, 2),\n<span class=\"ln\">184</span>        p_decline_caution=round(p_caution, 3), p_decline_warning=round(p_warn, 3),\n<span class=\"ln\">185</span>        caution_cm=cfg[&quot;caution_cm&quot;], warn_cm=cfg[&quot;warn_cm&quot;],\n<span class=\"ln\">186</span>        forecast7={k2: round(v, 3) for k2, v in k[&quot;forecast7&quot;].items()},\n<span class=\"ln\">187</span>        forecast14={k2: round(v, 3) for k2, v in k[&quot;forecast14&quot;].items()},\n<span class=\"ln\">188</span>        days_since_last=days_since_last,\n<span class=\"ln\">189</span>        history=[{&quot;date&quot;: (base + timedelta(days=h[&quot;day&quot;])).isoformat(), &quot;obs&quot;: round(h[&quot;obs&quot;], 3),\n<span class=\"ln\">190</span>                  &quot;level&quot;: round(h[&quot;level&quot;], 3)} for h in k[&quot;history&quot;]],\n<span class=\"ln\">191</span>    )\n<span class=\"ln\">192</span>    return out</pre></details></details>\n<div class=\"warn\"><b>한계·주의</b> 아직 실제 환자 기록이 14일 이상 쌓인 적이 없어 실데이터 검증은 없다(합성 시험만). 본선 전에 매일 걷는 기록을 쌓으면 실제 예측을 보여 줄 수 있다.</div>\n<div class=\"cite\">Phillips LJ et al. Using Embedded Sensors in Independent Living to Predict Gait Changes and Falls. West J Nurs Res 2017;39(1):78–94. · Harvey AC. Forecasting, Structural Time Series Models and the Kalman Filter. Cambridge Univ Press 1989.</div>\n</section><section class=\"part\" id=\"search\" hidden><div class=\"part-head\"><a href=\"#home\" class=\"back\">← 전체 지도</a><h2>5. 근거 찾기 — 검색어 생성·하이브리드 검색·충분성 판단</h2><p class=\"sub\">LLM이 무엇을 찾을지 정하고, 서버가 논문·환자 기록에서 찾는다</p></div>\n<div class=\"easy\"><b>쉽게 말하면</b> 리포트를 쓰기 전에 '이 환자 상태를 설명할 논문이 뭐지?'를 먼저 찾는다. LLM이 환자 상태를 보고 검색어 2~3개를 만들고, 서버가 논문 조각을 두 방식(뜻이 비슷한 것 + 단어가 겹치는 것)으로 찾아 순위를 합친다. LLM이 '근거가 충분한가'를 판단해 부족하면 한 번 더 찾는다.</div>\n<details class=\"step\"><summary><span class=\"num\">5-1</span>전체 흐름(investigate)</summary><div class=\"plain\"><p>상태 모으기 → 검색어 생성(LLM) → 하이브리드 검색 + 환자 EMR 검색 → 충분성 판단(LLM) → 부족하면 추가 검색어로 다시(기본 최대 2라운드, 리포트 버튼은 1라운드). 이 함수는 리포트도 점수도 만들지 않고 재료만 모은다.</p></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> gather_patient_state() — 환자 상태 모으기 <span class=\"code-loc\">server/ai_agent.py:80–151</span></summary><pre><span class=\"ln\"> 80</span>def gather_patient_state(bed_id: str) -&gt; dict:\n<span class=\"ln\"> 81</span>    &quot;&quot;&quot;환자 프로필·위험인자·투약(SQL DB)과, ToF/mmWave 실서버의 현재 판정을 한데 모은다.\n<span class=\"ln\"> 82</span>    실서버가 꺼져있어도(개발 중 등) 예외를 던지지 않고 그 부분만 None으로 정직하게 비운다 —\n<span class=\"ln\"> 83</span>    &quot;조회 실패&quot;와 &quot;정보 없음&quot;을 헷갈리지 않도록 각 필드에 상태를 남긴다.&quot;&quot;&quot;\n<span class=\"ln\"> 84</span>    patient = db.get_patient(bed_id)\n<span class=\"ln\"> 85</span>    mmw_target_id = (patient or {}).get(&quot;mmw_target_id&quot;) or (&quot;room_01&quot; if bed_id == &quot;bed_01&quot; else None)\n<span class=\"ln\"> 86</span>\n<span class=\"ln\"> 87</span>    state: dict = {\n<span class=\"ln\"> 88</span>        &quot;bed_id&quot;: bed_id,\n<span class=\"ln\"> 89</span>        &quot;patient_profile&quot;: patient,\n<span class=\"ln\"> 90</span>        &quot;risk_factors&quot;: db.list_risk_factors(bed_id) if patient else [],\n<span class=\"ln\"> 91</span>        &quot;medications&quot;: db.list_medications(bed_id) if patient else [],\n<span class=\"ln\"> 92</span>        &quot;emr_records&quot;: db.list_emr_records(bed_id) if patient else [],\n<span class=\"ln\"> 93</span>        &quot;nursing_records&quot;: db.list_nursing_records(bed_id) if patient else [],\n<span class=\"ln\"> 94</span>        &quot;data_source&quot;: &quot;simulation&quot; if sim_state.is_simulated(bed_id) else &quot;patient_records_and_live_sensors&quot;,\n<span class=\"ln\"> 95</span>        &quot;recent_24h&quot;: db.get_patient_timeseries_summary(bed_id, window=&quot;24h&quot;, exclude_types=(&quot;ai_analysis_completed&quot;,)),\n<span class=\"ln\"> 96</span>        # 실제 개별 이벤트(시각·제목·메모) — 집계 요약(recent_24h)만으로는 &quot;언제 어떤 전조가\n<span class=\"ln\"> 97</span>        # 있었는지&quot;를 알 수 없어, 낙상 등 특정 사건 전후의 시계열 근거로 그대로 씀.\n<span class=\"ln\"> 98</span>        &quot;recent_events&quot;: [e for e in db.get_activity_log(bed_id, limit=60)\n<span class=\"ln\"> 99</span>                          if e.get(&quot;event_type&quot;) != &quot;ai_analysis_completed&quot; and _recent_record(e.get(&quot;ts&quot;))][:20] if patient else [],\n<span class=\"ln\">100</span>        &quot;tof_behavior&quot;: None, &quot;tof_behavior_error&quot;: None,\n<span class=\"ln\">101</span>        &quot;mmw_latest&quot;: None, &quot;mmw_latest_error&quot;: None,\n<span class=\"ln\">102</span>    }\n<span class=\"ln\">103</span>\n<span class=\"ln\">104</span>    # The bed_sim_* demo patients have no hardware at all — their &quot;sensors&quot; are a\n<span class=\"ln\">105</span>    # deterministic client-side scenario (site/dashboard-assets/simulation.js). Mirror that\n<span class=\"ln\">106</span>    # same formula here (sim_state.py) so a report generated with nobody&#x27;s browser open\n<span class=\"ln\">107</span>    # still has real signals to reason about, matching whatever is on screen at that moment.\n<span class=\"ln\">108</span>    if sim_state.is_simulated(bed_id):\n<span class=\"ln\">109</span>        state[&quot;tof_behavior&quot;] = sim_state.simulated_tof_behavior(bed_id)\n<span class=\"ln\">110</span>        state[&quot;mmw_latest&quot;] = sim_state.simulated_mmw_latest(bed_id)\n<span class=\"ln\">111</span>        return _attach_fall_risk(state, bed_id)\n<span class=\"ln\">112</span>\n<span class=\"ln\">113</span>    # The shared hardware stream is wired to the first patient only. The retired\n<span class=\"ln\">114</span>    # /tof/behavior route no longer exists; use current posture and presence APIs.\n<span class=\"ln\">115</span>    if bed_id == &quot;bed_01&quot;:\n<span class=\"ln\">116</span>        try:\n<span class=\"ln\">117</span>            r = requests.get(f&quot;{TOF_BASE}/tof/latest&quot;, timeout=3)\n<span class=\"ln\">118</span>            latest = r.json() if r.status_code == 200 else {}\n<span class=\"ln\">119</span>            frames = [latest.get(sensor) or {} for sensor in (&quot;tof1&quot;, &quot;tof2&quot;)]\n<span class=\"ln\">120</span>            if any(_fresh(frame.get(&quot;received_at&quot;), 10) for frame in frames):\n<span class=\"ln\">121</span>                p = requests.get(f&quot;{TOF_BASE}/tof/presence&quot;, timeout=3)\n<span class=\"ln\">122</span>                presence = p.json() if p.status_code == 200 else None\n<span class=\"ln\">123</span>                risk = latest.get(&quot;risk&quot;) or {}\n<span class=\"ln\">124</span>                risk_level = None\n<span class=\"ln\">125</span>                if risk.get(&quot;posture&quot;) and _fresh(risk.get(&quot;at&quot;), 10):\n<span class=\"ln\">126</span>                    risk_level = &quot;warning&quot; if risk.get(&quot;status&quot;) == &quot;anomaly&quot; else (\n<span class=\"ln\">127</span>                        &quot;normal&quot; if risk.get(&quot;status&quot;) == &quot;normal&quot; else None)\n<span class=\"ln\">128</span>                state[&quot;tof_behavior&quot;] = {\n<span class=\"ln\">129</span>                    &quot;posture&quot;: latest.get(&quot;posture&quot;), &quot;posture_ko&quot;: latest.get(&quot;posture_ko&quot;),\n<span class=\"ln\">130</span>                    &quot;posture_conf&quot;: latest.get(&quot;posture_conf&quot;), &quot;presence&quot;: presence, &quot;risk&quot;: risk,\n<span class=\"ln\">131</span>                    &quot;posture_baseline&quot;: {&quot;alert_level&quot;: risk_level, &quot;source&quot;: &quot;current_posture_edge_detector&quot;},\n<span class=\"ln\">132</span>                    &quot;exit_episode&quot;: None,\n<span class=\"ln\">133</span>                    &quot;note&quot;: &quot;현재 자세·가장자리 감지 결과. 이탈 빈도 및 과거 자세 통계는 제공되지 않음.&quot;,\n<span class=\"ln\">134</span>                }\n<span class=\"ln\">135</span>            else:\n<span class=\"ln\">136</span>                state[&quot;tof_behavior_error&quot;] = &quot;최근 ToF 수신 데이터가 없습니다.&quot;\n<span class=\"ln\">137</span>        except (requests.exceptions.RequestException, ValueError):\n<span class=\"ln\">138</span>            state[&quot;tof_behavior_error&quot;] = &quot;ToF 서버 상태를 조회하지 못했습니다.&quot;\n<span class=\"ln\">139</span>\n<span class=\"ln\">140</span>    if mmw_target_id:\n<span class=\"ln\">141</span>        try:\n<span class=\"ln\">142</span>            r = requests.get(f&quot;{MMW_BASE}/mmw/latest&quot;, params={&quot;target&quot;: mmw_target_id}, timeout=3)\n<span class=\"ln\">143</span>            latest = r.json() if r.status_code == 200 else {}\n<span class=\"ln\">144</span>            if latest and _fresh(latest.get(&quot;received_at&quot;), 90):\n<span class=\"ln\">145</span>                state[&quot;mmw_latest&quot;] = latest\n<span class=\"ln\">146</span>            else:\n<span class=\"ln\">147</span>                state[&quot;mmw_latest_error&quot;] = &quot;최근 mmWave 수신 데이터가 없습니다.&quot;\n<span class=\"ln\">148</span>        except (requests.exceptions.RequestException, ValueError):\n<span class=\"ln\">149</span>            state[&quot;mmw_latest_error&quot;] = &quot;mmWave 서버 상태를 조회하지 못했습니다.&quot;\n<span class=\"ln\">150</span>\n<span class=\"ln\">151</span>    return _attach_fall_risk(state, bed_id)</pre></details><details class=\"code\"><summary><span class=\"code-tag\">코드</span> generate_queries() <span class=\"code-loc\">server/ai_agent.py:170–187</span></summary><pre><span class=\"ln\">170</span>@report_trace.traced_stage(&#x27;query_generation&#x27;, &#x27;현재 상황에 필요한 검색 질문 생성&#x27;)\n<span class=\"ln\">171</span>def generate_queries(patient_state: dict, max_queries: int = QUERIES_PER_ROUND_DEFAULT) -&gt; dict:\n<span class=\"ln\">172</span>    &quot;&quot;&quot;현재 상태를 LLM에 넘겨 검색 질의를 생성시킨다. 정직한 실패 shape은 ai_report.call_openai()와 동일.&quot;&quot;&quot;\n<span class=\"ln\">173</span>    user_content = (\n<span class=\"ln\">174</span>        f&quot;환자 현재 상태(JSON):\\n{json.dumps(patient_state, ensure_ascii=False, indent=2, default=str)}\\n\\n&quot;\n<span class=\"ln\">175</span>        f&quot;위 상태에서 낙상 위험과 관련해 확인이 필요한 항목에 대해, 최대 {max_queries}개의 검색 질의를 만드세요.&quot;\n<span class=\"ln\">176</span>    )\n<span class=\"ln\">177</span>    result = ai_report.call_openai(system_prompt=QUERY_GEN_SYSTEM_PROMPT,\n<span class=\"ln\">178</span>                                    user_content=user_content, json_mode=True)\n<span class=\"ln\">179</span>    if not result[&quot;success&quot;]:\n<span class=\"ln\">180</span>        return result\n<span class=\"ln\">181</span>    try:\n<span class=\"ln\">182</span>        parsed = json.loads(result[&quot;text&quot;])\n<span class=\"ln\">183</span>        queries = list(parsed.get(&quot;queries&quot;) or [])[:max_queries]\n<span class=\"ln\">184</span>        return {&quot;success&quot;: True, &quot;queries&quot;: queries, &quot;reasoning&quot;: parsed.get(&quot;reasoning&quot;, &quot;&quot;)}\n<span class=\"ln\">185</span>    except (json.JSONDecodeError, AttributeError) as e:\n<span class=\"ln\">186</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;parse_error&quot;,\n<span class=\"ln\">187</span>                &quot;message&quot;: f&quot;LLM 응답이 JSON 스키마를 따르지 않음: {type(e).__name__}&quot;}</pre></details><details class=\"code\"><summary><span class=\"code-tag\">코드</span> judge_sufficiency() <span class=\"code-loc\">server/ai_agent.py:199–216</span></summary><pre><span class=\"ln\">199</span>@report_trace.traced_stage(&#x27;sufficiency&#x27;, &#x27;근거 충분성 판단·추가 질문&#x27;)\n<span class=\"ln\">200</span>def judge_sufficiency(patient_state: dict, results_so_far: list[dict]) -&gt; dict:\n<span class=\"ln\">201</span>    user_content = (\n<span class=\"ln\">202</span>        f&quot;환자 상태(JSON):\\n{json.dumps(patient_state, ensure_ascii=False, indent=2, default=str)}\\n\\n&quot;\n<span class=\"ln\">203</span>        f&quot;지금까지 검색된 근거(JSON):\\n{json.dumps(results_so_far, ensure_ascii=False, indent=2)}&quot;\n<span class=\"ln\">204</span>    )\n<span class=\"ln\">205</span>    result = ai_report.call_openai(system_prompt=SUFFICIENCY_SYSTEM_PROMPT,\n<span class=\"ln\">206</span>                                    user_content=user_content, json_mode=True)\n<span class=\"ln\">207</span>    if not result[&quot;success&quot;]:\n<span class=\"ln\">208</span>        return result\n<span class=\"ln\">209</span>    try:\n<span class=\"ln\">210</span>        parsed = json.loads(result[&quot;text&quot;])\n<span class=\"ln\">211</span>        return {&quot;success&quot;: True, &quot;sufficient&quot;: bool(parsed.get(&quot;sufficient&quot;)),\n<span class=\"ln\">212</span>                &quot;reasoning&quot;: parsed.get(&quot;reasoning&quot;, &quot;&quot;),\n<span class=\"ln\">213</span>                &quot;additional_queries&quot;: list(parsed.get(&quot;additional_queries&quot;) or [])}\n<span class=\"ln\">214</span>    except (json.JSONDecodeError, AttributeError) as e:\n<span class=\"ln\">215</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;parse_error&quot;,\n<span class=\"ln\">216</span>                &quot;message&quot;: f&quot;LLM 응답이 JSON 스키마를 따르지 않음: {type(e).__name__}&quot;}</pre></details><details class=\"code\"><summary><span class=\"code-tag\">코드</span> investigate() <span class=\"code-loc\">server/ai_agent.py:220–302</span></summary><pre><span class=\"ln\">220</span>@report_trace.traced_run(&#x27;investigation&#x27;)\n<span class=\"ln\">221</span>def investigate(bed_id: str, max_rounds: int = MAX_ROUNDS_DEFAULT,\n<span class=\"ln\">222</span>                 max_queries_per_round: int = QUERIES_PER_ROUND_DEFAULT, top_k: int = 5,\n<span class=\"ln\">223</span>                 search_method: str = &quot;hybrid&quot;) -&gt; dict:\n<span class=\"ln\">224</span>    &quot;&quot;&quot;전체 루프: 상태수집 → query생성 → Hybrid 검색 → 충분성판단 → (부족하면) 추가검색 반복\n<span class=\"ln\">225</span>    → SQL 환자기록은 ①에서 이미 gather_patient_state()로 모아뒀으므로 여기서 다시 붙인다(Hybrid).\n<span class=\"ln\">226</span>\n<span class=\"ln\">227</span>    반환 shape: {&quot;success&quot;:bool, &quot;bed_id&quot;, &quot;patient_state&quot;, &quot;rounds&quot;:[...], &quot;final_results&quot;:[...],\n<span class=\"ln\">228</span>                 &quot;sufficient&quot;:bool, &quot;reasoning&quot;:str}\n<span class=\"ln\">229</span>    이 결과는 STEP 21-23(통합분석/리포트)이 그대로 입력으로 받게 될 재료다 — 이 함수 자체는\n<span class=\"ln\">230</span>    최종 리포트나 위험점수를 만들지 않는다.&quot;&quot;&quot;\n<span class=\"ln\">231</span>    report_trace.emit(&#x27;retrieval_configuration&#x27;, &#x27;running&#x27;, &#x27;문헌 검색 구성 확인&#x27;, {&#x27;method&#x27;: search_method, &#x27;max_rounds&#x27;: max_rounds, &#x27;queries_per_round&#x27;: max_queries_per_round, &#x27;top_k&#x27;: top_k})\n<span class=\"ln\">232</span>    import paper_kb\n<span class=\"ln\">233</span>\n<span class=\"ln\">234</span>    if search_method not in {&quot;hybrid&quot;, &quot;dense&quot;}:\n<span class=\"ln\">235</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;invalid_argument&quot;, &quot;stage&quot;: &quot;search_configuration&quot;,\n<span class=\"ln\">236</span>                &quot;message&quot;: &quot;search_method는 hybrid 또는 dense여야 합니다.&quot;}\n<span class=\"ln\">237</span>    retrieve = paper_kb.search_hybrid if search_method == &quot;hybrid&quot; else paper_kb.search\n<span class=\"ln\">238</span>    patient_state = gather_patient_state(bed_id)\n<span class=\"ln\">239</span>\n<span class=\"ln\">240</span>    rounds: list[dict] = []\n<span class=\"ln\">241</span>    all_results: dict[str, dict] = {}  # chunk_id -&gt; result (중복 검색 결과 제거)\n<span class=\"ln\">242</span>    emr_results, emr_statuses = {}, {}\n<span class=\"ln\">243</span>\n<span class=\"ln\">244</span>    qgen = generate_queries(patient_state, max_queries=max_queries_per_round)\n<span class=\"ln\">245</span>    if not qgen[&quot;success&quot;]:\n<span class=\"ln\">246</span>        return {&quot;success&quot;: False, **{k: v for k, v in qgen.items() if k != &quot;success&quot;},\n<span class=\"ln\">247</span>                &quot;bed_id&quot;: bed_id, &quot;patient_state&quot;: patient_state, &quot;stage&quot;: &quot;generate_queries&quot;}\n<span class=\"ln\">248</span>\n<span class=\"ln\">249</span>    queries = qgen[&quot;queries&quot;]\n<span class=\"ln\">250</span>    sufficiency = {&quot;sufficient&quot;: False, &quot;reasoning&quot;: &quot;&quot;}\n<span class=\"ln\">251</span>\n<span class=\"ln\">252</span>    for round_i in range(max_rounds):\n<span class=\"ln\">253</span>        if not queries:\n<span class=\"ln\">254</span>            break\n<span class=\"ln\">255</span>        round_results = []\n<span class=\"ln\">256</span>        for q in queries:\n<span class=\"ln\">257</span>            # Titles/authors alone cannot substantiate a report&#x27;s medical claims.\n<span class=\"ln\">258</span>            sr = retrieve(q, top_k=top_k * 3)\n<span class=\"ln\">259</span>            if not sr[&quot;success&quot;]:\n<span class=\"ln\">260</span>                # Vector DB 쪽이 실패(키 미설정 등)해도 지금까지 모은 SQL 상태는 살려서 반환 —\n<span class=\"ln\">261</span>                # &quot;검색을 못 했다&quot;와 &quot;검색했는데 결과가 없다&quot;를 구분해 정직하게 기록.\n<span class=\"ln\">262</span>                return {&quot;success&quot;: False, **{k: v for k, v in sr.items() if k != &quot;success&quot;},\n<span class=\"ln\">263</span>                        &quot;bed_id&quot;: bed_id, &quot;patient_state&quot;: patient_state,\n<span class=\"ln\">264</span>                        &quot;rounds&quot;: rounds, &quot;stage&quot;: &quot;vector_search&quot;, &quot;search_method&quot;: search_method, &quot;query&quot;: q}\n<span class=\"ln\">265</span>            import emr_kb\n<span class=\"ln\">266</span>            emr_result = emr_kb.search(bed_id, q, top_k=3)\n<span class=\"ln\">267</span>            for record in emr_result.get(&#x27;results&#x27;, []) if emr_result.get(&#x27;success&#x27;) else []:\n<span class=\"ln\">268</span>                emr_results[record[&#x27;chunk_id&#x27;]] = record\n<span class=\"ln\">269</span>            status_key = emr_result.get(&#x27;error_type&#x27;) or (&#x27;complete&#x27; if (emr_result.get(&#x27;coverage&#x27;) or {}).get(&#x27;complete&#x27;) else &#x27;partial&#x27;)\n<span class=\"ln\">270</span>            emr_statuses[status_key] = {k:emr_result.get(k) for k in (&#x27;success&#x27;,&#x27;error_type&#x27;,&#x27;message&#x27;,&#x27;coverage&#x27;,&#x27;warning&#x27;)}\n<span class=\"ln\">271</span>            content_results = [r for r in sr[&quot;results&quot;] if r.get(&quot;section&quot;) != &quot;identity&quot;][:top_k]\n<span class=\"ln\">272</span>            report_trace.emit(&#x27;evidence_selection&#x27;, &#x27;completed&#x27;, &#x27;실제 검색 근거 선택&#x27;, {\n<span class=\"ln\">273</span>                &#x27;round&#x27;: round_i + 1, &#x27;query&#x27;: q, &#x27;method&#x27;: search_method,\n<span class=\"ln\">274</span>                &#x27;retrieved&#x27;: len(sr[&#x27;results&#x27;]), &#x27;selected&#x27;: len(content_results),\n<span class=\"ln\">275</span>                &#x27;excluded_identity&#x27;: sum(r.get(&#x27;section&#x27;) == &#x27;identity&#x27; for r in sr[&#x27;results&#x27;]),\n<span class=\"ln\">276</span>                &#x27;evidence&#x27;: content_results,\n<span class=\"ln\">277</span>            })\n<span class=\"ln\">278</span>            for r in content_results:\n<span class=\"ln\">279</span>                all_results[r[&quot;chunk_id&quot;]] = r\n<span class=\"ln\">280</span>                round_results.append(r)\n<span class=\"ln\">281</span>        rounds.append({&quot;round&quot;: round_i + 1, &quot;queries&quot;: queries, &quot;n_results&quot;: len(round_results),\n<span class=\"ln\">282</span>                       &quot;search_method&quot;: search_method})\n<span class=\"ln\">283</span>\n<span class=\"ln\">284</span>        sufficiency = judge_sufficiency(patient_state, list(all_results.values()))\n<span class=\"ln\">285</span>        if not sufficiency[&quot;success&quot;]:\n<span class=\"ln\">286</span>            # 충분성 판단(LLM) 실패해도 지금까지 모은 검색결과는 유효하니 그대로 반환.\n<span class=\"ln\">287</span>            break\n<span class=\"ln\">288</span>        if sufficiency[&quot;sufficient&quot;] or round_i == max_rounds - 1:\n<span class=\"ln\">289</span>            break\n<span class=\"ln\">290</span>        queries = sufficiency[&quot;additional_queries&quot;][:max_queries_per_round]\n<span class=\"ln\">291</span>        report_trace.emit(&#x27;additional_queries&#x27;, &#x27;completed&#x27;, &#x27;근거 부족으로 재검색 질문 선택&#x27;, {&#x27;round&#x27;: round_i + 2, &#x27;queries&#x27;: queries})\n<span class=\"ln\">292</span>\n<span class=\"ln\">293</span>    return {\n<span class=\"ln\">294</span>        &quot;success&quot;: True, &quot;bed_id&quot;: bed_id, &quot;patient_state&quot;: patient_state,\n<span class=\"ln\">295</span>        &quot;rounds&quot;: rounds, &quot;final_results&quot;: list(all_results.values()),\n<span class=\"ln\">296</span>        &quot;emr_retrieval&quot;: {&quot;results&quot;:list(emr_results.values()), &quot;statuses&quot;:list(emr_statuses.values()),\n<span class=\"ln\">297</span>                          &quot;method&quot;:&quot;local-text-hash-v1&quot;, &quot;note&quot;:&quot;환자 원문 검색; 논문 근거와 별도, 어휘 점수는 확률 아님&quot;},\n<span class=\"ln\">298</span>        &quot;sufficient&quot;: sufficiency.get(&quot;sufficient&quot;, False),\n<span class=\"ln\">299</span>        &quot;reasoning&quot;: sufficiency.get(&quot;reasoning&quot;, &quot;&quot;),\n<span class=\"ln\">300</span>        &quot;initial_query_reasoning&quot;: qgen.get(&quot;reasoning&quot;, &quot;&quot;),\n<span class=\"ln\">301</span>        &quot;search_method&quot;: search_method,\n<span class=\"ln\">302</span>    }</pre></details></details>\n<details class=\"step\"><summary><span class=\"num\">5-2</span>논문 지식 베이스</summary><div class=\"plain\"><p>등록 논문 73편을 문단 단위 조각 631개로 나눠 OpenAI 임베딩(text-embedding-3-small) 벡터로 바꿔 LanceDB(server/lancedb_store/paper_chunks)에 저장했다.</p></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> embed_texts() <span class=\"code-loc\">server/paper_kb.py:189–240</span></summary><pre><span class=\"ln\">189</span>@report_trace.traced_stage(&#x27;embedding&#x27;, &#x27;검색 질의 임베딩&#x27;)\n<span class=\"ln\">190</span>def embed_texts(texts: list[str], model: str = EMBEDDING_MODEL, timeout: float = 60.0) -&gt; dict:\n<span class=\"ln\">191</span>    &quot;&quot;&quot;OpenAI Embeddings API 호출. 반환: {&quot;success&quot;:bool, &quot;embeddings&quot;:[[float,...],...]} 또는\n<span class=\"ln\">192</span>    ai_report.call_openai()과 동일한 {&quot;success&quot;:False,&quot;error_type&quot;:...,&quot;message&quot;:...}.\n<span class=\"ln\">193</span>    키가 없으면 절대 가짜 벡터를 만들지 않고 정직하게 실패를 반환한다.&quot;&quot;&quot;\n<span class=\"ln\">194</span>    key = ai_report.get_api_key()\n<span class=\"ln\">195</span>    if not key:\n<span class=\"ln\">196</span>        return {\n<span class=\"ln\">197</span>            &quot;success&quot;: False, &quot;error_type&quot;: &quot;missing_key&quot;,\n<span class=\"ln\">198</span>            &quot;message&quot;: &quot;.env 또는 환경변수에 OPENAI_API_KEY가 설정되어 있지 않습니다. &quot;\n<span class=\"ln\">199</span>                       &quot;코드 문제가 아니라 키 미설정입니다 — 이 경우 검색은 임베딩 없이 동작할 수 없습니다.&quot;,\n<span class=\"ln\">200</span>        }\n<span class=\"ln\">201</span>    if not texts:\n<span class=\"ln\">202</span>        return {&quot;success&quot;: True, &quot;embeddings&quot;: []}\n<span class=\"ln\">203</span>\n<span class=\"ln\">204</span>    try:\n<span class=\"ln\">205</span>        resp = requests.post(\n<span class=\"ln\">206</span>            EMBEDDING_URL,\n<span class=\"ln\">207</span>            headers={&quot;Authorization&quot;: f&quot;Bearer {key}&quot;, &quot;Content-Type&quot;: &quot;application/json&quot;},\n<span class=\"ln\">208</span>            json={&quot;model&quot;: model, &quot;input&quot;: texts},\n<span class=\"ln\">209</span>            timeout=timeout,\n<span class=\"ln\">210</span>        )\n<span class=\"ln\">211</span>    except requests.exceptions.Timeout:\n<span class=\"ln\">212</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;timeout&quot;,\n<span class=\"ln\">213</span>                &quot;message&quot;: f&quot;OpenAI Embeddings API 응답 시간 초과({timeout}s) — 네트워크 문제일 가능성이 높습니다.&quot;}\n<span class=\"ln\">214</span>    except requests.exceptions.ConnectionError:\n<span class=\"ln\">215</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;network&quot;,\n<span class=\"ln\">216</span>                &quot;message&quot;: &quot;OpenAI Embeddings API 연결 실패 — 네트워크/방화벽 문제일 가능성이 높습니다.&quot;}\n<span class=\"ln\">217</span>    except requests.exceptions.RequestException as e:\n<span class=\"ln\">218</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;request_error&quot;,\n<span class=\"ln\">219</span>                &quot;message&quot;: f&quot;요청 중 예외 발생: {type(e).__name__}&quot;}\n<span class=\"ln\">220</span>\n<span class=\"ln\">221</span>    if resp.status_code == 401:\n<span class=\"ln\">222</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;auth&quot;,\n<span class=\"ln\">223</span>                &quot;message&quot;: &quot;인증 실패(401) — API 키가 비어있거나 유효하지 않습니다.&quot;}\n<span class=\"ln\">224</span>    if resp.status_code == 429:\n<span class=\"ln\">225</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;rate_limit&quot;,\n<span class=\"ln\">226</span>                &quot;message&quot;: &quot;요청 한도 초과(429) — 크레딧/쿼터 문제일 수 있습니다.&quot;}\n<span class=\"ln\">227</span>    if resp.status_code != 200:\n<span class=\"ln\">228</span>        snippet = resp.text[:300] if resp.text else &quot;&quot;\n<span class=\"ln\">229</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: f&quot;http_{resp.status_code}&quot;,\n<span class=\"ln\">230</span>                &quot;message&quot;: f&quot;OpenAI Embeddings API 오류 응답: {snippet}&quot;}\n<span class=\"ln\">231</span>\n<span class=\"ln\">232</span>    try:\n<span class=\"ln\">233</span>        data = resp.json()\n<span class=\"ln\">234</span>        vectors = [item[&quot;embedding&quot;] for item in sorted(data[&quot;data&quot;], key=lambda x: x[&quot;index&quot;])]\n<span class=\"ln\">235</span>    except (KeyError, ValueError, json.JSONDecodeError) as e:\n<span class=\"ln\">236</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;parse_error&quot;,\n<span class=\"ln\">237</span>                &quot;message&quot;: f&quot;응답 파싱 실패: {type(e).__name__}&quot;}\n<span class=\"ln\">238</span>\n<span class=\"ln\">239</span>    return {&quot;success&quot;: True, &quot;embeddings&quot;: vectors, &quot;model&quot;: model,\n<span class=\"ln\">240</span>            &quot;usage&quot;: data.get(&quot;usage&quot;)}</pre></details></details>\n<details class=\"step\"><summary><span class=\"num\">5-3</span>하이브리드 검색 — 벡터 + BM25 + RRF</summary><div class=\"plain\"><div class=\"formula\">벡터: 질문 벡터와 조각 벡터의 코사인 유사도 순위<br>BM25: 질문 단어가 조각에 얼마나 나오나(드문 단어일수록 가중) 순위<br>RRF 점수 = Σ 1/(60 + 순위)   — 점수 크기 대신 순위만 합침(학습 필요 없음)</div></div><div class=\"detail\"><div class=\"detail-h\">엔지니어 메모</div><p>RRF 점수는 순위용일 뿐 확률·신뢰도가 아니다. 18개 개발용 질의로 벡터 단독과 비교했다(research/alternatives).</p></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> search_hybrid() <span class=\"code-loc\">server/paper_kb.py:367–421</span></summary><pre><span class=\"ln\">367</span>@report_trace.traced_stage(&#x27;hybrid_search&#x27;, &#x27;벡터·BM25·RRF 하이브리드 검색&#x27;)\n<span class=\"ln\">368</span>def search_hybrid(query: str, top_k: int = 5, k_rrf: int = 60) -&gt; dict:\n<span class=\"ln\">369</span>    &quot;&quot;&quot;벡터 검색(cosine) + BM25(키워드) 결과를 Reciprocal Rank Fusion(RRF)으로 결합한\n<span class=\"ln\">370</span>    하이브리드 검색. 2026-09 문헌조사 근거: Sawarkar, Mangal &amp; Solanki (2024), &quot;Blended\n<span class=\"ln\">371</span>    RAG: Improving RAG Accuracy with Semantic Search and Hybrid Query-Based Retrievers&quot;,\n<span class=\"ln\">372</span>    arXiv:2404.07220 — dense+sparse 하이브리드가 데이터셋에 따라 순수 dense 단독 대비\n<span class=\"ln\">373</span>    NDCG@10을 유의미하게 개선한다고 보고(그들의 Elasticsearch+ELSER 파이프라인 실험이며\n<span class=\"ln\">374</span>    우리 자료가 아니므로 &quot;그러니 낫다&quot;가 아니라 &quot;그래서 우리 데이터로 직접 비교할 가치가\n<span class=\"ln\">375</span>    있다&quot;). 2026-09-18: ai_agent의 기본 검색에 연결하고 18개 근거 연결 질의로 비교했다.\n<span class=\"ln\">376</span>    정답셋은 독립 검수 전의 개발용 seed이며 상세 결과는 research/alternatives/artifacts에 있다.\n<span class=\"ln\">377</span>\n<span class=\"ln\">378</span>    RRF 자체는 Cormack, Clarke &amp; Buettcher (2009)의 표준 랭킹 결합 공식(1/(k+rank) 합산)이며\n<span class=\"ln\">379</span>    학습이 필요 없다 — 우리에게 없는 &#x27;융합 학습용 라벨 데이터&#x27;가 필요 없다는 뜻.&quot;&quot;&quot;\n<span class=\"ln\">380</span>    if not isinstance(top_k, int) or top_k &lt; 1 or not isinstance(k_rrf, int) or k_rrf &lt; 1:\n<span class=\"ln\">381</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;invalid_argument&quot;, &quot;message&quot;: &quot;top_k와 k_rrf는 양의 정수여야 합니다.&quot;}\n<span class=\"ln\">382</span>    db_conn = _connect()\n<span class=\"ln\">383</span>    if not _table_exists(db_conn, PAPERS_TABLE):\n<span class=\"ln\">384</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;no_index&quot;,\n<span class=\"ln\">385</span>                &quot;message&quot;: &quot;paper_kb.build_index()를 먼저 실행해야 합니다.&quot;}\n<span class=\"ln\">386</span>    tbl = db_conn.open_table(PAPERS_TABLE)\n<span class=\"ln\">387</span>    all_rows = [r for r in tbl.to_arrow().to_pylist()]\n<span class=\"ln\">388</span>    n_candidates = len(all_rows)\n<span class=\"ln\">389</span>    if n_candidates == 0:\n<span class=\"ln\">390</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;no_embeddings&quot;,\n<span class=\"ln\">391</span>                &quot;message&quot;: &quot;인덱스에 임베딩된 chunk가 없습니다(OPENAI_API_KEY 미설정 상태로 build_index()가 &quot;\n<span class=\"ln\">392</span>                           &quot;실행됐을 가능성) — 키를 설정한 뒤 build_index()를 다시 실행하세요.&quot;}\n<span class=\"ln\">393</span>\n<span class=\"ln\">394</span>    q_result = embed_texts([query])\n<span class=\"ln\">395</span>    if not q_result[&quot;success&quot;]:\n<span class=\"ln\">396</span>        return q_result\n<span class=\"ln\">397</span>    q_vec = q_result[&quot;embeddings&quot;][0]\n<span class=\"ln\">398</span>    report_trace.emit(&#x27;vector_index&#x27;, &#x27;completed&#x27;, &#x27;실제 임베딩 인덱스와 질의 벡터 확인&#x27;, {&#x27;database&#x27;: LANCEDB_DIR, &#x27;table&#x27;: PAPERS_TABLE, &#x27;candidate_chunks&#x27;: n_candidates, &#x27;embedding_model&#x27;: q_result.get(&#x27;model&#x27;, EMBEDDING_MODEL), &#x27;query_vector_dimensions&#x27;: len(q_vec), &#x27;distance&#x27;: &#x27;cosine&#x27;})\n<span class=\"ln\">399</span>\n<span class=\"ln\">400</span>    # 1) 벡터 랭킹 — 전체 후보를 코사인 유사도로 정렬(순위만 쓰므로 전체가 필요)\n<span class=\"ln\">401</span>    vec_rows = tbl.search(q_vec).metric(&quot;cosine&quot;).limit(n_candidates).to_list()\n<span class=\"ln\">402</span>    # 2) BM25: 0점/음수 무매치 문서는 투표하지 않는다. 동점은 같은 순위.\n<span class=\"ln\">403</span>    by_id = {r[&quot;chunk_id&quot;]: r for r in all_rows}\n<span class=\"ln\">404</span>    corpus_ids = [r[&quot;chunk_id&quot;] for r in all_rows]\n<span class=\"ln\">405</span>    lexical = dict(zip(corpus_ids, sparse_scores(query, [r[&quot;original_text&quot;] for r in all_rows])))\n<span class=\"ln\">406</span>    # 3) RRF — 1-based ranks, same pure function as the offline evaluator.\n<span class=\"ln\">407</span>    fused, fused_scores, vec_rank, bm25_rank = fuse_rankings(\n<span class=\"ln\">408</span>        [r[&quot;chunk_id&quot;] for r in vec_rows], lexical, k_rrf=k_rrf,\n<span class=\"ln\">409</span>    )\n<span class=\"ln\">410</span>\n<span class=\"ln\">411</span>    report_trace.emit(&#x27;ranking_fusion&#x27;, &#x27;completed&#x27;, &#x27;벡터 순위와 BM25 순위를 RRF로 결합&#x27;, {&#x27;query&#x27;: query, &#x27;formula&#x27;: &#x27;Σ 1 / (k_rrf + rank)&#x27;, &#x27;k_rrf&#x27;: k_rrf, &#x27;rank_base&#x27;: 1, &#x27;score_kind&#x27;: &#x27;순위 점수(확률 아님)&#x27;, &#x27;selected&#x27;: [{&#x27;chunk_id&#x27;: cid, &#x27;vector_rank&#x27;: vec_rank.get(cid), &#x27;bm25_rank&#x27;: bm25_rank.get(cid), &#x27;bm25_score&#x27;: lexical.get(cid), &#x27;rrf_score&#x27;: fused_scores[cid]} for cid in fused[:top_k]]})\n<span class=\"ln\">412</span>    results = []\n<span class=\"ln\">413</span>    for cid in fused[:top_k]:\n<span class=\"ln\">414</span>        r = by_id[cid]\n<span class=\"ln\">415</span>        rrf = fused_scores[cid]\n<span class=\"ln\">416</span>        results.append({&quot;score&quot;: round(rrf, 5), &quot;chunk_id&quot;: cid, &quot;paper_id&quot;: r[&quot;paper_id&quot;],\n<span class=\"ln\">417</span>                         &quot;title&quot;: r[&quot;title&quot;], &quot;section&quot;: r[&quot;section&quot;], &quot;original_text&quot;: r[&quot;original_text&quot;],\n<span class=\"ln\">418</span>                         &quot;source_url&quot;: r[&quot;source_url&quot;], &quot;doi&quot;: r[&quot;doi&quot;],\n<span class=\"ln\">419</span>                         &quot;vector_rank&quot;: vec_rank.get(cid), &quot;bm25_rank&quot;: bm25_rank.get(cid)})\n<span class=\"ln\">420</span>    return {&quot;success&quot;: True, &quot;query&quot;: query, &quot;n_candidates&quot;: n_candidates,\n<span class=\"ln\">421</span>            &quot;method&quot;: &quot;hybrid_rrf_v2&quot;, &quot;rank_base&quot;: 1, &quot;score_kind&quot;: &quot;ranking_score_not_probability&quot;, &quot;results&quot;: results}</pre></details><details class=\"code\"><summary><span class=\"code-tag\">코드</span> sparse_scores() <span class=\"code-loc\">server/retrieval.py:16–20</span></summary><pre><span class=\"ln\">16</span>def sparse_scores(query, documents):\n<span class=\"ln\">17</span>    corpus = [tokenize(text) for text in documents]\n<span class=\"ln\">18</span>    if not any(corpus):\n<span class=\"ln\">19</span>        return [0.0] * len(corpus)\n<span class=\"ln\">20</span>    return [float(score) for score in BM25Okapi(corpus).get_scores(tokenize(query))]</pre></details><details class=\"code\"><summary><span class=\"code-tag\">코드</span> fuse_rankings() <span class=\"code-loc\">server/retrieval.py:23–44</span></summary><pre><span class=\"ln\">23</span>def fuse_rankings(vector_ids, lexical_scores, k_rrf=60):\n<span class=\"ln\">24</span>    &quot;&quot;&quot;Ignore nonpositive lexical matches; equal BM25 scores receive equal rank.\n<span class=\"ln\">25</span>\n<span class=\"ln\">26</span>    Without this abstention a no-match query acquires an arbitrary second\n<span class=\"ln\">27</span>    ranking based solely on insertion order, corrupting dense retrieval.\n<span class=\"ln\">28</span>    &quot;&quot;&quot;\n<span class=\"ln\">29</span>    if not isinstance(k_rrf, int) or k_rrf &lt; 1:\n<span class=\"ln\">30</span>        raise ValueError(&quot;k_rrf must be a positive integer&quot;)\n<span class=\"ln\">31</span>    dense_rank = {cid: rank for rank, cid in enumerate(dict.fromkeys(vector_ids), 1)}\n<span class=\"ln\">32</span>    positive = sorted(((cid, float(score)) for cid, score in lexical_scores.items()\n<span class=\"ln\">33</span>                       if math.isfinite(float(score)) and float(score) &gt; 0), key=lambda p: (-p[1], p[0]))\n<span class=\"ln\">34</span>    sparse_rank = {}\n<span class=\"ln\">35</span>    previous, rank = None, 0\n<span class=\"ln\">36</span>    for position, (cid, score) in enumerate(positive, 1):\n<span class=\"ln\">37</span>        if previous is None or score != previous:\n<span class=\"ln\">38</span>            rank = position\n<span class=\"ln\">39</span>        sparse_rank[cid], previous = rank, score\n<span class=\"ln\">40</span>    scores = {cid: (1/(k_rrf+dense_rank[cid]) if cid in dense_rank else 0) +\n<span class=\"ln\">41</span>                   (1/(k_rrf+sparse_rank[cid]) if cid in sparse_rank else 0)\n<span class=\"ln\">42</span>              for cid in dense_rank.keys() | sparse_rank.keys()}\n<span class=\"ln\">43</span>    order = sorted(scores, key=lambda cid: (-scores[cid], dense_rank.get(cid, math.inf), cid))\n<span class=\"ln\">44</span>    return order, scores, dense_rank, sparse_rank</pre></details></details>\n<details class=\"step\"><summary><span class=\"num\">5-4</span>환자 기록(EMR) 검색 — 신경망이 아닌 해시 벡터</summary><div class=\"plain\"><div class=\"formula\">글자 → 단어 + 2·3글자 조각 → SHA-256 해시로 512칸 중 한 칸에 ±1 → 길이 1로 정규화</div></div><div class=\"detail\"><div class=\"detail-h\">엔지니어 메모</div><p>환자 기록을 외부로 보내지 않으려고 Pi 안에서 만드는 <b>어휘 유사도</b> 벡터다(뜻 이해 아님). 환자별로 걸러서 다른 환자 기록이 섞이지 않는다. 검색 점수는 확률이 아니다.</p></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> local_embedding() <span class=\"code-loc\">server/emr_kb.py:25–34</span></summary><pre><span class=\"ln\">25</span>def local_embedding(text):\n<span class=\"ln\">26</span>    normalized = re.sub(r&#x27;\\s+&#x27;, &#x27; &#x27;, str(text).lower()).strip()\n<span class=\"ln\">27</span>    tokens = re.findall(r&#x27;\\w+&#x27;, normalized)\n<span class=\"ln\">28</span>    features = tokens + [normalized[i:i+n] for n in (2, 3) for i in range(max(0, len(normalized)-n+1))]\n<span class=\"ln\">29</span>    vector = [0.0] * DIMENSIONS\n<span class=\"ln\">30</span>    for feature in features:\n<span class=\"ln\">31</span>        digest = hashlib.sha256(feature.encode()).digest()\n<span class=\"ln\">32</span>        vector[int.from_bytes(digest[:4], &#x27;big&#x27;) % DIMENSIONS] += 1 if digest[4] &amp; 1 else -1\n<span class=\"ln\">33</span>    norm = math.sqrt(sum(x*x for x in vector))\n<span class=\"ln\">34</span>    return [x/norm for x in vector] if norm else vector</pre></details><details class=\"code\"><summary><span class=\"code-tag\">코드</span> search() <span class=\"code-loc\">server/emr_kb.py:159–190</span></summary><pre><span class=\"ln\">159</span>@report_trace.traced_stage(&#x27;emr_search&#x27;, &#x27;현재 환자의 EMR 벡터 검색&#x27;)\n<span class=\"ln\">160</span>def search(patient_id, query, top_k=5):\n<span class=\"ln\">161</span>    if not isinstance(query, str) or not query.strip() or len(query) &gt; 2000:\n<span class=\"ln\">162</span>        return {&#x27;success&#x27;: False, &#x27;error_type&#x27;: &#x27;bad_query&#x27;, &#x27;message&#x27;: &#x27;1~2000자 검색어가 필요합니다.&#x27;}\n<span class=\"ln\">163</span>    if type(top_k) is not int or not 1 &lt;= top_k &lt;= 20:\n<span class=\"ln\">164</span>        return {&#x27;success&#x27;: False, &#x27;error_type&#x27;: &#x27;bad_top_k&#x27;, &#x27;message&#x27;: &#x27;top_k는 1~20입니다.&#x27;}\n<span class=\"ln\">165</span>    try:\n<span class=\"ln\">166</span>        source = {c[&#x27;chunk_id&#x27;]:c[&#x27;content_hash&#x27;] for c in chunks_for(patient_id)}\n<span class=\"ln\">167</span>        if not Path(STORE).exists():\n<span class=\"ln\">168</span>            return {&#x27;success&#x27;: False, &#x27;error_type&#x27;: &#x27;no_index&#x27;, &#x27;message&#x27;: &#x27;EMR 벡터 인덱스가 없습니다.&#x27;}\n<span class=\"ln\">169</span>        conn = _connection()\n<span class=\"ln\">170</span>        if not _exists(conn, TABLE):\n<span class=\"ln\">171</span>            return {&#x27;success&#x27;: False, &#x27;error_type&#x27;: &#x27;no_index&#x27;, &#x27;message&#x27;: &#x27;EMR 벡터 인덱스가 없습니다.&#x27;}\n<span class=\"ln\">172</span>        table = conn.open_table(TABLE)\n<span class=\"ln\">173</span>        current_ids = [r[&#x27;chunk_id&#x27;] for r in _rows(table,patient_id)\n<span class=\"ln\">174</span>                       if source.get(r[&#x27;chunk_id&#x27;]) == r[&#x27;content_hash&#x27;] and r[&#x27;embedding_model&#x27;] == LOCAL_MODEL]\n<span class=\"ln\">175</span>        coverage = {&#x27;n_source_chunks&#x27;:len(source),&#x27;n_current&#x27;:len(current_ids),\n<span class=\"ln\">176</span>                    &#x27;complete&#x27;:len(source)==len(current_ids)}\n<span class=\"ln\">177</span>        if current_ids:\n<span class=\"ln\">178</span>            eligible = &#x27;,&#x27;.join(&quot;&#x27;&quot;+cid.replace(&quot;&#x27;&quot;,&quot;&#x27;&#x27;&quot;)+&quot;&#x27;&quot; for cid in current_ids)\n<span class=\"ln\">179</span>            rows = table.search(local_embedding(query)).metric(&#x27;cosine&#x27;).where(\n<span class=\"ln\">180</span>                _filter(patient_id)+f&#x27; AND chunk_id IN ({eligible})&#x27;, prefilter=True).limit(top_k).to_list()\n<span class=\"ln\">181</span>        else:\n<span class=\"ln\">182</span>            rows = []\n<span class=\"ln\">183</span>        results = [{k:v for k,v in r.items() if k not in (&#x27;vector&#x27;,&#x27;_distance&#x27;)} |\n<span class=\"ln\">184</span>                   {&#x27;score&#x27;: round(1-r[&#x27;_distance&#x27;], 5)} for r in rows\n<span class=\"ln\">185</span>                   if source.get(r[&#x27;chunk_id&#x27;]) == r[&#x27;content_hash&#x27;]][:top_k]\n<span class=\"ln\">186</span>        return {&#x27;success&#x27;: True, &#x27;patient_id&#x27;: patient_id, &#x27;query&#x27;: query, &#x27;method&#x27;: LOCAL_MODEL,\n<span class=\"ln\">187</span>                &#x27;table&#x27;: TABLE, &#x27;coverage&#x27;:coverage, &#x27;warning&#x27;:None if coverage[&#x27;complete&#x27;] else &#x27;일부 원문 벡터 미갱신; 원문 전체는 SQL에 유지됩니다.&#x27;,\n<span class=\"ln\">188</span>                &#x27;score_kind&#x27;: &#x27;lexical_cosine_not_probability&#x27;, &#x27;results&#x27;: results}\n<span class=\"ln\">189</span>    except Exception as exc:\n<span class=\"ln\">190</span>        return {&#x27;success&#x27;: False, &#x27;error_type&#x27;: type(exc).__name__, &#x27;message&#x27;: &#x27;EMR 벡터 검색을 완료하지 못했습니다.&#x27;}</pre></details></details>\n<div class=\"cite\">Robertson S, Zaragoza H. The Probabilistic Relevance Framework: BM25 and Beyond. 2009. · Cormack GV, Clarke CLA, Büttcher S. Reciprocal Rank Fusion. SIGIR 2009. · Sawarkar K et al. Blended RAG. arXiv:2404.07220, 2024.</div>\n</section><section class=\"part\" id=\"report\" hidden><div class=\"part-head\"><a href=\"#home\" class=\"back\">← 전체 지도</a><h2>6. AI 종합 리포트 — 계산은 서버, 문장은 LLM</h2><p class=\"sub\">15개 항목 리포트가 만들어지는 과정과 안전장치</p></div>\n<div class=\"easy\"><b>쉽게 말하면</b> 5장에서 모은 재료(환자 기록·센서 판정·보행 예측·논문 근거)를 한 JSON으로 묶어 LLM에 주고 '이 사실만으로 15개 항목을 쓰라'고 한다. 위험 점수는 LLM이 아니라 서버가 미리 계산한다. 응답 형식을 검사하고, 저장 뒤 규칙 검토(7장)를 붙이고, 그래프 숫자도 서버가 넣는다.</div>\n<details class=\"step\"><summary><span class=\"num\">6-1</span>위험 점수(서버 계산)</summary><div class=\"plain\"><div class=\"formula\">센서 단계 → 점수: 정상 0.1 · 주의 0.4 · 경고 0.7 · 위험 0.95<br>종합 = 확보된 신호 중 최댓값 · 신호 확보 비율 = 확보 신호 수 / 3   (낙상 확률 아님)</div></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> compute_risk_score() <span class=\"code-loc\">server/integrated_analysis.py:55–84</span></summary><pre><span class=\"ln\">55</span>def compute_risk_score(patient_state: dict) -&gt; dict:\n<span class=\"ln\">56</span>    &quot;&quot;&quot;이미 계산된 alert_level(ToF 자세·ToF 이탈·mmWave 보행 3종)만으로 위험도를 정량화한다.\n<span class=\"ln\">57</span>    셋 중 가장 위험한 신호를 대표값으로 삼는다(평균을 쓰면 한 센서만 위험해도 희석되어 과소평가될\n<span class=\"ln\">58</span>    수 있으므로 max를 택함 — 근거: 04번 탭 융합 설계의 &quot;결정레벨에서 보수적으로 합친다&quot;는 원칙과 동일).&quot;&quot;&quot;\n<span class=\"ln\">59</span>    tof = patient_state.get(&quot;tof_behavior&quot;) or {}\n<span class=\"ln\">60</span>    mmw = patient_state.get(&quot;mmw_latest&quot;) or {}\n<span class=\"ln\">61</span>\n<span class=\"ln\">62</span>    posture_level = (tof.get(&quot;posture_baseline&quot;) or {}).get(&quot;alert_level&quot;)\n<span class=\"ln\">63</span>    exit_level = (tof.get(&quot;exit_episode&quot;) or {}).get(&quot;alert_level&quot;)\n<span class=\"ln\">64</span>    mmw_level = mmw.get(&quot;alert_level&quot;) if not mmw.get(&quot;measuring_held&quot;) and (mmw.get(&quot;quality&quot;) or {}).get(&quot;reliable&quot;) is not False else None\n<span class=\"ln\">65</span>    # 개인 기준이 생기기 전의 &#x27;잠정&#x27; 보행 판정(문헌 기대 범위 비교)은 정식 위험 점수에 넣지 않고 따로 보여준다.\n<span class=\"ln\">66</span>    # 단 높이 급강하(낙상) 절대 규칙에서 나온 critical은 잠정 여부와 관계없이 반영한다.\n<span class=\"ln\">67</span>    provisional = {}\n<span class=\"ln\">68</span>    if mmw_level and mmw.get(&quot;provisional&quot;) and mmw_level != &quot;critical&quot;:\n<span class=\"ln\">69</span>        provisional[&quot;mmwave_gait&quot;] = mmw_level\n<span class=\"ln\">70</span>        mmw_level = None\n<span class=\"ln\">71</span>\n<span class=\"ln\">72</span>    components = {\n<span class=\"ln\">73</span>        &quot;tof_posture&quot;: posture_level, &quot;tof_exit&quot;: exit_level, &quot;mmwave_gait&quot;: mmw_level,\n<span class=\"ln\">74</span>    }\n<span class=\"ln\">75</span>    scored = {k: RISK_LEVEL_SCORE[v] for k, v in components.items() if v in RISK_LEVEL_SCORE}\n<span class=\"ln\">76</span>    combined = max(scored.values()) if scored else None\n<span class=\"ln\">77</span>    dominant = max(scored, key=scored.get) if scored else None\n<span class=\"ln\">78</span>\n<span class=\"ln\">79</span>    return {\n<span class=\"ln\">80</span>        &quot;component_levels&quot;: components, &quot;component_scores&quot;: scored,\n<span class=\"ln\">81</span>        &quot;combined_risk_score&quot;: combined, &quot;dominant_signal&quot;: dominant,\n<span class=\"ln\">82</span>        &quot;provisional_levels&quot;: provisional,\n<span class=\"ln\">83</span>        &quot;method&quot;: &quot;max_of_existing_alert_level_scores_v1&quot;,\n<span class=\"ln\">84</span>    }</pre></details><details class=\"code\"><summary><span class=\"code-tag\">코드</span> compute_data_confidence() <span class=\"code-loc\">server/integrated_analysis.py:87–94</span></summary><pre><span class=\"ln\">87</span>def compute_data_confidence(patient_state: dict, risk: dict) -&gt; float | None:\n<span class=\"ln\">88</span>    &quot;&quot;&quot;데이터 신뢰도 — 몇 개 신호가 실제로 확보됐는지 비율로. 신호가 하나도 없으면 None(모른다를\n<span class=\"ln\">89</span>    0으로 위장하지 않음).&quot;&quot;&quot;\n<span class=\"ln\">90</span>    total = 3  # tof_posture, tof_exit, mmwave_gait\n<span class=\"ln\">91</span>    have = len(risk[&quot;component_scores&quot;])\n<span class=\"ln\">92</span>    if have == 0:\n<span class=\"ln\">93</span>        return None\n<span class=\"ln\">94</span>    return round(have / total, 2)</pre></details></details>\n<details class=\"step\"><summary><span class=\"num\">6-2</span>프롬프트 규칙(요약)</summary><div class=\"plain\"><ul><li>주어진 수치를 바꾸거나 새로 만들지 않기</li><li>의심 신호를 '낙상 확정'으로 바꾸지 않기</li><li>이벤트 0건을 '낙상 없음'의 증거로 쓰지 않기</li><li>논문의 낙상 확률(86.3% 등)을 환자 확률로 쓰지 않기</li><li>시뮬레이션이면 첫 문장에 명시</li><li>투약 조정은 '의사 판단' 문구와 함께 참고로만</li></ul></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> INTEGRATED_SYSTEM_PROMPT <span class=\"code-loc\">server/integrated_analysis.py:98–150</span></summary><pre><span class=\"ln\"> 98</span>INTEGRATED_SYSTEM_PROMPT = (\n<span class=\"ln\"> 99</span>    &quot;환자_EMR_검색_결과는 해당 환자 원문의 로컬 어휘 검색이며 입원_기록_원문과 중복될 수 있습니다. &quot;\n<span class=\"ln\">100</span>    &quot;검색 점수는 확률·위험도가 아닙니다. EMR 기록 ID를 논문 근거 ID로 인용하지 마세요. &quot;\n<span class=\"ln\">101</span>    &quot;검색 실패/부분 갱신은 자료 가용성으로 설명하고 없는 EMR 정보를 만들지 마세요. &quot;\n<span class=\"ln\">102</span>    &quot;당신은 치매환자 낙상예측시스템의 통합분석 리포트 작성자입니다. 아래 JSON에는 이미 계산이 끝난 &quot;\n<span class=\"ln\">103</span>    &quot;사실(환자 프로필·위험인자·투약, ToF/mmWave 현재 판정, 이미 계산된 위험점수, 직전 분석 기록, &quot;\n<span class=\"ln\">104</span>    &quot;검색된 논문 근거)만 들어있습니다. 절대 새로운 수치를 만들어내거나 주어진 수치를 바꾸지 마세요. &quot;\n<span class=\"ln\">105</span>    &quot;&#x27;입원_기록_원문&#x27;과 &#x27;간호_기록_원문&#x27;은 해당 환자의 저장된 기록이며 날짜·출처를 함께 참고하세요. &quot;\n<span class=\"ln\">106</span>    &quot;&#x27;데이터_출처&#x27;가 simulation이면 현재_상태 첫 문장에 &#x27;시뮬레이션 기반 리포트입니다.&#x27;라고 명시하고, &quot;\n<span class=\"ln\">107</span>    &quot;가상 센서 사건을 실제 환자에게 발생한 사건처럼 서술하지 마세요. &quot;\n<span class=\"ln\">108</span>    &quot;quality.walking=false 또는 보행속도 0은 현재 걷는 신호가 없다는 뜻입니다. &quot;\n<span class=\"ln\">109</span>    &quot;원문 기록의 명시적인 근거 없이 &#x27;보행 불가능&#x27;이나 &#x27;걸을 수 없음&#x27;으로 해석하지 마세요. &quot;\n<span class=\"ln\">110</span>    &quot;이벤트 0건은 해당 기간에 저장된 이벤트가 없다는 뜻이며, 낙상이 없었다는 증거가 아닙니다. &quot;\n<span class=\"ln\">111</span>    &quot;데이터_신뢰도_비율은 3개 판정 신호 중 확보된 신호의 비율입니다. AI 정확도나 의학적 신뢰도로 해석하지 마세요. &quot;\n<span class=\"ln\">112</span>    &quot;계산된 위험점수는 단계 대응값이지 낙상 발생 확률이 아닙니다. &quot;\n<span class=\"ln\">113</span>    &quot;&#x27;낙상_위험도_프로필&#x27;은 Morse 척도 기본 점수와 센서·간호 기록 변동 점수의 합이며 설계값입니다. 낙상 확률로 쓰지 마세요. &quot;\n<span class=\"ln\">114</span>    &quot;&#x27;보행_추세_예측&#x27;은 서버가 계산한 값입니다(하루 보행 대표값 → 칼만 필터 추세 → 7·14일 예측, 7일 누적 감소가 &quot;\n<span class=\"ln\">115</span>    &quot;Phillips 2017 기준(속도 2.54/5.1 cm/s, 보폭 2.54/7.6 cm)을 넘었을 확률). &#x27;향후_위험_가능성&#x27;은 이 수치와 범위를 그대로 인용해 쓰고, &quot;\n<span class=\"ln\">116</span>    &quot;숫자를 새로 만들거나 바꾸지 마세요. 논문의 3주 내 낙상 확률(86.3% 등)을 이 환자의 낙상 확률이라고 쓰지 마세요. &quot;\n<span class=\"ln\">117</span>    &quot;status가 insufficient면 &#x27;기록 일수가 부족해 예측하지 않음&#x27;이라고 쓰세요. &quot;\n<span class=\"ln\">118</span>    &quot;직전 리포트는 AI가 쓴 과거 해석이며 검증된 환자 사실이 아닙니다. 오류를 그대로 반복하지 마세요. &quot;\n<span class=\"ln\">119</span>    &quot;&#x27;최근_이벤트_상세&#x27;는 최근 24시간의 최대 20건입니다. 오래된 사건이나 리포트 생성 이력은 제외됩니다. &quot;\n<span class=\"ln\">120</span>    &quot;활동 요약과 개별 이벤트가 없으면 최근 변화는 판단할 수 없습니다. 현재 신호만으로 &#x27;변화 없음&#x27;이라고 쓰지 마세요. &quot;\n<span class=\"ln\">121</span>    &quot;67% 등의 신호 확보 비율을 mmWave 센서 자체의 신뢰도나 예측 정확도라고 쓰지 마세요. &quot;\n<span class=\"ln\">122</span>    &quot;현재 센서 상태가 낙상 의심이면 현재의 의심 신호라고 쓰세요. 의심을 실제 낙상 확정으로 바꾸지 마세요. &quot;\n<span class=\"ln\">123</span>    &quot;&#x27;최근_이벤트_상세&#x27;는 저장된 이벤트 로그입니다. 시뮬레이션의 이벤트는 가상 사건임을 표시하세요. &quot;\n<span class=\"ln\">124</span>    &quot;낙상(level=critical, event_type에 fall 포함) &quot;\n<span class=\"ln\">125</span>    &quot;이벤트가 있다면 &#x27;침상_관련_행동&#x27;과 &#x27;낙상_위험도_설명&#x27;에 그 발생 사실과 시각을 명시하고, 그 낙상 &quot;\n<span class=\"ln\">126</span>    &quot;이벤트보다 앞선 시각의 이벤트들(주의·경고 수준 상승 등) 중 전조로 볼 만한 것이 있다면 함께 짚어 &quot;\n<span class=\"ln\">127</span>    &quot;&#x27;최근_변화&#x27;에 서술하세요 — 이벤트 로그에 없는 전조는 지어내지 마세요. &quot;\n<span class=\"ln\">128</span>    &quot;논문 근거는 주어진 것 외에 새로 지어내지 마세요. 정보가 부족한 항목은 빈 문자열이나 &#x27;정보 부족&#x27;으로 &quot;\n<span class=\"ln\">129</span>    &quot;정직하게 표시하고 추측으로 채우지 마세요. &#x27;향후 위험 가능성&#x27;은 실제 예측 모델이 아니라 현재 판정과 &quot;\n<span class=\"ln\">130</span>    &quot;최근 변화 추세에 대한 신중한 설명이어야 하며, 확정적으로 단정하지 마세요. &quot;\n<span class=\"ln\">131</span>    &quot;&#x27;투약_조정_제안&#x27;에는 현재 투약과 관련해 담당 의료진이 확인할 사항만 적으세요. &quot;\n<span class=\"ln\">132</span>    &quot;센서 위험점수나 일반적인 낙상 논문만으로 특정 약의 감량·증량·중단·유지가 적절하다고 판단하지 마세요. &quot;\n<span class=\"ln\">133</span>    &quot;약물 분류·부작용을 주어진 근거에서 확인할 수 없으면 임의로 붙이지 마세요. &quot;\n<span class=\"ln\">134</span>    &quot;환자별 복용 목적, 실제 복용 여부, 증상·혈압 등 평가 자료가 부족하면 &#x27;정보 부족으로 조정 판단 불가&#x27;라고 적으세요. &quot;\n<span class=\"ln\">135</span>    &quot;절대 구체적인 용량·용법을 지시하지 마세요. 이 항목의 마지막 문장은 반드시 &#x27;이 제안은 참고용이며 최종 처방 변경은 담당 의사가 &quot;\n<span class=\"ln\">136</span>    &quot;판단해야 합니다.&#x27;로 끝내세요. &quot;\n<span class=\"ln\">137</span>    &quot;관련_연구_근거에는 실제 제공된 문단의 내용과 한계를 적고 문헌 ID를 [근거: ID] 형식으로 붙이세요. &quot;\n<span class=\"ln\">138</span>    &quot;제목·저자만 있는 identity 구간은 연구 결과의 근거가 아닙니다. 연관성을 인과관계나 개인 예측으로 확대하지 마세요. &quot;\n<span class=\"ln\">139</span>    &quot;&#x27;보행_기대범위_문헌기반&#x27;은 입원 기록과 문헌으로 만든 참고 범위일 뿐 낙상 확률이 아니며, 개인 보행 기록이 &quot;\n<span class=\"ln\">140</span>    &quot;쌓이면 개인 기준이 우선합니다. &#x27;센서_예측범위_밖_위험&#x27;에 요인이 있으면 &#x27;주요_위험_요인&#x27;에서 센서가 미리 &quot;\n<span class=\"ln\">141</span>    &quot;알기 어려운 유형(걸려 넘어짐·갑자기 힘이 빠지는 주저앉음 등)으로 구분해 적고, 이런 낙상을 센서가 예측한다고 쓰지 마세요. &quot;\n<span class=\"ln\">142</span>    &quot;반드시 아래 JSON 스키마로만, 모든 키를 한국어 문자열 값으로 채워 답하세요: &quot;\n<span class=\"ln\">143</span>    &#x27;{&quot;현재_상태&quot;: &quot;&quot;, &quot;최근_변화&quot;: &quot;&quot;, &quot;ToF_변화&quot;: &quot;&quot;, &quot;mmWave_변화&quot;: &quot;&quot;, &quot;보행_변화&quot;: &quot;&quot;, &#x27;\n<span class=\"ln\">144</span>    &#x27;&quot;활동_변화&quot;: &quot;&quot;, &quot;침상_관련_행동&quot;: &quot;&quot;, &quot;낙상_위험도_설명&quot;: &quot;&quot;, &quot;주요_위험_요인&quot;: &quot;&quot;, &#x27;\n<span class=\"ln\">145</span>    &#x27;&quot;과거_데이터와의_비교&quot;: &quot;&quot;, &quot;향후_위험_가능성&quot;: &quot;&quot;, &quot;관련_연구_근거&quot;: &quot;&quot;, &#x27;\n<span class=\"ln\">146</span>    &#x27;&quot;투약_조정_제안&quot;: &quot;&quot;, &quot;데이터_신뢰도_설명&quot;: &quot;&quot;, &quot;추가_관찰이_필요한_항목&quot;: &quot;&quot;}&#x27;\n<span class=\"ln\">147</span>)\n<span class=\"ln\">148</span>\n<span class=\"ln\">149</span>\n<span class=\"ln\">150</span>def _build_payload(bed_id: str, investigation: dict, risk: dict, confidence: float | None,</pre></details></details>\n<details class=\"step\"><summary><span class=\"num\">6-3</span>작성·검증·저장</summary><div class=\"plain\"><p>LLM 응답(JSON)의 15개 항목을 검사한다. 목록·객체는 글로 풀고, 빠진 항목이 3개 이하면 '정보 부족'으로 채우며, 그보다 많거나 숫자만 온 응답은 저장하지 않는다(2026-10-13). 저장 전 report_charts가 계산한 그래프 숫자(24시간 사건 원그래프·7일 보행 속도·위험도 변동)를 붙인다.</p></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> generate_integrated_report() <span class=\"code-loc\">server/integrated_analysis.py:187–279</span></summary><pre><span class=\"ln\">187</span>@report_trace.traced_run(&#x27;report&#x27;)\n<span class=\"ln\">188</span>def generate_integrated_report(bed_id: str, max_rounds: int = 2, top_k: int = 5,\n<span class=\"ln\">189</span>                                persist: bool = True, override_created_at: str | None = None) -&gt; dict:\n<span class=\"ln\">190</span>    &quot;&quot;&quot;전체 STEP 21-23 파이프라인. 반환: {&quot;success&quot;:bool, &quot;analysis_id&quot;, &quot;risk&quot;, &quot;report&quot;, ...}\n<span class=\"ln\">191</span>    또는 실패 시 ai_agent/ai_report와 동일한 정직한 실패 shape을 그대로 전파한다.&quot;&quot;&quot;\n<span class=\"ln\">192</span>    investigation = ai_agent.investigate(bed_id, max_rounds=max_rounds, top_k=top_k)\n<span class=\"ln\">193</span>    if not investigation[&quot;success&quot;]:\n<span class=\"ln\">194</span>        return {**investigation, &quot;stage&quot;: investigation.get(&quot;stage&quot;, &quot;investigate&quot;)}\n<span class=\"ln\">195</span>\n<span class=\"ln\">196</span>    risk = compute_risk_score(investigation[&quot;patient_state&quot;])\n<span class=\"ln\">197</span>    confidence = compute_data_confidence(investigation[&quot;patient_state&quot;], risk)\n<span class=\"ln\">198</span>    report_trace.emit(&#x27;risk_fusion&#x27;, &#x27;completed&#x27;, &#x27;두 센서의 기존 위험 단계 결합&#x27;, {&#x27;risk&#x27;: risk, &#x27;confidence&#x27;: confidence, &#x27;formula&#x27;: &#x27;max(기존 위험 단계 대응 점수)&#x27;, &#x27;note&#x27;: &#x27;낙상 확률이 아닙니다. 잠정 보행 판정은 제외합니다.&#x27;})\n<span class=\"ln\">199</span>    prev_analysis = db.get_latest_ai_analysis(bed_id, analysis_type=&quot;integrated_status&quot;)\n<span class=\"ln\">200</span>\n<span class=\"ln\">201</span>    payload = _build_payload(bed_id, investigation, risk, confidence, prev_analysis)\n<span class=\"ln\">202</span>    user_content = (\n<span class=\"ln\">203</span>        &quot;다음은 한 환자의 통합분석에 필요한 사실입니다. 이 사실만 근거로 15개 항목 리포트를 &quot;\n<span class=\"ln\">204</span>        &quot;작성하세요.\\n\\n&quot; + json.dumps(payload, ensure_ascii=False, indent=2, default=str)\n<span class=\"ln\">205</span>    )\n<span class=\"ln\">206</span>    report_trace.emit(&#x27;report_generation&#x27;, &#x27;running&#x27;, &#x27;실제 근거와 환자 기록으로 15개 항목 작성 요청&#x27;, {&#x27;prompt_version&#x27;: PROMPT_VERSION, &#x27;fields&#x27;: REPORT_FIELDS, &#x27;evidence_ids&#x27;: [r[&#x27;chunk_id&#x27;] for r in investigation.get(&#x27;final_results&#x27;, [])], &#x27;previous_analysis_id&#x27;: (prev_analysis or {}).get(&#x27;id&#x27;), &#x27;data_source&#x27;: investigation[&#x27;patient_state&#x27;].get(&#x27;data_source&#x27;)})\n<span class=\"ln\">207</span>    result = ai_report.call_openai(system_prompt=INTEGRATED_SYSTEM_PROMPT,\n<span class=\"ln\">208</span>                                    user_content=user_content, json_mode=True)\n<span class=\"ln\">209</span>    if not result[&quot;success&quot;]:\n<span class=\"ln\">210</span>        return {**result, &quot;stage&quot;: &quot;generate_report&quot;, &quot;risk&quot;: risk, &quot;patient_state&quot;: investigation[&quot;patient_state&quot;]}\n<span class=\"ln\">211</span>\n<span class=\"ln\">212</span>    try:\n<span class=\"ln\">213</span>        report = json.loads(result[&quot;text&quot;])\n<span class=\"ln\">214</span>    except json.JSONDecodeError as e:\n<span class=\"ln\">215</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;parse_error&quot;,\n<span class=\"ln\">216</span>                &quot;message&quot;: f&quot;LLM 응답이 JSON 스키마를 따르지 않음: {type(e).__name__}&quot;,\n<span class=\"ln\">217</span>                &quot;stage&quot;: &quot;parse_report&quot;, &quot;risk&quot;: risk}\n<span class=\"ln\">218</span>\n<span class=\"ln\">219</span>    if isinstance(report, dict):\n<span class=\"ln\">220</span>        # 10-13 실측: 모델이 일부 항목을 목록·객체로 주거나 한두 개 빠뜨려 리포트 전체가 버려졌다 → 목록·객체는 글로 풀고,\n<span class=\"ln\">221</span>        # 빠진 항목이 3개 이하면 &#x27;정보 부족&#x27;으로 채운다. 숫자만 온 항목·대부분 빠진 응답은 그대로 거절한다.\n<span class=\"ln\">222</span>        for key in REPORT_FIELDS:\n<span class=\"ln\">223</span>            val = report.get(key)\n<span class=\"ln\">224</span>            if isinstance(val, list):\n<span class=\"ln\">225</span>                report[key] = &quot;\\n&quot;.join(v if isinstance(v, str) else json.dumps(v, ensure_ascii=False) for v in val)\n<span class=\"ln\">226</span>            elif isinstance(val, dict):\n<span class=\"ln\">227</span>                report[key] = &quot;\\n&quot;.join(f&quot;{k}: {v if isinstance(v, str) else json.dumps(v, ensure_ascii=False)}&quot; for k, v in val.items())\n<span class=\"ln\">228</span>        missing = [key for key in REPORT_FIELDS if report.get(key) is None]\n<span class=\"ln\">229</span>        if len(missing) &lt;= 3:\n<span class=\"ln\">230</span>            for key in missing:\n<span class=\"ln\">231</span>                report[key] = &quot;정보 부족&quot;\n<span class=\"ln\">232</span>    if not isinstance(report, dict) or any(not isinstance(report.get(key), str) for key in REPORT_FIELDS):\n<span class=\"ln\">233</span>        invalid = [key for key in REPORT_FIELDS if not isinstance(report, dict) or not isinstance(report.get(key), str)]\n<span class=\"ln\">234</span>        return {&quot;success&quot;: False, &quot;error_type&quot;: &quot;invalid_report_schema&quot;,\n<span class=\"ln\">235</span>                &quot;message&quot;: &quot;리포트는 15개 필수 항목을 문자열로 포함해야 합니다.&quot;,\n<span class=\"ln\">236</span>                &quot;invalid_fields&quot;: invalid,\n<span class=\"ln\">237</span>                &quot;stage&quot;: &quot;parse_report&quot;, &quot;risk&quot;: risk}\n<span class=\"ln\">238</span>\n<span class=\"ln\">239</span>    report_trace.emit(&#x27;report_validation&#x27;, &#x27;completed&#x27;, &#x27;필수 15개 필드 검증 완료&#x27;, {&#x27;fields&#x27;: list(report), &#x27;report&#x27;: report})\n<span class=\"ln\">240</span>    evidence_ids = [r[&quot;chunk_id&quot;] for r in investigation.get(&quot;final_results&quot;, [])]\n<span class=\"ln\">241</span>    analysis_id = None\n<span class=\"ln\">242</span>    review = None\n<span class=\"ln\">243</span>    try:   # 10-13: 리포트 화면의 원그래프·선그래프용 숫자(report_charts — 계산값만, LLM이 만들지 않음)\n<span class=\"ln\">244</span>        import report_charts\n<span class=\"ln\">245</span>        report[&quot;charts&quot;] = report_charts.build(bed_id)\n<span class=\"ln\">246</span>    except Exception as e:\n<span class=\"ln\">247</span>        print(f&quot;[integrated] 그래프 데이터 실패: {type(e).__name__}&quot;)\n<span class=\"ln\">248</span>    if persist:\n<span class=\"ln\">249</span>        analysis_id = db.insert_ai_analysis(\n<span class=\"ln\">250</span>            patient_id=bed_id, analysis_type=&quot;integrated_status&quot;,\n<span class=\"ln\">251</span>            risk_score=risk[&quot;combined_risk_score&quot;], summary=report.get(&quot;현재_상태&quot;, &quot;&quot;),\n<span class=\"ln\">252</span>            detected_patterns=[report.get(&quot;주요_위험_요인&quot;, &quot;&quot;)],\n<span class=\"ln\">253</span>            predicted_risks=[report.get(&quot;향후_위험_가능성&quot;, &quot;&quot;)],\n<span class=\"ln\">254</span>            evidence_ids=evidence_ids, model_version=result.get(&quot;model&quot;, DEFAULT_MODEL),\n<span class=\"ln\">255</span>            prompt_version=PROMPT_VERSION, confidence=confidence, report=report, risk=risk,\n<span class=\"ln\">256</span>            created_at=override_created_at,\n<span class=\"ln\">257</span>            input_snapshot=payload,\n<span class=\"ln\">258</span>        )\n<span class=\"ln\">259</span>        report_trace.emit(&#x27;report_storage&#x27;, &#x27;completed&#x27;, &#x27;운영 DB에 리포트 저장 완료&#x27;, {&#x27;database&#x27;: db.DB_PATH, &#x27;table&#x27;: &#x27;ai_analysis&#x27;, &#x27;row_id&#x27;: analysis_id, &#x27;analysis_type&#x27;: &#x27;integrated_status&#x27;, &#x27;evidence_ids&#x27;: evidence_ids, &#x27;model&#x27;: result.get(&#x27;model&#x27;, DEFAULT_MODEL), &#x27;prompt_version&#x27;: PROMPT_VERSION, &#x27;risk&#x27;: risk, &#x27;confidence&#x27;: confidence})\n<span class=\"ln\">260</span>        import report_review\n<span class=\"ln\">261</span>        review = report_review.review_and_save(db.get_analysis_by_id(analysis_id), {\n<span class=\"ln\">262</span>            &quot;success&quot;: True, &quot;found&quot;: investigation.get(&quot;final_results&quot;, []), &quot;missing_chunk_ids&quot;: [],\n<span class=\"ln\">263</span>        })\n<span class=\"ln\">264</span>        report_trace.emit(&#x27;report_review&#x27;, &#x27;completed&#x27;, &#x27;생성 리포트 근거 검토 완료&#x27;, {&#x27;review&#x27;: review})\n<span class=\"ln\">265</span>        db.insert_sensor_event(\n<span class=\"ln\">266</span>            bed_id, &quot;ai_analysis_completed&quot;, ts=override_created_at, level=(\n<span class=\"ln\">267</span>                risk[&quot;component_levels&quot;].get(risk[&quot;dominant_signal&quot;]) if risk[&quot;dominant_signal&quot;] else None),\n<span class=\"ln\">268</span>            title=&quot;AI 통합분석 완료&quot;, note=report.get(&quot;현재_상태&quot;, &quot;&quot;)[:200],\n<span class=\"ln\">269</span>        )\n<span class=\"ln\">270</span>\n<span class=\"ln\">271</span>    if not persist:\n<span class=\"ln\">272</span>        report_trace.emit(&#x27;report_storage&#x27;, &#x27;skipped&#x27;, &#x27;리포트 저장 생략&#x27;, {&#x27;reason&#x27;: &#x27;persist=False&#x27;})\n<span class=\"ln\">273</span>    return {\n<span class=\"ln\">274</span>        &quot;success&quot;: True, &quot;bed_id&quot;: bed_id, &quot;analysis_id&quot;: analysis_id,\n<span class=\"ln\">275</span>        &quot;risk&quot;: risk, &quot;data_confidence&quot;: confidence, &quot;report&quot;: report,\n<span class=\"ln\">276</span>        &quot;evidence&quot;: investigation.get(&quot;final_results&quot;, []),\n<span class=\"ln\">277</span>        &quot;prev_analysis_compared&quot;: prev_analysis is not None,\n<span class=\"ln\">278</span>        &quot;review&quot;: review,\n<span class=\"ln\">279</span>    }</pre></details><details class=\"code\"><summary><span class=\"code-tag\">코드</span> build() <span class=\"code-loc\">server/report_charts.py:74–75</span></summary><pre><span class=\"ln\">74</span>def build(bed_id: str) -&gt; dict:\n<span class=\"ln\">75</span>    return {&quot;activity_pie&quot;: activity_pie(bed_id), &quot;gait_line&quot;: gait_line(bed_id), &quot;risk_line&quot;: risk_line(bed_id)}</pre></details></details>\n<details class=\"step\"><summary><span class=\"num\">6-4</span>언제 만들어지나</summary><div class=\"plain\"><p>① 매주 자동(스케줄러가 마지막 리포트 7일 뒤) ② 리포트 탭 '지금 리포트 만들기' ③ 예전에는 낙상 때도 이걸 썼지만, 지금은 7장의 낙상 사건 리포트가 따로 만든다. 진행 단계는 report_trace가 메모리에만 기록해 개발 화면에서 볼 수 있다(키·비밀번호는 지움).</p></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> _run_due_weekly_reports() <span class=\"code-loc\">server/dashboard_api.py:764–771</span></summary><pre><span class=\"ln\">764</span>def _run_due_weekly_reports():\n<span class=\"ln\">765</span>    import integrated_analysis\n<span class=\"ln\">766</span>    for bed_id in _weekly_reports_due():\n<span class=\"ln\">767</span>        try:\n<span class=\"ln\">768</span>            result = integrated_analysis.generate_integrated_report(bed_id, max_rounds=1, top_k=3)\n<span class=\"ln\">769</span>            print(f&quot;[scheduler] 주간 리포트 {&#x27;완료&#x27; if result.get(&#x27;success&#x27;) else &#x27;실패&#x27;}: {bed_id}&quot;)\n<span class=\"ln\">770</span>        except Exception as e:\n<span class=\"ln\">771</span>            print(f&quot;[scheduler] 주간 리포트 생성 중 오류({bed_id}): {type(e).__name__}: {e}&quot;)</pre></details><details class=\"code\"><summary><span class=\"code-tag\">코드</span> emit() <span class=\"code-loc\">server/report_trace.py:53–70</span></summary><pre><span class=\"ln\">53</span>def emit(stage, status, title, details=None):\n<span class=\"ln\">54</span>    &quot;&quot;&quot;Observability must never change the clinical/report execution result.&quot;&quot;&quot;\n<span class=\"ln\">55</span>    try:\n<span class=\"ln\">56</span>        run_id = _ACTIVE.get()\n<span class=\"ln\">57</span>        if not run_id:\n<span class=\"ln\">58</span>            return\n<span class=\"ln\">59</span>        event = {&#x27;at&#x27;: _now(), &#x27;stage&#x27;: stage, &#x27;status&#x27;: status, &#x27;title&#x27;: title,\n<span class=\"ln\">60</span>                 &#x27;details&#x27;: _clean(details or {})}\n<span class=\"ln\">61</span>        with _LOCK:\n<span class=\"ln\">62</span>            run = _RUNS.get(run_id)\n<span class=\"ln\">63</span>            if run is None:\n<span class=\"ln\">64</span>                return\n<span class=\"ln\">65</span>            run[&#x27;event_count&#x27;] += 1\n<span class=\"ln\">66</span>            event[&#x27;seq&#x27;] = run[&#x27;event_count&#x27;]\n<span class=\"ln\">67</span>            run[&#x27;events&#x27;].append(event)\n<span class=\"ln\">68</span>            del run[&#x27;events&#x27;][:-MAX_EVENTS]\n<span class=\"ln\">69</span>    except Exception:\n<span class=\"ln\">70</span>        pass</pre></details></details>\n<div class=\"warn\"><b>한계·주의</b> gpt-4o-mini는 지시를 어기고 두루뭉술하게 쓰거나 항목을 빠뜨릴 때가 있다(10-13 첫 실행 실패). 그래서 형식 검사와 규칙 검토가 있고, 리포트는 간호사의 판단을 돕는 참고 자료로만 쓴다.</div>\n</section><section class=\"part\" id=\"fall\" hidden><div class=\"part-head\"><a href=\"#home\" class=\"back\">← 전체 지도</a><h2>7. 낙상 사건 리포트·자동 검토</h2><p class=\"sub\">넘어진 순간 '왜?'를 정리하고, 리포트를 규칙으로 다시 점검</p></div>\n<div class=\"easy\"><b>쉽게 말하면</b> 낙상이 감지되면 4초 뒤 서버가 그 순간의 사실(내려간 속도·바닥에 머문 시간·직전 30분 사건·밤인지·약·위험 요인)을 모은다. 규칙으로 '가능성 있는 원인'을 근거와 함께 뽑고, LLM은 그 후보로만 간호사용 문장을 쓴다. LLM이 실패해도 규칙 요약이 저장된다.</div>\n<details class=\"step\"><summary><span class=\"num\">7-1</span>원인 후보는 규칙으로</summary><div class=\"plain\"><table><thead><tr><th>사실</th><th>원인 후보</th></tr></thead><tbody><tr><td>1초 이내 하강·세로 속도 빠름</td><td>미끄러짐·걸림 또는 갑작스러운 힘 빠짐(실신 감별)</td></tr><tr><td>천천히 내려가 바닥에 머묾</td><td>다리 힘 빠짐·어지럼</td></tr><tr><td>낙상 5분 안 침상 이탈</td><td>기립 직후 균형 상실</td></tr><tr><td>21~06시</td><td>야간(어두움·졸림·야간뇨)</td></tr><tr><td>진정·마약성·혈압·어지럼 약</td><td>약물 영향 가능</td></tr><tr><td>Morse 보행 약화·자기 한계 잊음</td><td>평소 보행 약화·인지 저하</td></tr><tr><td>최근 보행 속도 15% 이상 감소</td><td>보행 저하</td></tr></tbody></table></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> candidate_causes() <span class=\"code-loc\">server/fall_report.py:103–146</span></summary><pre><span class=\"ln\">103</span>def candidate_causes(facts: dict) -&gt; list[dict]:\n<span class=\"ln\">104</span>    &quot;&quot;&quot;사실에서 바로 나오는 원인 후보와 근거. 근거 없는 후보는 만들지 않는다.&quot;&quot;&quot;\n<span class=\"ln\">105</span>    out = []\n<span class=\"ln\">106</span>    ev = facts[&quot;사건&quot;]\n<span class=\"ln\">107</span>    if ev.get(&quot;양상&quot;) == &quot;급격한 하강&quot;:\n<span class=\"ln\">108</span>        out.append({&quot;원인&quot;: &quot;미끄러짐·발 걸림 또는 갑작스러운 힘 빠짐(실신·기립성 저혈압 감별 필요)&quot;,\n<span class=\"ln\">109</span>                    &quot;근거&quot;: f&quot;1초 이내 하강, 세로 속도 {ev.get(&#x27;세로_속도_최저_m_s&#x27;)} m/s&quot;})\n<span class=\"ln\">110</span>    elif ev.get(&quot;양상&quot;) == &quot;천천히 주저앉음&quot;:\n<span class=\"ln\">111</span>        out.append({&quot;원인&quot;: &quot;다리 힘 빠짐·어지럼으로 서서히 주저앉음&quot;,\n<span class=\"ln\">112</span>                    &quot;근거&quot;: f&quot;서 있음→바닥까지 천천히 내려감, 바닥에 {ev.get(&#x27;바닥에_머문_초&#x27;)}초&quot;})\n<span class=\"ln\">113</span>    when = datetime.fromisoformat(facts[&quot;발생_시각&quot;])\n<span class=\"ln\">114</span>    exits = []\n<span class=\"ln\">115</span>    for e in facts[&quot;직전_30분_사건&quot;]:\n<span class=\"ln\">116</span>        if e[&quot;종류&quot;] in (&quot;bed_alert&quot;, &quot;bed_exit&quot;, &quot;sim_exit&quot;) or &quot;이탈&quot; in (e[&quot;제목&quot;] or &quot;&quot;):\n<span class=\"ln\">117</span>            try:\n<span class=\"ln\">118</span>                mins = (when - datetime.fromisoformat(e[&quot;ts&quot;])).total_seconds() / 60\n<span class=\"ln\">119</span>            except ValueError:\n<span class=\"ln\">120</span>                continue\n<span class=\"ln\">121</span>            if 0 &lt;= mins &lt;= BED_EXIT_WINDOW_MIN:\n<span class=\"ln\">122</span>                exits.append((mins, e))\n<span class=\"ln\">123</span>    if exits:\n<span class=\"ln\">124</span>        mins, e = exits[-1]\n<span class=\"ln\">125</span>        out.append({&quot;원인&quot;: &quot;침상 이탈·기립 직후 균형 상실&quot;,\n<span class=\"ln\">126</span>                    &quot;근거&quot;: f&quot;낙상 {mins:.1f}분 전 &#x27;{e[&#x27;제목&#x27;]}&#x27;({e[&#x27;시각&#x27;]})&quot;})\n<span class=\"ln\">127</span>    if facts[&quot;야간&quot;]:\n<span class=\"ln\">128</span>        out.append({&quot;원인&quot;: &quot;야간(어두움·졸림·야간뇨로 서두름)&quot;, &quot;근거&quot;: f&quot;발생 시각 {facts[&#x27;발생_시각&#x27;][11:16]}&quot;})\n<span class=\"ln\">129</span>    for f in facts[&quot;투약_주의&quot;]:\n<span class=\"ln\">130</span>        out.append({&quot;원인&quot;: f&quot;약물 영향 가능({f.split(&#x27;:&#x27;)[0]})&quot;, &quot;근거&quot;: f})\n<span class=\"ln\">131</span>    morse = facts.get(&quot;Morse_항목&quot;) or {}\n<span class=\"ln\">132</span>    if morse.get(&quot;gait&quot;) in (&quot;weak&quot;, &quot;impaired&quot;):\n<span class=\"ln\">133</span>        out.append({&quot;원인&quot;: &quot;평소 보행 약화&quot;, &quot;근거&quot;: f&quot;Morse 보행 항목 &#x27;{morse.get(&#x27;gait&#x27;)}&#x27;&quot;})\n<span class=\"ln\">134</span>    if morse.get(&quot;mental&quot;) == &quot;forgets_limitations&quot;:\n<span class=\"ln\">135</span>        out.append({&quot;원인&quot;: &quot;인지 저하로 자기 한계를 잊고 혼자 이동&quot;, &quot;근거&quot;: &quot;Morse 정신 상태 &#x27;자기 한계를 잊음&#x27;&quot;})\n<span class=\"ln\">136</span>    g = facts.get(&quot;최근_보행_속도&quot;) or []\n<span class=\"ln\">137</span>    if len(g) &gt;= 3 and g[-1][&quot;y&quot;] &lt; 0.85 * g[0][&quot;y&quot;]:\n<span class=\"ln\">138</span>        out.append({&quot;원인&quot;: &quot;최근 보행 속도 감소&quot;, &quot;근거&quot;: f&quot;{g[0][&#x27;x&#x27;]} {g[0][&#x27;y&#x27;]} m/s → {g[-1][&#x27;x&#x27;]} {g[-1][&#x27;y&#x27;]} m/s&quot;})\n<span class=\"ln\">139</span>    seen = &quot; &quot;.join(c[&quot;근거&quot;] for c in out)\n<span class=\"ln\">140</span>    for rf in facts[&quot;위험_요인&quot;]:\n<span class=\"ln\">141</span>        if len(out) &gt;= 7:\n<span class=\"ln\">142</span>            break\n<span class=\"ln\">143</span>        if any(w and w in seen for w in rf.split()[:1]):   # 이미 투약 등으로 나온 요인은 다시 쓰지 않는다\n<span class=\"ln\">144</span>            continue\n<span class=\"ln\">145</span>        out.append({&quot;원인&quot;: f&quot;기존 위험 요인: {rf}&quot;, &quot;근거&quot;: &quot;환자 위험 요인 기록&quot;})\n<span class=\"ln\">146</span>    return out</pre></details></details>\n<details class=\"step\"><summary><span class=\"num\">7-2</span>작성과 저장</summary><div class=\"plain\"><p>LLM 출력 7항목(요약·양상·추정 원인·직전 상황·지금 확인할 것·재발 방지·데이터 한계)을 저장하고, 낙상 전후 9초 몸 높이 그래프(mmWave/fall_traces)를 붙인다. analysis_type='fall_incident'.</p></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> collect_facts() <span class=\"code-loc\">server/fall_report.py:149–180</span></summary><pre><span class=\"ln\">149</span>def collect_facts(bed_id: str, event: dict, source: str = &quot;live&quot;) -&gt; dict:\n<span class=\"ln\">150</span>    when = datetime.fromtimestamp(event[&quot;at&quot;]) if isinstance(event.get(&quot;at&quot;), (int, float)) else datetime.now()\n<span class=\"ln\">151</span>    patient = db.get_patient(bed_id) or {}\n<span class=\"ln\">152</span>    meds = db.list_medications(bed_id)\n<span class=\"ln\">153</span>    rfs = [r.get(&quot;label&quot;) or r.get(&quot;factor&quot;) for r in db.list_risk_factors(bed_id)]\n<span class=\"ln\">154</span>    try:\n<span class=\"ln\">155</span>        import fall_risk\n<span class=\"ln\">156</span>        with db.get_conn() as conn:\n<span class=\"ln\">157</span>            prof = fall_risk.get_profile(conn, bed_id) or {}\n<span class=\"ln\">158</span>        morse = {k: v.get(&quot;value&quot;) for k, v in (prof.get(&quot;morse&quot;) or {}).items()}\n<span class=\"ln\">159</span>        mobility = prof.get(&quot;mobility_ko&quot;)\n<span class=\"ln\">160</span>    except Exception:\n<span class=\"ln\">161</span>        morse, mobility = {}, None\n<span class=\"ln\">162</span>    kind = event.get(&quot;kind&quot;)\n<span class=\"ln\">163</span>    gait = report_charts.gait_line(bed_id)[&quot;points&quot;]\n<span class=\"ln\">164</span>    return {\n<span class=\"ln\">165</span>        &quot;데이터_출처&quot;: &quot;simulation&quot; if source == &quot;sim&quot; else &quot;live&quot;,\n<span class=\"ln\">166</span>        &quot;환자&quot;: {&quot;이름&quot;: patient.get(&quot;name&quot;), &quot;나이&quot;: patient.get(&quot;age&quot;), &quot;진단&quot;: patient.get(&quot;diagnosis&quot;), &quot;병실&quot;: patient.get(&quot;room&quot;)},\n<span class=\"ln\">167</span>        &quot;발생_시각&quot;: when.isoformat(timespec=&quot;seconds&quot;),\n<span class=\"ln\">168</span>        &quot;야간&quot;: when.hour &gt;= NIGHT_HOURS[0] or when.hour &lt; NIGHT_HOURS[1],\n<span class=\"ln\">169</span>        &quot;사건&quot;: {&quot;양상&quot;: &quot;급격한 하강&quot; if kind == &quot;fast&quot; else &quot;천천히 주저앉음&quot; if kind == &quot;slow&quot; else (event.get(&quot;label&quot;) or &quot;낙상 감지&quot;),\n<span class=\"ln\">170</span>               &quot;하강_시간_초&quot;: event.get(&quot;drop_sec&quot;), &quot;세로_속도_최저_m_s&quot;: event.get(&quot;vz_min&quot;),\n<span class=\"ln\">171</span>               &quot;바닥에_머문_초&quot;: event.get(&quot;low_sec&quot;), &quot;몸_중심_높이_m&quot;: event.get(&quot;z&quot;), &quot;평소_높이_m&quot;: event.get(&quot;ref&quot;),\n<span class=\"ln\">172</span>               &quot;위치_m&quot;: [round(event[&quot;x&quot;], 2), round(event[&quot;y&quot;], 2)] if isinstance(event.get(&quot;x&quot;), (int, float)) else None,\n<span class=\"ln\">173</span>               &quot;설명&quot;: event.get(&quot;note&quot;)},\n<span class=\"ln\">174</span>        &quot;직전_30분_사건&quot;: _recent_events(bed_id, when),\n<span class=\"ln\">175</span>        &quot;Morse_항목&quot;: morse, &quot;거동_범위&quot;: mobility,\n<span class=\"ln\">176</span>        &quot;투약&quot;: [f&quot;{m.get(&#x27;name&#x27;)} ({m.get(&#x27;frequency&#x27;) or &#x27;&#x27;}) {m.get(&#x27;notes&#x27;) or &#x27;&#x27;}&quot;.strip() for m in meds],\n<span class=\"ln\">177</span>        &quot;투약_주의&quot;: _med_flags(meds),\n<span class=\"ln\">178</span>        &quot;위험_요인&quot;: [r for r in rfs if r],\n<span class=\"ln\">179</span>        &quot;최근_보행_속도&quot;: gait,\n<span class=\"ln\">180</span>    }</pre></details><details class=\"code\"><summary><span class=\"code-tag\">코드</span> generate() <span class=\"code-loc\">server/fall_report.py:198–232</span></summary><pre><span class=\"ln\">198</span>def generate(bed_id: str, event: dict, source: str = &quot;live&quot;) -&gt; dict:\n<span class=\"ln\">199</span>    facts = collect_facts(bed_id, event, source)\n<span class=\"ln\">200</span>    facts[&quot;사건&quot;] = {k: v for k, v in facts[&quot;사건&quot;].items() if v not in (None, &quot;&quot;)}   # null 수치는 LLM에 주지 않는다\n<span class=\"ln\">201</span>    causes = candidate_causes(facts)\n<span class=\"ln\">202</span>    payload = {**facts, &quot;원인_후보&quot;: causes}\n<span class=\"ln\">203</span>    report, model = None, &quot;rule-fallback&quot;\n<span class=\"ln\">204</span>    try:\n<span class=\"ln\">205</span>        import ai_report\n<span class=\"ln\">206</span>        res = ai_report.call_openai(system_prompt=SYSTEM_PROMPT, json_mode=True,\n<span class=\"ln\">207</span>                                    user_content=&quot;낙상 사건 사실:\\n&quot; + json.dumps(payload, ensure_ascii=False, indent=1, default=str))\n<span class=\"ln\">208</span>        if res.get(&quot;success&quot;):\n<span class=\"ln\">209</span>            out = json.loads(res[&quot;text&quot;])\n<span class=\"ln\">210</span>            if isinstance(out, dict):\n<span class=\"ln\">211</span>                report = {k: (v if isinstance(v, str) else &quot;\\n&quot;.join(map(str, v)) if isinstance(v, list) else json.dumps(v, ensure_ascii=False))\n<span class=\"ln\">212</span>                          for k, v in out.items() if k in FIELDS}\n<span class=\"ln\">213</span>                for k in FIELDS:\n<span class=\"ln\">214</span>                    report.setdefault(k, &quot;정보 부족&quot;)\n<span class=\"ln\">215</span>                model = res.get(&quot;model&quot;) or &quot;llm&quot;\n<span class=\"ln\">216</span>    except Exception as e:  # LLM 실패해도 사건 리포트는 남긴다\n<span class=\"ln\">217</span>        print(f&quot;[fall_report] LLM 실패: {type(e).__name__}&quot;)\n<span class=\"ln\">218</span>    if report is None:\n<span class=\"ln\">219</span>        report = _fallback_report(facts, causes)\n<span class=\"ln\">220</span>    charts = report_charts.build(bed_id)\n<span class=\"ln\">221</span>    trace = _trace_for(event) if source == &quot;live&quot; else None\n<span class=\"ln\">222</span>    if trace and trace[&quot;points&quot;]:\n<span class=\"ln\">223</span>        charts[&quot;fall_trace&quot;] = trace\n<span class=\"ln\">224</span>    report.update({&quot;리포트_종류&quot;: &quot;낙상 사건&quot;, &quot;원인_후보&quot;: causes, &quot;charts&quot;: charts,\n<span class=\"ln\">225</span>                   &quot;사건_수치&quot;: facts[&quot;사건&quot;], &quot;발생_시각&quot;: facts[&quot;발생_시각&quot;]})\n<span class=\"ln\">226</span>    aid = db.insert_ai_analysis(bed_id, &quot;fall_incident&quot;, None, report[&quot;요약&quot;][:300], None,\n<span class=\"ln\">227</span>                                [c[&quot;원인&quot;] for c in causes], None, model, PROMPT_VERSION, None, report,\n<span class=\"ln\">228</span>                                input_snapshot=payload)\n<span class=\"ln\">229</span>    db.insert_sensor_event(bed_id, &quot;ai_analysis_completed&quot;, ts=datetime.now().isoformat(timespec=&quot;milliseconds&quot;),\n<span class=\"ln\">230</span>                           level=&quot;normal&quot;, title=&quot;낙상 사건 리포트 작성&quot;,\n<span class=\"ln\">231</span>                           note=report[&quot;요약&quot;][:200])\n<span class=\"ln\">232</span>    return {&quot;success&quot;: True, &quot;analysis_id&quot;: aid, &quot;model&quot;: model}</pre></details></details>\n<details class=\"step\"><summary><span class=\"num\">7-3</span>리포트 자동 검토(LLM 없음)</summary><div class=\"plain\"><p>종합 리포트마다 규칙으로 점검한다: 15개 항목 존재, 작성 당시 입력 보존, 환자 ID 일치, 위험 점수 재계산 일치, 인용 논문 실재, 그리고 과잉 해석 문장(예: '보행 불가능', '낙상이 없었다', 신호 확보 비율을 정확도로 씀, 약 감량·중단 단정)을 찾아 수정 문구를 제안한다. 통과해도 의학적 승인은 아니다.</p></div><details class=\"code\"><summary><span class=\"code-tag\">코드</span> build_review() <span class=\"code-loc\">server/report_review.py:96–233</span></summary><pre><span class=\"ln\"> 96</span>def build_review(row, resolved=None):\n<span class=\"ln\"> 97</span>    report = decode(row.get(&quot;report_json&quot;), {})\n<span class=\"ln\"> 98</span>    payload = decode(row.get(&quot;input_snapshot_json&quot;))\n<span class=\"ln\"> 99</span>    payload = payload if isinstance(payload, dict) and payload else None\n<span class=\"ln\">100</span>    risk = decode(row.get(&quot;risk_json&quot;), {}) or {}\n<span class=\"ln\">101</span>    ids = decode(row.get(&quot;evidence_ids_json&quot;), [])\n<span class=\"ln\">102</span>    ids = ids if isinstance(ids, list) else []\n<span class=\"ln\">103</span>    resolved = _resolve(ids) if resolved is None else resolved\n<span class=\"ln\">104</span>    papers = [{k: v for k, v in p.items() if k != &quot;vector&quot;} for p in resolved.get(&quot;found&quot;, [])]\n<span class=\"ln\">105</span>    demo = row.get(&quot;model_version&quot;) == &quot;demo-history-seed&quot;\n<span class=\"ln\">106</span>    simulated = str(row.get(&quot;patient_id&quot;, &quot;&quot;)).startswith(&quot;bed_sim_&quot;)\n<span class=\"ln\">107</span>    checks, findings = [], []\n<span class=\"ln\">108</span>\n<span class=\"ln\">109</span>    def check(name, status, detail):\n<span class=\"ln\">110</span>        checks.append({&quot;name&quot;: name, &quot;status&quot;: status, &quot;detail&quot;: detail})\n<span class=\"ln\">111</span>\n<span class=\"ln\">112</span>    def finding(code, field, quote, explanation, correction, severity=&quot;warning&quot;):\n<span class=\"ln\">113</span>        if not any(f[&quot;code&quot;] == code and f[&quot;field&quot;] == field for f in findings):\n<span class=\"ln\">114</span>            findings.append(dict(code=code, field=field, quote=quote, explanation=explanation,\n<span class=\"ln\">115</span>                                 correction=correction, severity=severity))\n<span class=\"ln\">116</span>\n<span class=\"ln\">117</span>    missing = [k for k in REQUIRED_FIELDS if not isinstance(report, dict) or not isinstance(report.get(k), str)]\n<span class=\"ln\">118</span>    check(&quot;15개 필수 항목&quot;, &quot;fail&quot; if missing else &quot;pass&quot;, &quot;누락·형식 오류: &quot; + &quot;, &quot;.join(missing) if missing else &quot;15개 항목이 문자열로 저장되어 있습니다.&quot;)\n<span class=\"ln\">119</span>    check(&quot;작성 당시 입력&quot;, &quot;pass&quot; if payload else &quot;limited&quot;,\n<span class=\"ln\">120</span>          &quot;작성 요청에 사용한 입력이 보존되어 있습니다.&quot; if payload else &quot;당시 입력이 없어 현재 환자 정보로 소급 검증하지 않습니다.&quot;)\n<span class=\"ln\">121</span>    if payload:\n<span class=\"ln\">122</span>        owner = (payload.get(&quot;환자_프로필&quot;) or {}).get(&quot;bed_id&quot;)\n<span class=\"ln\">123</span>        check(&quot;환자 일치&quot;, &quot;pass&quot; if owner == row.get(&quot;patient_id&quot;) else &quot;fail&quot;, &quot;리포트 환자 ID와 작성 입력의 환자 ID를 비교했습니다.&quot;)\n<span class=\"ln\">124</span>\n<span class=\"ln\">125</span>    levels = risk.get(&quot;component_levels&quot;)\n<span class=\"ln\">126</span>    if isinstance(levels, dict):\n<span class=\"ln\">127</span>        expected = {k: SCORES[v] for k, v in levels.items() if v in SCORES}\n<span class=\"ln\">128</span>        score = max(expected.values()) if expected else None\n<span class=\"ln\">129</span>        conf = round(len(expected) / 3, 2) if expected else None\n<span class=\"ln\">130</span>        ok = (_same(row.get(&quot;risk_score&quot;), score) and _same(risk.get(&quot;combined_risk_score&quot;), score)\n<span class=\"ln\">131</span>              and risk.get(&quot;component_scores&quot;) == expected)\n<span class=\"ln\">132</span>        check(&quot;위험점수 계산&quot;, &quot;pass&quot; if ok else &quot;fail&quot;, f&quot;저장된 신호별 단계의 최댓값: {score}; 저장 점수: {row.get(&#x27;risk_score&#x27;)}. 낙상 확률이 아닙니다.&quot;)\n<span class=\"ln\">133</span>        check(&quot;신호 확보 비율&quot;, &quot;pass&quot; if _same(row.get(&quot;confidence&quot;), conf) else &quot;fail&quot;,\n<span class=\"ln\">134</span>              f&quot;확보 신호 {len(expected)}/3개 → {conf}; 저장값: {row.get(&#x27;confidence&#x27;)}. AI 정확도가 아닙니다.&quot;)\n<span class=\"ln\">135</span>        if payload:\n<span class=\"ln\">136</span>            # Recalculate from saved sensor facts, never from today&#x27;s live readings.\n<span class=\"ln\">137</span>            from integrated_analysis import compute_risk_score\n<span class=\"ln\">138</span>            recalculated = compute_risk_score({&quot;tof_behavior&quot;: payload.get(&quot;ToF_현재_판정&quot;), &quot;mmw_latest&quot;: payload.get(&quot;mmWave_현재_판정&quot;)})\n<span class=\"ln\">139</span>            check(&quot;센서 입력과 판정 일치&quot;, &quot;pass&quot; if recalculated == risk and payload.get(&quot;계산된_위험점수&quot;) == risk else &quot;fail&quot;,\n<span class=\"ln\">140</span>                  &quot;보존된 ToF·mmWave 입력으로 현재 계산 규칙을 다시 적용해 저장된 판정과 비교했습니다.&quot;)\n<span class=\"ln\">141</span>    else:\n<span class=\"ln\">142</span>        check(&quot;점수 계산 재현&quot;, &quot;limited&quot;, &quot;신호별 판정 근거가 저장되어 있지 않습니다.&quot;)\n<span class=\"ln\">143</span>\n<span class=\"ln\">144</span>    missing_ids = resolved.get(&quot;missing_chunk_ids&quot;, [])\n<span class=\"ln\">145</span>    if not resolved.get(&quot;success&quot;):\n<span class=\"ln\">146</span>        check(&quot;문헌 ID 연결&quot;, &quot;limited&quot;, &quot;문헌 저장소 조회 실패. 인용 내용은 확인하지 못했습니다.&quot;)\n<span class=\"ln\">147</span>    elif missing_ids:\n<span class=\"ln\">148</span>        check(&quot;문헌 ID 연결&quot;, &quot;fail&quot;, &quot;찾을 수 없는 근거: &quot; + &quot;, &quot;.join(map(str, missing_ids)))\n<span class=\"ln\">149</span>    else:\n<span class=\"ln\">150</span>        check(&quot;문헌 ID 연결&quot;, &quot;pass&quot; if ids else &quot;limited&quot;, f&quot;저장된 근거 {len(ids)}개를 찾았습니다. ID가 있다는 것만으로 주장이 증명되지는 않습니다.&quot; if ids else &quot;연결된 문헌 ID가 없습니다.&quot;)\n<span class=\"ln\">151</span>\n<span class=\"ln\">152</span>    supplied = (payload or {}).get(&quot;검색된_논문_근거&quot;, [])\n<span class=\"ln\">153</span>    identity_only = (supplied and all(p.get(&quot;구간&quot;) == &quot;identity&quot; for p in supplied)) if payload else (papers and all(p.get(&quot;section&quot;) == &quot;identity&quot; for p in papers))\n<span class=\"ln\">154</span>    if identity_only:\n<span class=\"ln\">155</span>        check(&quot;문헌 내용의 충분성&quot;, &quot;limited&quot;, &quot;연결된 자료가 제목·저자 등 서지정보뿐입니다. 연구 결과나 투약 판단의 직접 근거로 충분하지 않습니다.&quot;)\n<span class=\"ln\">156</span>    if payload and not ((payload.get(&quot;논문_근거_충분성_판단&quot;) or {}).get(&quot;sufficient&quot;)):\n<span class=\"ln\">157</span>        check(&quot;검색 근거 충분성&quot;, &quot;limited&quot;, &quot;문헌 조사 단계에서 근거가 충분하다고 확인하지 못했습니다.&quot;)\n<span class=\"ln\">158</span>\n<span class=\"ln\">159</span>    if not isinstance(report, dict):\n<span class=\"ln\">160</span>        report = {}\n<span class=\"ln\">161</span>    if payload:\n<span class=\"ln\">162</span>        cited = re.findall(r&quot;\\[근거:\\s*([^\\]]+)\\]&quot;, report.get(&quot;관련_연구_근거&quot;, &quot;&quot;))\n<span class=\"ln\">163</span>        supplied_ids = {p.get(&quot;문헌_ID&quot;) for p in supplied if p.get(&quot;문헌_ID&quot;)}\n<span class=\"ln\">164</span>        unknown = [c.strip() for c in cited if c.strip() not in supplied_ids]\n<span class=\"ln\">165</span>        if unknown:\n<span class=\"ln\">166</span>            finding(&quot;unknown_citation&quot;, &quot;관련_연구_근거&quot;, report.get(&quot;관련_연구_근거&quot;, &quot;&quot;), &quot;실제 작성 입력에 없는 문헌 ID를 인용했습니다: &quot; + &quot;, &quot;.join(unknown), &quot;실제 전달된 문헌 ID와 해당 문단의 내용만 인용해야 합니다.&quot;, &quot;error&quot;)\n<span class=\"ln\">167</span>        if supplied_ids and not cited:\n<span class=\"ln\">168</span>            check(&quot;문장별 근거 표시&quot;, &quot;limited&quot;, &quot;실제 문헌 ID를 붙인 인용이 없어 설명과 근거의 대응을 직접 확인해야 합니다.&quot;)\n<span class=\"ln\">169</span>        previous = payload.get(&quot;직전_분석_기록&quot;)\n<span class=\"ln\">170</span>        previous_text = report.get(&quot;과거_데이터와의_비교&quot;, &quot;&quot;)\n<span class=\"ln\">171</span>        if previous and re.search(r&quot;직전 분석 기록[이은 는]*없&quot;, previous_text):\n<span class=\"ln\">172</span>            finding(&quot;previous_report_denied&quot;, &quot;과거_데이터와의_비교&quot;, previous_text, &quot;작성 입력에 직전 리포트가 있는데 없다고 서술했습니다.&quot;, &quot;직전 기록의 시각과 점수를 비교하되 원시 관측 이력의 한계는 별도로 설명해야 합니다.&quot;, &quot;error&quot;)\n<span class=\"ln\">173</span>        raw_speed = ((payload.get(&quot;mmWave_현재_판정&quot;) or {}).get(&quot;raw&quot;) or {}).get(&quot;speed&quot;)\n<span class=\"ln\">174</span>        for field in (&quot;보행_변화&quot;, &quot;mmWave_변화&quot;):\n<span class=\"ln\">175</span>            text = report.get(field, &quot;&quot;)\n<span class=\"ln\">176</span>            if not re.search(r&quot;직전|이전|과거&quot;, text) and isinstance(raw_speed, (int, float)):\n<span class=\"ln\">177</span>                claimed = re.findall(r&quot;보행\\s*속도(?:는|가|:)?\\s*(\\d+(?:\\.\\d+)?)&quot;, text)\n<span class=\"ln\">178</span>                if any(not _same(float(speed), raw_speed) for speed in claimed):\n<span class=\"ln\">179</span>                    finding(&quot;speed_mismatch&quot;, field, text, f&quot;작성 입력의 보행 속도는 {raw_speed}m/s입니다. 보행 감지 여부를 이유로 숫자를 바꾸면 안 됩니다.&quot;, f&quot;센서 속도값은 {raw_speed}m/s입니다. 걷는 신호가 있는지는 별도 판정입니다.&quot;, &quot;error&quot;)\n<span class=\"ln\">180</span>        tof_text = report.get(&quot;ToF_변화&quot;, &quot;&quot;)\n<span class=\"ln\">181</span>        if isinstance(levels, dict) and levels.get(&quot;tof_posture&quot;) in (&quot;caution&quot;, &quot;warning&quot;, &quot;critical&quot;) and re.search(r&quot;위험\\s*(?:상태|단계|수준)[는이가 ]*[&#x27;\\&quot;]?정상&quot;, tof_text):\n<span class=\"ln\">182</span>            finding(&quot;tof_level_mismatch&quot;, &quot;ToF_변화&quot;, tof_text, &quot;최종 ToF 단계는 정상이 아닙니다. 이진 이상감지 상태와 위험 단계를 혼동한 표현입니다.&quot;, &quot;계산된 위험점수의 ToF 단계에 맞게 설명해야 합니다.&quot;, &quot;error&quot;)\n<span class=\"ln\">183</span>        for field in (&quot;최근_변화&quot;, &quot;활동_변화&quot;):\n<span class=\"ln\">184</span>            text = report.get(field, &quot;&quot;)\n<span class=\"ln\">185</span>            if re.search(r&quot;(?:기록|이벤트).{0,12}없&quot;, text) and re.search(r&quot;변화[는가 ]*없&quot;, text):\n<span class=\"ln\">186</span>                finding(&quot;no_records_as_no_change&quot;, field, text, &quot;기록이 없다는 사실은 변화가 없다는 증거가 아닙니다.&quot;, &quot;변화 여부를 판단할 관측 자료가 부족합니다.&quot;)\n<span class=\"ln\">187</span>        if not supplied and not re.search(r&quot;정보 부족|근거.{0,8}(없|부족)|제시.{0,8}(없|않)&quot;, report.get(&quot;관련_연구_근거&quot;, &quot;&quot;)):\n<span class=\"ln\">188</span>            finding(&quot;no_supplied_evidence&quot;, &quot;관련_연구_근거&quot;, report.get(&quot;관련_연구_근거&quot;, &quot;&quot;), &quot;검색된 문헌이 입력에 없는데 연구 결과를 서술했습니다.&quot;, &quot;이번 작성에 전달된 문헌 근거가 없다고 표시해야 합니다.&quot;, &quot;error&quot;)\n<span class=\"ln\">189</span>        observed_count = (payload.get(&quot;최근_24시간_활동_요약&quot;) or {}).get(&quot;n_events&quot;)\n<span class=\"ln\">190</span>        for field in (&quot;최근_변화&quot;, &quot;활동_변화&quot;):\n<span class=\"ln\">191</span>            text = report.get(field, &quot;&quot;)\n<span class=\"ln\">192</span>            if &quot;24시간&quot; not in text:\n<span class=\"ln\">193</span>                continue\n<span class=\"ln\">194</span>            counts = [int(n) for n in re.findall(r&quot;(\\d+)\\s*건&quot;, text)]\n<span class=\"ln\">195</span>            if isinstance(observed_count, int) and any(n &gt; observed_count for n in counts):\n<span class=\"ln\">196</span>                finding(&quot;event_count_mismatch&quot;, field, text, f&quot;입력의 최근 24시간 이벤트는 {observed_count}건인데 더 많은 건수를 서술했습니다.&quot;, &quot;보존된 집계와 시간 범위를 기준으로 다시 작성해야 합니다.&quot;, &quot;error&quot;)\n<span class=\"ln\">197</span>            try:\n<span class=\"ln\">198</span>                at = datetime.fromisoformat(payload[&quot;분석_시점&quot;].replace(&quot;Z&quot;, &quot;+00:00&quot;))\n<span class=\"ln\">199</span>                dates = re.findall(r&quot;(20\\d{2})[-년]\\s*(\\d{1,2})[-월]\\s*(\\d{1,2})&quot;, text)\n<span class=\"ln\">200</span>                if any((at.date() - datetime(int(y), int(m), int(d)).date()).days &gt; 2 for y, m, d in dates) and not re.search(r&quot;24시간 이전|과거 기록|오래된&quot;, text):\n<span class=\"ln\">201</span>                    finding(&quot;old_event_as_current&quot;, field, text, &quot;분석일보다 여러 날 이전의 사건을 최근 24시간 사건처럼 서술했습니다.&quot;, &quot;과거 사건과 이번 관측 기간을 분리해야 합니다.&quot;, &quot;error&quot;)\n<span class=\"ln\">202</span>            except (KeyError, ValueError, TypeError):\n<span class=\"ln\">203</span>                pass\n<span class=\"ln\">204</span>    medication_text = report.get(&quot;투약_조정_제안&quot;, &quot;&quot;)\n<span class=\"ln\">205</span>    for sentence in re.split(r&quot;(?&lt;=[.!?])\\s+|\\n&quot;, medication_text):\n<span class=\"ln\">206</span>        if re.search(r&quot;감량|증량|중단|유지.{0,8}적절&quot;, sentence) and not re.search(r&quot;판단.{0,8}(불가|없|않)|결정.{0,8}(없|않)|근거.{0,8}부족|단정.{0,8}(없|않)&quot;, sentence):\n<span class=\"ln\">207</span>            finding(&quot;medication_direction&quot;, &quot;투약_조정_제안&quot;, sentence, &quot;개별 약의 조정 방향을 제시하고 있습니다. 센서 위험점수와 일반 논문만으로는 환자별 적절성을 확인할 수 없습니다.&quot;, &quot;복용 목적·실제 복용·증상 등을 의료진이 검토해야 하며, 현재 자료만으로 조정 방향은 판단할 수 없습니다.&quot;)\n<span class=\"ln\">208</span>    if simulated and not demo and &quot;시뮬레이션&quot; not in report.get(&quot;현재_상태&quot;, &quot;&quot;):\n<span class=\"ln\">209</span>        finding(&quot;simulation_not_declared&quot;, &quot;현재_상태&quot;, report.get(&quot;현재_상태&quot;, &quot;&quot;), &quot;가상 환자·가상 센서임이 첫 항목에 명시되어 있지 않습니다.&quot;, &quot;시뮬레이션 기반 리포트임을 먼저 표시해야 합니다.&quot;)\n<span class=\"ln\">210</span>    for field, value in report.items():\n<span class=\"ln\">211</span>        if not isinstance(value, str):\n<span class=\"ln\">212</span>            continue\n<span class=\"ln\">213</span>        for sentence in re.split(r&quot;(?&lt;=[.!?])\\s+|\\n&quot;, value):\n<span class=\"ln\">214</span>            cautious = re.search(r&quot;단정.{0,8}(없|않)|판단.{0,8}(없|않)|의미하지|아닙니다|구분해야|확인.{0,5}필요&quot;, sentence)\n<span class=\"ln\">215</span>            if re.search(r&quot;보행[이가은 는]*불가능|걸을 수 없&quot;, sentence) and not cautious:\n<span class=\"ln\">216</span>                finding(&quot;walking_incapacity&quot;, field, sentence, &quot;보행 신호가 없는 것과 걸을 능력이 없는 것은 다릅니다. 이 표현은 원문 근거 확인이 필요합니다.&quot;, &quot;지금 걷는 신호가 관측되지 않았습니다. 보행 가능 여부는 별도 평가가 필요합니다.&quot;)\n<span class=\"ln\">217</span>            if re.search(r&quot;낙상.{0,28}(발생하지 않았|없었|없습니다|없음)&quot;, sentence) and not re.search(r&quot;기록|저장|보고|확인되지|판단|단정&quot;, sentence):\n<span class=\"ln\">218</span>                finding(&quot;unobserved_fall_absence&quot;, field, sentence, &quot;로그가 없다는 사실만으로 실제 낙상이 없었다고 확정할 수 없습니다.&quot;, &quot;해당 기간에 저장된 낙상 이벤트가 없습니다. 실제 발생 여부는 이 자료만으로 확인할 수 없습니다.&quot;)\n<span class=\"ln\">219</span>            if re.search(r&quot;신뢰.{0,12}(수준|정보|데이터)&quot;, sentence) and re.search(r&quot;0\\.67|67\\s*%&quot;, sentence) and not cautious:\n<span class=\"ln\">220</span>                finding(&quot;availability_as_accuracy&quot;, field, sentence, &quot;0.67은 3개 판정 신호 중 2개 확보를 뜻합니다. 내용의 정확성을 측정한 값이 아닙니다.&quot;, &quot;판정 신호 3개 중 2개를 확보했습니다. 리포트 정확도는 별도로 검토해야 합니다.&quot;)\n<span class=\"ln\">221</span>            if re.search(r&quot;활동이 없었|활동은 없&quot;, sentence) and not re.search(r&quot;기록|이벤트|저장|관측|현재&quot;, sentence):\n<span class=\"ln\">222</span>                finding(&quot;no_events_as_inactivity&quot;, field, sentence, &quot;이벤트가 기록되지 않은 기간을 실제 활동이 없었던 기간으로 단정할 수 없습니다.&quot;, &quot;저장된 활동 이벤트가 없습니다. 활동량 전체를 판단할 자료는 부족합니다.&quot;)\n<span class=\"ln\">223</span>\n<span class=\"ln\">224</span>    for c in checks:\n<span class=\"ln\">225</span>        if c[&quot;status&quot;] == &quot;fail&quot;:\n<span class=\"ln\">226</span>            finding(&quot;check_failed&quot;, c[&quot;name&quot;], &quot;&quot;, c[&quot;detail&quot;], &quot;원자료와 계산·저장 경로를 확인한 후 다시 작성해야 합니다.&quot;, &quot;error&quot;)\n<span class=\"ln\">227</span>    status = &quot;demo_example&quot; if demo else &quot;needs_review&quot; if findings else &quot;limited&quot; if any(c[&quot;status&quot;] == &quot;limited&quot; for c in checks) else &quot;checks_passed&quot;\n<span class=\"ln\">228</span>    return {&quot;version&quot;: VERSION, &quot;analysis_id&quot;: row[&quot;id&quot;], &quot;patient_id&quot;: row.get(&quot;patient_id&quot;),\n<span class=\"ln\">229</span>            &quot;content_hash&quot;: content_hash(row), &quot;reviewed_at&quot;: datetime.now(timezone.utc).isoformat(),\n<span class=\"ln\">230</span>            &quot;status&quot;: status, &quot;label&quot;: LABELS[status], &quot;scope&quot;: SCOPE,\n<span class=\"ln\">231</span>            &quot;checks&quot;: checks, &quot;findings&quot;: findings, &quot;evidence&quot;: papers,\n<span class=\"ln\">232</span>            &quot;evidence_note&quot;: &quot;문헌 저장소에서 조회한 근거입니다. 당시 모델에 전달된 문단은 아래 작성 입력에서 별도로 확인하세요.&quot;,\n<span class=\"ln\">233</span>            &quot;input_available&quot;: payload is not None, &quot;direct_review&quot;: None}</pre></details></details>\n</section><section class=\"part\" id=\"lab\" hidden><div class=\"part-head\"><a href=\"#home\" class=\"back\">← 전체 지도</a><h2>8. 실험 코드와 아직 안 쓰는 것</h2><p class=\"sub\">운영 경로에 연결 안 된 AI — 헷갈리지 않게</p></div>\n<table><thead><tr><th>이름</th><th>무엇</th><th>상태</th></tr></thead><tbody><tr><td><a class=\"ref\" href=\"../server/maintenance_ai.py\" title=\"server/maintenance_ai.py\">server/maintenance_ai.py</a></td><td>ADWIN 방식 평균 변화 감시(값의 분포가 바뀌었나)</td><td>테스트용 — 운영에서 import 안 함. 자동 재학습 없음</td></tr><tr><td><a class=\"ref\" href=\"../server/analysis_kb.py\" title=\"server/analysis_kb.py\">server/analysis_kb.py</a></td><td>과거 AI 리포트를 벡터화해 비슷한 사례 찾기</td><td>인덱스는 있으나(7조각) 리포트 작성 흐름에 연결 안 됨</td></tr><tr><td><a class=\"ref\" href=\"../TOF/ml/compare_rf_tabpfn.py\" title=\"TOF/ml/compare_rf_tabpfn.py\">TOF/ml/compare_rf_tabpfn.py</a></td><td>자세 분류 Random Forest vs TabPFN 비교</td><td>연구용</td></tr><tr><td><a class=\"ref\" href=\"../research/alternatives/README.md\" title=\"research/alternatives/README.md\">research/alternatives/README.md</a></td><td>후보 알고리즘·검색 평가</td><td>연구용, 운영과 분리</td></tr><tr><td>mmWave/exit_seq/</td><td>침상 이탈 시퀀스 학습 실험(LSTM 등)</td><td>예전 설치 기준 실험</td></tr></tbody></table>\n<div class=\"warn\"><b>한계·주의</b> 실험 코드의 수치를 운영 성능으로 인용하지 않는다. 운영에 넣으려면 실측 시험과 테스트를 먼저 만든다.</div>\n</section><section class=\"part\" id=\"ops\" hidden><div class=\"part-head\"><a href=\"#home\" class=\"back\">← 전체 지도</a><h2>9. 실행·시험·바꿀 때 체크리스트</h2><p class=\"sub\">신입이 처음 손댈 때 보는 곳</p></div>\n<details class=\"step\"><summary><span class=\"num\">9-1</span>다시 학습·다시 만들기</summary><div class=\"plain\"><table><thead><tr><th>무엇</th><th>명령</th></tr></thead><tbody><tr><td>자세 모델 평가만</td><td>cd TOF/ml && ../../.venv/bin/python train_posture_v2.py --group subject --no-save</td></tr><tr><td>자세 모델 학습·교체</td><td>기존 모델을 TOF/ml/archive/에 복사 → train_posture_v2.py --group subject → tof_server 재시작</td></tr><tr><td>논문 인덱스 다시 만들기</td><td>.venv/bin/python -c 'import sys;sys.path.insert(0,\"server\");import paper_kb;print(paper_kb.build_index(force=True))'</td></tr><tr><td>이 가이드 다시 만들기</td><td>.venv/bin/python tools/build_ai_guide.py</td></tr></tbody></table></div></details>\n<details class=\"step\"><summary><span class=\"num\">9-2</span>자동 테스트</summary><div class=\"plain\"><table><thead><tr><th>파일</th><th>무엇을 지키나</th></tr></thead><tbody><tr><td>server/test_patient_report_context.py</td><td>리포트 입력·형식 검사·환자 분리</td></tr><tr><td>server/test_report_review.py</td><td>자동 검토 규칙</td></tr><tr><td>server/test_fall_report.py</td><td>원인 후보 규칙·LLM 실패 시 대체 저장</td></tr><tr><td>server/test_gait_prior.py</td><td>기대 범위·인용 검증</td></tr><tr><td>server/test_gait_trend.py</td><td>칼만 추세·신호 기준</td></tr><tr><td>server/test_emr_kb.py</td><td>환자별 EMR 벡터 분리</td></tr><tr><td>mmWave/tests/test_fall_detect.py</td><td>낙상 규칙(AI 아님)·실측 재생</td></tr></tbody></table></div></details>\n<details class=\"step\"><summary><span class=\"num\">9-3</span>바꿀 때 지킬 것</summary><div class=\"plain\"><ul><li>LLM에게 숫자를 만들게 하지 않는다 — 새 수치는 서버 함수로 계산해 입력에 넣는다.</li><li>프롬프트를 바꾸면 PROMPT_VERSION을 올린다(저장된 리포트와 구분).</li><li>모델을 바꾸면 이전 모델을 archive/에 남기고, 사람 단위(LOSO) 성능을 같이 적는다.</li><li>키·환자 이름을 로그·문서에 남기지 않는다(.env는 저장소 제외).</li><li>시뮬레이션 환자와 실측 환자(bed_01)를 섞지 않는다.</li></ul></div></details>\n</section>\n</div><script>\nconst parts=[...document.querySelectorAll('.part')];\nfunction route(){const id=(location.hash||'#home').slice(1);const home=document.getElementById('home');\n const hit=parts.find(p=>p.id===id);home.hidden=!!hit;parts.forEach(p=>p.hidden=p!==hit);window.scrollTo(0,0);}\naddEventListener('hashchange',route);route();\ndocument.getElementById('theme').onclick=()=>{const r=document.documentElement;r.dataset.theme=r.dataset.theme==='dark'?'light':'dark';};\ndocument.getElementById('openall').onclick=()=>document.querySelectorAll('.part:not([hidden]) details').forEach(d=>d.open=true);\n</script></body></html>";
